export default {"sections":[{"id":1,"title":"Древнерусская мысль и XVIII век","count":295,"topics":["Иларион. «Слово о Законе и Благодати»","Нил Сорский. «Устав о скитской жизни»","Иосиф Волоцкий. «Просветитель»","Федотов. «Святые Древней Руси»","Радищев. «О человеке, о его смертности и бессмертии»","Флоровский. «Пути русского богословия»: древняя Русь","Зеньковский. «История русской философии»: до XIX века"]},{"id":2,"title":"Чаадаев и славянофилы","count":345,"topics":["Чаадаев. «Апология сумасшедшего»","Хомяков. «Церковь одна»","Хомяков. «О старом и новом»","Киреевский. «О характере просвещения Европы»","Киреевский. «О необходимости и возможности новых начал для философии»","К. С. Аксаков. «О внутреннем состоянии России»","Чаадаев. «Философические письма»","Гоголь. «Выбранные места из переписки с друзьями»"]},{"id":3,"title":"Западники, революционная и народническая мысль","count":75,"topics":["Белинский. «Письмо Н. В. Гоголю»","Герцен. «Письма об изучении природы»"]},{"id":4,"title":"Почвенничество и консерватизм","count":0,"topics":[]},{"id":5,"title":"Достоевский и Толстой","count":0,"topics":[]},{"id":6,"title":"Академическая философия XIX века","count":0,"topics":[]},{"id":7,"title":"Владимир Соловьёв","count":0,"topics":[]},{"id":8,"title":"Серебряный век и «Вехи»","count":0,"topics":[]},{"id":9,"title":"Бердяев","count":0,"topics":[]},{"id":10,"title":"Булгаков и Флоренский","count":0,"topics":[]},{"id":11,"title":"Франк, Лосский, Ильин","count":0,"topics":[]},{"id":12,"title":"Эмиграция и евразийство","count":0,"topics":[]},{"id":13,"title":"Русский космизм","count":0,"topics":[]},{"id":14,"title":"Марксизм в России","count":0,"topics":[]},{"id":15,"title":"Советская философия","count":0,"topics":[]},{"id":16,"title":"Историки русской философии","count":0,"topics":[]}],"books":[{"key":"ilarion_slovo","author":"Иларион Киевский","title":"Слово о Законе и Благодати","year":"ок. 1049","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/"},{"key":"nil_ustav","author":"Нил Сорский","title":"Устав о скитской жизни","year":"кон. XV — нач. XVI в.","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/"},{"key":"iosif_prosvetitel","author":"Иосиф Волоцкий","title":"Просветитель","year":"нач. XVI в.","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/"},{"key":"radishchev_o_cheloveke","author":"А. Н. Радищев","title":"О человеке, о его смертности и бессмертии","year":"1792","url":""},{"key":"fedotov_svyatye","author":"Г. П. Федотов","title":"Святые Древней Руси","year":"1931","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/"},{"key":"chaadaev_pisma","author":"П. Я. Чаадаев","title":"Философические письма","year":"1829–1831","url":"http://www.vehi.net/chaadaev/filpisma.html"},{"key":"chaadaev_apologiya","author":"П. Я. Чаадаев","title":"Апология сумасшедшего","year":"1837","url":"http://www.vehi.net/chaadaev/apologiya.html"},{"key":"khomyakov_staroe","author":"А. С. Хомяков","title":"О старом и новом","year":"1839","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml"},{"key":"khomyakov_cerkov","author":"А. С. Хомяков","title":"Церковь одна","year":"1840-е","url":"http://www.vehi.net/khomyakov/cerkov.html"},{"key":"kireevsky_prosveshchenie","author":"И. В. Киреевский","title":"О характере просвещения Европы и о его отношении к просвещению России","year":"1852","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/"},{"key":"kireevsky_novye_nachala","author":"И. В. Киреевский","title":"О необходимости и возможности новых начал для философии","year":"1856","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/"},{"key":"aksakov_zapiska","author":"К. С. Аксаков","title":"О внутреннем состоянии России","year":"1855","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml"},{"key":"gogol_vybrannye","author":"Н. В. Гоголь","title":"Выбранные места из переписки с друзьями","year":"1847","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml"},{"key":"belinsky_pismo","author":"В. Г. Белинский","title":"Письмо к Гоголю","year":"1847","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml"},{"key":"herzen_pisma_priroda","author":"А. И. Герцен","title":"Письма об изучении природы","year":"1845–1846","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml"},{"key":"florovsky_puti","author":"Г. В. Флоровский","title":"Пути русского богословия","year":"1937","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/"},{"key":"zenkovsky_istoriya","author":"В. В. Зеньковский","title":"История русской философии","year":"1948–1950","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/"}],"questions":[{"id":"rf8cab65fca","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Кого Иларион называет образом Закона и Благодати?","options":["Агарь и Сарру","Лию и Рахиль","Еву и Марию","Марфу и Марию"],"explanation":"По Илариону, «раба Агарь и свободная Сарра» — образы Закона и Благодати: раба прежде, свободная потом. Лия и Рахиль, Ева и Мария, Марфа и Мария в этом толковании не участвуют.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Образ же Закона и Благодати – Агарь и Сарра"}]},{"id":"r646bd6d81d","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Кого из сыновей Авраама Иларион соотносит с Законом, принесённым Моисеем с Синая?","options":["Измаила","Исаака","Мадиама","Шуаха"],"explanation":"Сын рабыни Агари Измаил у Илариона соответствует Закону, а сын свободной Исаак — Благодати. Мадиам и Шуах — сыновья Авраама от Хеттуры, о них в «Слове» речи нет.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"И нарек Авраам имя ему Измаил. Принес же и Моисей от горы Синайской Закон"}]},{"id":"r8b75165a8e","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Как Иларион определяет отношение Закона к Благодати и Истине?","options":["Закон — предтеча и слуга Благодати","Благодать — награда за исполнение Закона","Закон — кара за отвержение Благодати","Закон — ложное учение, враждебное Благодати"],"explanation":"Иларион называет Закон предтечей и слугой Благодати и Истины: он готовил человечество к Крещению. Ни наградой, ни карой, ни ложным учением Закон у него не назван.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Ибо Закон – предтеча и слуга Благодати и Истины"}]},{"id":"r6599d8e287","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что, по Илариону, давал иудеям Закон в отличие от христианской Благодати?","options":["оправдание, но не спасение","спасение, но не оправдание","мудрость, но не праведность","надежду, но не любовь"],"explanation":"Иларион различает: иудеи Законом оправдывались, но не спасались, а христиане Благодатью спасаются. Оправдание у него относится к этому миру, спасение — к Будущему Веку.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Ибо у иудеев – оправдание, у христиан же – спасение"}]},{"id":"rc157a10f3d","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"С каким явлением природы Иларион сравнивает отход Закона, когда явилась Благодать?","options":["со светом луны, когда восходит солнце","с ветхой одеждой, сменённой на новую","с ручьём, который теряется в море","с семенем, которое умирает в земле"],"explanation":"По Илариону, Закон отошёл, как отходит свет луны, когда воссияло солнце, и как сгинула ночная стужа от солнечного тепла. Образы одежды, ручья и семени он здесь не использует.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Ибо отошел свет луны, когда солнце воссияло"}]},{"id":"r040db43adf","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Каким словом Иларион обозначает Закон в противоположность Истине?","options":["тень","пестун","ярмо","печать"],"explanation":"«Прежде Закон, потом Благодать; прежде тень, потом Истина» — Закон у Илариона есть тень будущей Истины. Слово «пестун» (детоводитель) восходит к апостолу Павлу, «ярмо» и «печать» — не термины Илариона для Закона.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Прежде Закон, потом Благодать; прежде тень, потом Истина"}]},{"id":"r06a2a86f3d","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Как Иларион объясняет то, что Сарра долго не рождала?","options":["её затворил Божий Промысл до старости","так она была наказана за смех над обетованием","это была кара за гнев на рабыню Агарь","так испытывалась вера Авраама"],"explanation":"По Илариону, Сарра «не (вовсе) была неплодна», но была заключена Божиим Промыслом, чтобы родить в старости: так тайна Благодати была утаена до конца веков. Наказание, кара и испытание здесь ни при чём.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"но заключена была Божиим Промыслом"}]},{"id":"r03748d347f","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Как, по Илариону, живёт человечество под Благодатью в сравнении с жизнью под Законом?","options":["свободно ходит, а не теснится","спасается, а не оправдывается","знает Бога, но не видит Его","постится, но не приносит жертв"],"explanation":"Иларион пишет, что человечество уже не теснится в Законе, но в Благодати свободно ходит. Вариант «спасается, а не оправдывается» описывает различие иудеев и христиан, а не тесноту и свободу.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"И уже не теснится в Законе человечество, но в Благодати свободно ходит"}]},{"id":"r7c1e1bc750","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Каким евангельским изречением Иларион объясняет, почему учение Христа приняли язычники, а не иудеи?","options":["о вине, которое не вливают в ветхие мехи","о закваске, положенной в три меры муки","о горчичном зерне, ставшем деревом","о семени, упавшем на каменистую почву"],"explanation":"Иларион говорит, что вино благодатного учения не вливают в ветхие мехи, «обветшавшие в иудействе»: новое учение — в новые мехи, новые народы. Притчи о закваске, горчичном зерне и сеятеле он здесь не приводит.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Но новое учение – в новые мехи, новые народы"}]},{"id":"r1e94fdba06","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Каким ветхозаветным образом Иларион показывает, что вера прежде была в одном Израиле, а теперь по всей земле?","options":["росой на руне Гедеона","расцветшим жезлом Аарона","медным змеем в пустыне","лестницей Иакова"],"explanation":"Иларион вспоминает знамение Гедеона: сначала роса была только на руне, а по всей земле сушь, потом наоборот. Так и вера прежде была в одной Иудее, а затем распространилась по всей земле.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"да будет роса на руне только, по всей же земле – сушь"}]},{"id":"r48bc47a1ab","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что, по Илариону, было отнято у иудеев, когда кончилось иудейство и Закон отошёл?","options":["ковчег, скрижали и очистилище","субботы, посты и праздники","обрезание, Пасха и десятина","пророки, цари и судьи"],"explanation":"Иларион пишет: «Жертвы не приняты, ковчег и скрижали, и очистилище отнято». Субботы, обрезание или пророков он в этом месте не перечисляет.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Жертвы не приняты, ковчег и скрижали, и очистилище отнято"}]},{"id":"r29b46c4042","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что Иларион утверждает о Христе в ряду противопоставлений «Как человек… — и как Бог…»?","options":["Он совершенный человек и совершенный Бог","Он человек, усыновлённый Богом при Крещении","Его человечество было лишь призрачным","Его Божество поглотило человечество"],"explanation":"Иларион исповедует Христа совершенным человеком «по вочеловечению, а не призраком» и совершенным Богом по Божеству. Усыновление при Крещении, призрачное тело и поглощение человечества Божеством — учения, которые Церковь отвергла как ереси.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Совершенный человек по вочеловечению, а не призрак"}]},{"id":"r63480899ec","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Какого пророка Иларион цитирует словами «Нет Мне нужды в сынах Израилевых»?","options":["Малахию","Аггея","Захарию","Иоиля"],"explanation":"Иларион приводит слова «через пророка Малахию»: от востока и запада Имя Божие славится в народах, а жертвы Израиля не приняты. Аггей, Захария и Иоиль — тоже малые пророки, но эти слова принадлежат Малахии.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Нет Мне нужды в сынах Израилевых, и жертвы от рук их не приму"}]},{"id":"r44bd54597f","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что, согласно заглавию «Слова», следует за рассуждением о Законе и Благодати?","options":["похвала князю Владимиру и молитва","житие Бориса и Глеба и поучение","исповедание веры и поучение пастве","летопись Крещения и Символ веры"],"explanation":"В заглавии три части: о Законе и Благодати, о распространении веры до русского народа и похвале князю Владимиру, наконец молитва к Богу от всей земли. Житие, поучение и летопись в «Слово» не входят.","sources":[{"title":"Иларион. Слово о Законе и Благодати, заглавие","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"И похвала князю нашему Владимиру, которым мы крещены были"}]},{"id":"r94b8ddb337","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"К каким читателям, по словам Илариона, обращено «Слово»?","options":["к насытившимся сладости книжной","к новокрещёным простецам","к иноверцам, ищущим истины","к греческим книжникам"],"explanation":"Иларион прямо пишет, что обращается не к несведущим, а к «довольно насытившимся сладости книжной», и не к иноверным, а к сынам Божиим. О простецах и греках речь не идёт.","sources":[{"title":"Иларион. Слово о Законе и Благодати, о Законе и Благодати","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Ведь не к несведущим пишем, но к довольно насытившимся сладости книжной"}]},{"id":"r106e9dabae","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Какими словами Иларион характеризует деда и отца Владимира?","options":["Игорь «старый», Святослав «славный»","Игорь «храбрый», Святослав «грозный»","Игорь «мудрый», Святослав «великий»","Игорь «вещий», Святослав «смелый»"],"explanation":"Владимир у Илариона — «внук старого Игоря, сын же славного Святослава», прославившихся мужеством и храбростью. Прозвище «вещий» летопись даёт Олегу, а не Игорю.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"внука старого Игоря, сына же славного Святослава"}]},{"id":"r56c2d98290","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что Иларион говорит о Руси, где княжили предки Владимира?","options":["о ней знают во всех четырёх концах земли","она последней из народов приняла веру","её прежде просветил апостол Андрей","она была подвластна греческим царям"],"explanation":"Иларион подчёркивает, что предки Владимира владычествовали «не в худой и неведомой земле», а в Русской, о которой знают и слышат во всех концах земли. Об апостоле в Русской земле он говорит обратное: Владимир «не видел апостола».","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"но в Русской, о которой знают и слышат во всех четырех концах земли"}]},{"id":"re476d5f79d","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"О чём, по Илариону, Владимир постоянно слышал, прежде чем обратиться к Богу?","options":["о благоверной земле греческой","о святынях Иерусалима","о мудрости римских пап","о крещении болгарского царя"],"explanation":"Владимир, по Илариону, слышал о «благоверной земле греческой, христолюбивой и сильной верою», где Бога почитают в Троице. Об Иерусалиме, Риме и Болгарии в этом месте не говорится.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"всегда он слышал о благоверной земле греческой, христолюбивой и сильной верою"}]},{"id":"rb2b25e4c74","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Какое имя, по «Слову», Владимир принял в Крещении?","options":["Василий","Димитрий","Константин","Михаил"],"explanation":"Выйдя из купели, Владимир принял «имя вечное» — Василий. Константином звали императора, с которым Иларион его сравнивает.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"имя приняв вечное, именитое в поколениях и поколениях – Василий"}]},{"id":"r45d57a336a","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Почему, по признанию Илариона, крестились и те, кто не принимал веру по любви?","options":["из страха перед повелевшим князем","по уговору греческих священников","ради выгодной торговли с Византией","после чуда, явленного дружине"],"explanation":"Иларион признаёт, что некоторые крестились «не любовью», а «из страха (перед) повелевшим», ибо благоверие Владимира было сопряжено с властью. Уговоры, торговля и чудо здесь не упомянуты.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Да если кто и не любовью, то из страха"}]},{"id":"r7d505bef9c","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что, по описанию Илариона, появлялось на месте сокрушённых идолов?","options":["иконы святых","кресты при дорогах","мощи мучеников","книги Писания"],"explanation":"В похвале Владимиру Иларион пишет: капища разрушались, а церкви ставились, идолы сокрушались, а иконы святых являлись. Кресты, мощи и книги в этой антитезе не названы.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"идолы сокрушались, а иконы святых являлись"}]},{"id":"r6fcf40b509","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Чем, по Илариону, особенно удивительна вера Владимира?","options":["он уверовал, не видев Христа и чудес","он крестился, будучи уже старцем","он принял веру вопреки воле дружины","он уверовал после явления ангела"],"explanation":"Иларион восклицает: другие и видев не уверовали, а Владимир, не видев, уверовал — на нём сбылось слово «блаженны невидевшие и уверовавшие». Явления ангела или противодействия дружины в «Слове» нет.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Другие и видев Его не уверовали. Ты же, не видев – уверовал"}]},{"id":"r518be408c8","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"С каким императором Иларион сравнивает князя Владимира?","options":["с Константином Великим","с Юстинианом Великим","с Феодосием Великим","с Карлом Великим"],"explanation":"Владимир у Илариона «подобный Великому Константину, равный ему умом, равно христолюбивый». Константин утвердил веру с Никейским собором, Владимир — по всей своей земле.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Подобный Великому Константину, равный ему умом, равно христолюбивый"}]},{"id":"re42135cb07","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"С кем Иларион сопоставляет княгиню Ольгу, бабку Владимира?","options":["с царицей Еленой","с царицей Феодорой","с царицей Пульхерией","с царицей Ириной"],"explanation":"Как император Константин с матерью Еленой принёс Крест из Иерусалима, так Владимир с бабкой Ольгой принёс Крест «из Нового Иерусалима». Феодора, Пульхерия и Ирина в этом сравнении не участвуют.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Он с матерью своей Еленой Крест от Иерусалима принес"}]},{"id":"r1052bd5ad1","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Каким именем в «Слове» назван сын и преемник Владимира?","options":["Георгий","Борис","Глеб","Святополк"],"explanation":"Иларион называет преемника Владимира христианским именем: «сын твой Георгий» (это Ярослав Мудрый). Борис, Глеб и Святополк — другие сыновья Владимира, преемником Иларион их не называет.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Добрый и верный свидетель – сын твой Георгий, которого Господь создал преемником"}]},{"id":"re87f7810b3","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"С кем Иларион сравнивает сына Владимира, доводящего до конца неоконченное отцом?","options":["с Соломоном, достроившим дело Давида","с Иисусом Навином, преемником Моисея","с Елисеем, учеником пророка Илии","с Езекией, наследником царя Ахаза"],"explanation":"Сын Владимира у Илариона доводит до конца то, что не окончил отец, «как Соломон (дела) Давида»: Соломон построил храм, задуманный Давидом. Иисус Навин, Елисей и Езекия в этом сравнении не появляются.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"доводящим до конца, что тобою неокончено, как Соломон"}]},{"id":"r8da077ef94","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Что, по «Слову», возвёл в Киеве сын Владимира, украсив постройку златом и серебром?","options":["храм Святой Премудрости","Десятинную церковь","церковь Святого Спаса","Успенский собор"],"explanation":"Иларион пишет, что сын Владимира «создал Дом Божий, великий, святой Премудрости» — Софийский собор. Десятинную церковь построил сам Владимир, а Спасский и Успенский соборы здесь не упоминаются.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Он создал Дом Божий, великий, святой Премудрости"}]},{"id":"r813cc59d6e","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Как Иларион обращается к Владимиру в заключительном приветствии «Радуйся, …»?","options":["«апостол во владыках»","«пастырь во царях»","«мученик во князьях»","«пророк во властителях»"],"explanation":"Иларион называет Владимира «апостолом во владыках», который воскресил не мёртвых телами, а людей, мёртвых душою от идолослужения. Остальные формулы придуманы по тому же образцу.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Радуйся, апостол во владыках, не мертвых телами воскресивший"}]},{"id":"r7b92d90c66","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Чей совет царю Навуходоносору Иларион приводит, говоря о милостыне Владимира?","options":["пророка Даниила","пророка Иеремии","пророка Иезекииля","пророка Ионы"],"explanation":"Иларион вспоминает слово Даниила Навуходоносору: «грехи твои милостями очисти и неправды твои — щедротами нищим». Владимир, по Илариону, исполнил этот совет.","sources":[{"title":"Иларион. Слово о Законе и Благодати, похвала Владимиру","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"сказанное Даниилом Навуходоносору: Да будет угоден тебе совет мой"}]},{"id":"r5d6bcbab05","s":1,"topic":"Иларион. «Слово о Законе и Благодати»","text":"Кем был Иларион, автор «Слова о Законе и Благодати»?","options":["первым митрополитом из русских","первым игуменом Печерского монастыря","первым епископом Новгородским","летописцем Киево-Печерского монастыря"],"explanation":"Иларион был поставлен на киевскую митрополию из священников и стал первым митрополитом из русских. Игуменом Печерского монастыря и летописцем он не был.","sources":[{"title":"Иларион. Слово о Законе и Благодати, примечания","url":"https://azbyka.ru/otechnik/Ilarion_Kievskij/slovo_o_zakone_i_blagodati/","quote":"Автор Слова – Иларион, первый митрополит из русских"}]},{"id":"r554fc2a70d","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Кому, по предисловию, адресован «Устав» Нила Сорского?","options":["иноку, хотящему спастись во времена нынешние","мирянам, ищущим наставления в вере","игуменам больших общежительных монастырей","князьям, покровительствующим обителям"],"explanation":"Смысл писаний, по предисловию, — показать, «какое делание подобает иметь иноку, истинно хотящему спастись во времена нынешние».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, предисловие","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"какое делание подобает иметь иноку, истинно хотящему спастись во времена нынешние"}]},{"id":"raaa3f6f458","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Какое слово Господа, по Нилу, восприняли отцы, учившие о сердечном делании?","options":["«От сердца исходят помышления злые»","«Царство Божие внутрь вас есть»","«Бодрствуйте и молитесь непрестанно»","«Блаженны чистые сердцем»"],"explanation":"Отцы учили о хранении ума, восприняв слово Господа: «От сердца исходят помышления злые и оскверняют человека» (Мф. 15:19–20).","sources":[{"title":"Нил Сорский. Устав о скитской жизни, предисловие","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"От сердца исходят помышления злые и оскверняют человека"}]},{"id":"r8b05882eaf","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Кого Нил приводит в пример того, что умное делание возможно и в многолюдном городе?","options":["Симеона Нового Богослова и Симеона Студита","Антония Великого и Пахомия Великого","Сергия Радонежского и Кирилла Белозерского","Иоанна Лествичника и Исаака Сирина"],"explanation":"Не только отшельники, но и жившие в городах просияли этим деланием, «как Симеон Новый Богослов и старец его Симеон Студийский» в многолюдной Студийской обители.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, предисловие","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"как Симеон Новый Богослов и старец его Симеон Студийский"}]},{"id":"r2d5d86b30f","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как, по Симеону Новому Богослову в передаче Нила, к большинству приходит «светородное делание»?","options":["от научения","без всякого научения","от долгого поста","от чтения книг"],"explanation":"Симеон Новый Богослов говорит, что это делание «многим от научения приходит; редкие же то без научения» приняли от Бога.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, предисловие","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"многим от научения приходит; редкие же то без научения"}]},{"id":"rfd7d1f3751","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как в «Уставе» Нила Сорского называется простой помысл или образ, только что вносимый в сердце и являющийся уму?","options":["прилог","сочетание","сосложение","пленение"],"explanation":"Прилог — первая стадия мысленной брани: «простой помысл или образ случившегося, только что в сердце вносимый и уму являющийся».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"это простой помысл или образ"}]},{"id":"r362f3b3604","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Кто из отцов, по Нилу, определяет прилог как «происходящее от врага внушение»?","options":["Григорий Синаит","Иоанн Лествичник","Исихий Иерусалимский","Симеон Новый Богослов"],"explanation":"Иоанн Лествичник и Филофей Синаит называют прилог простым помыслом, а Григорий Синаит — «происходящим от врага внушением», вроде «Сделай это или то».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Григорий же Синаит говорит, что прилог – это происходящее от врага внушение"}]},{"id":"r4176711933","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как Нил называет собеседование с явившимся помыслом, то есть его рассматривание по своему произволению?","options":["сочетание","прилог","пленение","страсть"],"explanation":"«Сочетанием же называют собеседование с явившимся [прилогом] по страсти или бесстрастно», то есть принятие внушаемого помысла и беседу с ним.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"СОЧЕТАНИЕМ же называют собеседование с явившимся"}]},{"id":"r023fd68df2","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"О какой стадии мысленной брани Нил говорит, что она «не совсем безгрешна»?","options":["о сочетании","о прилоге","о сосложении","о страсти"],"explanation":"Прилог безгрешен, а сочетание — обдумывание принесённой уму мысли — «не совсем безгрешно». Сосложение и страсть уже прямо греховны.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"И это, сказали, не совсем безгрешно"}]},{"id":"re2bea6c6ae","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как Нил определяет сосложение?","options":["усладительное склонение души к помыслу","насильственное порабощение сердца","простой образ, вносимый в сердце","навык, ставший нравом души"],"explanation":"«Сосложение же… это усладительное склонение души к явившемуся помыслу или образу», когда человек мысленно соглашается, «чтоб было так, как внушает вражий помысл».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"СОСЛОЖЕНИЕ же, сказали, – это усладительное склонение души к явившемуся помыслу"}]},{"id":"r57245521a5","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что, по Нилу, называется пленением?","options":["невольное порабощение сердца помыслом","первое появление образа в уме","усладительное согласие ума с помыслом","навык, ставший нравом души"],"explanation":"«Пленение же — это или насильственное и невольное порабощение сердца, или продолжительное сочетание с явившимся помыслом».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"ПЛЕНЕНИЕ же – это или насильственное и невольное порабощение сердца"}]},{"id":"r3ebaf1830c","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как, по Нилу, судится пленение помыслом?","options":["иначе во время молитвы и иначе вне её","одинаково строго во всех случаях","лишь по тяжести самого помысла","по суду духовника"],"explanation":"Нил пишет, что пленение «иначе судится во время молитвы и иначе не во время [неё]», иначе в отношении средних помыслов и иначе — злых.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Это иначе судится во время молитвы и иначе не во время"}]},{"id":"r303b2fea30","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как Нил определяет страсть, последнюю ступень мысленной брани?","options":["помысл, ставший от навыка нравом души","случайный образ, вносимый в сердце","кратковременное согласие с помыслом","насильственное порабощение ума"],"explanation":"Страсть — это то, что, «долгое время гнездясь в душе, как бы в нрав её от навыка обращается»; тогда человек увлекается ею произвольно и сам собою.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. I","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"долгое время гнездясь в душе, как бы в нрав ее от навыка обращается"}]},{"id":"r7708bdbf48","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Чем, по главе II «Устава», должно побеждать мысленную брань?","options":["памятью Божией и хранением сердца","строгим постом и долгим бдением","послушанием игумену во всём","чтением житий и поучений"],"explanation":"Глава II посвящена тому, «что должно побеждать всё это памятью Божией и хранением сердца, то есть молитвой и безмолвием ума».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"что должно побеждать всё это памятью Божией и хранением сердца"}]},{"id":"r1125d1aa09","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"С какой силой, по отцам в изложении Нила, должна вестись борьба с помыслами?","options":["с силой, равной силе нападения","с силой большей, чем у врага","без всякого усилия, одной верой","с той силой, какую даст игумен"],"explanation":"«Определяют отцы, чтобы борьба против вышеописанного велась с силой, равной [силе] противоборства».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"чтобы борьба против вышеописанного велась с силой, равной"}]},{"id":"r09f168f0b9","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"В чём, по отцам в изложении Нила, состоит разумная и искусная брань с помыслами?","options":["отсекать их в самом начале","вступать с ними в долгий спор","терпеть их до изнеможения","открывать их всем братьям"],"explanation":"«Разумная и искусная брань… состоит в том, чтобы отсекать начало пришествия» помыслов, то есть прилог.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Разумная и искусная брань, – говорят отцы, – состоит в том, чтобы отсекать начало"}]},{"id":"r8f5d547426","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Какие слова Нил предписывает говорить, взирая постоянно в глубину сердечную?","options":["«Господи Иисусе Христе, Сыне Божий, помилуй мя»","«Святый Боже, Святый Крепкий, Святый Бессмертный»","«Отче наш, Иже еси на небесех, да святится имя Твое»","«Богородице Дево, радуйся, Благодатная Марие»"],"explanation":"Против помыслов подобает молчать мыслью и говорить Иисусову молитву: «Господи Иисусе Христе, Сыне Божий, помилуй мя» — всю или половину её.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Господи Иисусе Христе, Сыне Божий, помилуй мя"}]},{"id":"rfdb0e3747f","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Какое делание, по Нилу, «ненавыкшим весьма трудно»?","options":["блюдение ума в сердце без помыслов","строгий пост в течение всей недели","пение всей Псалтири за одну ночь","молчание в келье круглый год"],"explanation":"«Делание же это — блюдение ума в сердце без всяких помыслов — ненавыкшим весьма трудно», но с Божией помощью достижимо.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Делание же это – блюдение ума в сердце без всяких помыслов – ненавыкшим весьма трудно"}]},{"id":"r75e504c9c9","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как, по приводимому Нилом «уставу деланий», следует распределять время?","options":["час молиться, час читать, час петь","днём трудиться, а ночью молиться","утром читать, вечером петь","всё время молиться без перерыва"],"explanation":"Нил приводит устав, по которому «надо час молиться, час читать, час петь», и толкует, как применять его к немощным.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"устав деланий полагая, что надо час молиться, час читать, час петь"}]},{"id":"r17edbb3183","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что, по заповеди ангела Антонию Великому, приводимой Нилом, следует делать, когда ум рассеян?","options":["прилежать чтению или рукоделию","удвоить пост и стояние на молитве","немедленно идти к старцу за советом","выйти из кельи и пройтись по скиту"],"explanation":"Ангел заповедал Антонию: «в то время, когда ум твой рассеян, более молитвы прилежи чтению или рукоделию». Новоначальным это особенно полезно.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"в то время, когда ум твой рассеян, более молитвы прилежи чтению или рукоделию"}]},{"id":"rfb90c2413e","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Когда, по отцам в изложении Нила, особенно подобает прилежать мысленному деланию?","options":["ночью","на рассвете","в полдень","после трапезы"],"explanation":"«Деланию этому подобает особенно прилежать ночью», — сказали отцы, ибо ночью ум свободнее от забот.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Деланию этому подобает особенно прилежать ночью"}]},{"id":"r9da74fee7e","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Сколько способов мысленного делания различает, по Нилу, Исихий Иерусалимский?","options":["четыре","три","пять","семь"],"explanation":"«Блаженный Исихий Иерусалимский различает четыре способа в этом мысленном делании»: наблюдать за прилогами, хранить сердце молчащим, призывать Христа, помнить о смерти.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Блаженный Исихий Иерусалимский различает четыре способа в этом мысленном делании"}]},{"id":"ra2191db0bd","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что, по Исихию в изложении Нила, относится к способам противостояния лукавым помыслам?","options":["иметь память смертную","поститься до вечера","читать Псалтирь вслух","искать уединения в лесу"],"explanation":"Один из четырёх способов Исихия — «память смертную иметь»; наряду с ним — наблюдение за прилогами, сердечное молчание и призывание Иисуса Христа.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. II","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"или Господа Иисуса Христа на помощь призывать, или память смертную иметь"}]},{"id":"rce2163ee60","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что, по Нилу, следует прежде всего сделать, восстав от сна?","options":["прославить Бога","прочесть Псалтирь","пойти к старцу","взяться за рукоделие"],"explanation":"Нил наставляет: «Итак, восстав от сна, прежде прославь Бога, затем исповедуйся Ему» и потом занимайся деланием.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. IV","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Итак, восстав от сна, прежде прославь Бога, затем исповедуйся Ему"}]},{"id":"r950d0a74e7","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Сколько главных страстных помыслов, «от каковых и прочие рождаются», называет Нил вслед за отцами?","options":["восемь","семь","девять","двенадцать"],"explanation":"Отцы, по Нилу, учат о восьми главных помыслах: чревообъядения, блуда, сребролюбия, гнева, печали, уныния, тщеславия и гордости.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"главных [страстных] помыслов, от каковых и прочие многие страстные помыслы рождаются, восемь"}]},{"id":"rab0e7c52b8","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Какой помысл отцы, по Нилу, поставили первым из главных?","options":["чревообъядения","гордости","блуда","сребролюбия"],"explanation":"Нил говорит, что отцы «первым из всех поставили [помысл] чревообъедения», поэтому и он начинает с него.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"первым из всех поставили они [помысл] чревообъедения"}]},{"id":"r8dd1391bfb","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Какой помысл в перечне Нила стоит последним?","options":["гордости","тщеславия","уныния","печали"],"explanation":"Перечень заканчивается так: «6) уныния, 7) тщеславия, 8) гордости».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"6) уныния, 7) тщеславия, 8) гордости"}]},{"id":"rd97672b458","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"До какого часа, по отцам в изложении Нила, следует поститься?","options":["до девятого","до шестого","до третьего","до вечерни"],"explanation":"«О времени воздержания от пищи сказали отцы: до девятого часа следует поститься»; кто хочет потерпеть больше, это в его воле.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"О времени воздержания от пищи сказали отцы: до девятого часа следует поститься"}]},{"id":"r4f2e63eb31","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Как, по слову «благоразумных» в изложении Нила, следует принимать усладительные снеди?","options":["понемногу от всех имеющихся","лишь одну, самую простую","по одним великим праздникам","ни одной, отвергая их совсем"],"explanation":"«От всех имеющихся усладительных снедей должно принимать понемногу — вот рассуждение благоразумных», а не одно избирать, а другое отвергать.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"От всех имеющихся усладительных снедей должно принимать понемногу"}]},{"id":"r6fd81b6787","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Почему, по Нилу, подвиг против духа блудного особенно жесток?","options":["это двоякая брань — в душе и теле","этот дух нападает лишь ночью","от него нет никакой защиты","он сильнее всех остальных вместе"],"explanation":"«Велик для нас подвиг против духа блудного и крайне жесток, ибо включает [в себя] двоякую брань — в душе и теле».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"ибо включает [в себя] двоякую брань – в душе и теле"}]},{"id":"r4c34f90422","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Откуда, по Нилу, происходит недуг сребролюбия?","options":["извне естества, от маловерия","из самой природы человека","от бедности и нужды","от зависти к богатым"],"explanation":"«Сребролюбия недуг — извне естества, от маловерия и неразумия бывает», поэтому подвиг против него невелик для внимающих себе.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Сребролюбия недуг – извне естества, от маловерия и неразумия бывает"}]},{"id":"r5b54598276","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Чего, кроме золота и серебра, по Нилу, подобает избегать инокам?","options":["всех вещей сверх потребности","общения с родными и близкими","всякой работы за плату","книг, кроме богослужебных"],"explanation":"Нил учит избегать «не только золота, серебра и имущества… но и всех вещей сверх жизненной потребности» — в одежде, обуви, убранстве келий.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"но и всех вещей сверх жизненной потребности"}]},{"id":"rd8481acc2d","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что, по авве Дорофею в изложении Нила, есть великая победа над гневными помыслами?","options":["молиться за оскорбившего брата","молча уйти от обидчика","рассказать обиду игумену","наложить на себя епитимью"],"explanation":"«Великая же победа над гневными помыслами — молиться за брата оскорбившего, как повелел авва Дорофей»: «Помоги, Господи, брату моему…»","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Великая же победа над гневными помыслами – молиться за брата оскорбившего, как повелел авва Дорофей"}]},{"id":"rbbca303aa7","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Какую скорбь, по Нилу, подобает иметь?","options":["о грехах, с надеждой на Бога","о мирских потерях и утратах","о чужих грехах и пороках","о трудностях монашеской жизни"],"explanation":"Скорбь губительна, но «подобает же иметь нам скорбь полезную — о грехах, с надеждою благой на Бога в покаянии».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Подобает же иметь нам скорбь полезную – о грехах, с надеждою благой на Бога"}]},{"id":"r8fb408f277","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"С каким духом, по Нилу, сопряжено уныние?","options":["с духом скорби","с духом гнева","с духом блуда","с духом тщеславия"],"explanation":"Уныние — «лют этот дух, тягчайший, ибо сопряжён он с духом скорби и споспешествует ему».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Лют этот дух, тягчайший, ибо сопряжен он с духом скорби"}]},{"id":"rbd995b2aaa","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что, по Нилу, порождают утвердившиеся тщеславные помыслы?","options":["высокомерие","уныние","гнев","сребролюбие"],"explanation":"Если часто слагаемся с тщеславными помыслами, они, «утвердившись», вскоре «породят высокомерие».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, гл. V","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"то вскоре, утвердившись, они породят высокомерие"}]},{"id":"r5cf0207cca","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"О чём глава VII «Устава» Нила Сорского?","options":["о памяти смертной и Страшном Суде","о слезах и о том, как их обрести","об отсечении забот и попечений","о различии телесных сил иноков"],"explanation":"Глава VII — «О памяти смертной и Страшном Суде: как поучаться в этом»; о слезах — глава VIII, об отсечении забот — глава X.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, оглавление","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"О памяти смертной и Страшном Суде: как поучаться в этом"}]},{"id":"rb0a553b674","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Что Нил называет «беспопечением истинным»?","options":["умерщвление для всего","забвение мира в молитве","бедность без забот о хлебе","послушание без рассуждения"],"explanation":"Глава X: «Об отсечении забот и беспопечении истинном, каковое есть умерщвление для всего».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, оглавление","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Об отсечении забот и беспопечении истинном, каковое есть умерщвление для всего"}]},{"id":"r1854d64402","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"О чём предупреждает последняя глава «Устава»?","options":["не браться за делания прежде времени","не принимать в скит новых учеников","не держать в келье лишних книг","не выходить из скита без благословения"],"explanation":"Глава XI учит, «что не прежде времени и в подобающую меру эти делания подобает совершать»: не дерзать прежде времени на высокое.","sources":[{"title":"Нил Сорский. Устав о скитской жизни, оглавление","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"что не прежде времени и в подобающую меру эти делания подобает совершать"}]},{"id":"r5fc8613ce3","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"О чём Нил просит братьев в «Духовном завещании»?","options":["бросить его тело в пустынном месте зверям","похоронить его у алтаря скитской церкви","отвезти его тело в Кирилло-Белозерский монастырь","раздать его книги по соседним обителям"],"explanation":"Нил просит: «по кончине моей повергните тело моё в пустынном месте, да изгложут его звери и птицы, потому что согрешило оно пред Богом».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, Духовное завещание","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"повергните тело мое в пустынном месте, да изгложут его звери и птицы"}]},{"id":"rd5c5e5bcef","s":1,"topic":"Нил Сорский. «Устав о скитской жизни»","text":"Чьё слово ученикам о собственном теле Нил приводит в «Духовном завещании»?","options":["Арсения Великого","Антония Великого","Макария Египетского","Пахомия Великого"],"explanation":"Нил напоминает: «Бойтесь же слова, которое заповедал Великий Арсений ученикам своим: На суде стану с вами, если кому дадите тело моё».","sources":[{"title":"Нил Сорский. Устав о скитской жизни, Духовное завещание","url":"https://azbyka.ru/otechnik/Nil_Sorskij/ustav-prepodobnogo-nila-sorskogo/","quote":"Бойтесь же слова, которое заповедал Великий Арсений ученикам своим"}]},{"id":"r7a2cf56baf","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Из какого города, по «Сказанию» Иосифа Волоцкого, прибыл в Новгород Схария?","options":["из Киева","из Вильны","из Кафы","из Смоленска"],"explanation":"«Сказание о новой ереси» начинается словами: «В то время жил в городе Киеве жид по имени Схария». Оттуда он пришёл в Новгород в свите князя.","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"В то время жил в городе Киеве жид по имени Схария"}]},{"id":"r6202422b37","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"С каким князем, по «Сказанию», Схария прибыл в Новгород?","options":["с Михаилом, правнуком Ольгерда","с Михаилом Борисовичем Тверским","с Казимиром, королём Польским","с Дмитрием Шемякой"],"explanation":"Схария был известен князю Михаилу, «сыну Александра, правнуку Вольгирда», которого новгородцы в 1470 году пригласили на княжение.","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Он был известен правившему в то время князю по имени Михаил, сыну Александра, правнуку Вольгирда"}]},{"id":"rcf760bd3ac","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Каким «злодейским изобретениям», по Иосифу, был обучен Схария?","options":["чародейству, чернокнижию и звездочетству","ростовщичеству, обману и подлогу","алхимии и составлению ядов","врачеванию и составлению гороскопов"],"explanation":"Иосиф пишет, что Схария «был обучен всякому злодейскому изобретению: чародейству и чернокнижию, звездочетству и астрологии».","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"чародейству и чернокнижию, звездочетству и астрологии"}]},{"id":"r7cd76e383b","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Каких новгородских священников, по «Сказанию», первыми совратил Схария?","options":["Дениса и Алексея","Максима и Гавриила","Касьяна и Некраса","Зосиму и Феодосия"],"explanation":"Первыми отступили поп Денис и протопоп Алексей; «Алексей же и Денис так старались укрепиться» в ереси, что сами стали её распространять.","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Алексей же и Денис так старались укрепиться"}]},{"id":"r28b60419ab","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какое тайное имя, по «Сказанию», дали новгородскому протопопу Алексею?","options":["Авраам","Моисей","Исаак","Давид"],"explanation":"Учителя ереси, по Иосифу, «переменили им имена: назвали Алексея Авраамом, а жену его Саррой».","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"назвали Алексея Авраамом, а жену его Саррой"}]},{"id":"r0b2098411a","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по Иосифу, советовали новообращённым еретикам их учителя?","options":["тайно держаться ереси, явно — христианства","открыто проповедовать новое учение в храмах","уйти в Литву и там принять новую веру","оставить священство и стать купцами"],"explanation":"Учителя говорили им: «держитесь своего жидовства втайне, а внешне будьте христианами», чтобы их не разоблачили.","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"держитесь своего жидовства втайне, а внешне будьте христианами"}]},{"id":"raf8c7b181c","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Кто, по «Сказанию», прибыл в Новгород из Литвы вслед за Схарией?","options":["Иосиф Шмойло-Скаравей и Мосей Хануш","Фёдор Курицын и его брат Волк","Иван Максимов и его отец поп Максим","Касьян Юрьевский и Некрас Рукавов"],"explanation":"«Потом прибыли из Литвы и другие жиды — Иосиф Шмойло-Скаравей, Мосей Хануш». Курицыны, Максимовы и Касьян — русские последователи ереси.","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Потом прибыли из Литвы и другие жиды – Иосиф Шмойло-Скаравей, Мосей Хануш"}]},{"id":"r4131d228cf","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какой вывод, по Иосифу, делали еретики из того, что пасхалия закончилась, а второго пришествия нет?","options":["творения отцов ложны и их следует сжечь","мир будет стоять вечно, без конца","пришествие отложено ещё на тысячу лет","Христос уже пришёл, но тайно"],"explanation":"Еретики, по Иосифу, говорили, что второго пришествия нет, «значит, творения отцов Церкви ложны и следует их сжечь».","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"значит, творения отцов Церкви ложны и следует их сжечь"}]},{"id":"rd47874d460","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Сколько лет от сотворения мира, по словам еретиков, прошло к концу пасхалии?","options":["семь тысяч","шесть тысяч","восемь тысяч","пять тысяч пятьсот"],"explanation":"Восьмое слово направлено против еретиков, говоривших, «что семь тысяч лет от сотворения мира прошло и пасхалия закончилась, а второго Христова пришествия нет».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 8","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"что семь тысяч лет от сотворения мира прошло и пасхалия закончилась"}]},{"id":"r1d339143e2","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Каким, по Иосифу, является «век сей», если его счёт ведётся седмицами?","options":["седмочисленным","тысячелетним","бесконечным","десятичным"],"explanation":"Иосиф напоминает: «век сей седмочислен» — месяцы и годы считают седмицами, поэтому нет оснований ждать конца ровно с седьмой тысячей.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 8","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"о чем уже прежде говорили, – что век сей седмочислен"}]},{"id":"r1bef39b0b2","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какой архангел, по Иосифу, «считает годы нынешнего века седмицами»?","options":["Гавриил","Михаил","Рафаил","Уриил"],"explanation":"Иосиф приводит слова, сказанные пророку Даниилу о «семи седминах и шестидесяти двух седминах»: «и архангел Гавриил считает годы нынешнего века седмицами».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 8","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Видишь, и архангел Гавриил считает годы нынешнего века седмицами"}]},{"id":"r55d1c2a107","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по предисловию к «Просветителю», постановил Собор 1492 года?","options":["составить пасхалию на восьмую тысячу лет","отлучить всех новгородских еретиков","поставить Геннадия митрополитом","запретить чтение отреченных книг"],"explanation":"Чтобы успокоить умы, «Собор 1492 г. постановил написать пасхалию на восьмую тысячу лет», что и было сделано святителем Геннадием.","sources":[{"title":"Иосиф Волоцкий. Просветитель, предисловие издателя","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Собор 1492 г. постановил написать пасхалию на восьмую тысячу лет"}]},{"id":"rd947cb2299","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Сколько лет, по словам еретиков в девятом слове, прошло от Рождества Христова?","options":["тысяча пятьсот","тысяча","тысяча четыреста","две тысячи"],"explanation":"Еретики спрашивали: апостолы написали, что Христос родился «в последние лета», «и уже тысяча пятьсот лет прошло» — почему же нет второго пришествия?","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 9","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Христос родился в последние лета, и уже тысяча пятьсот лет прошло"}]},{"id":"r0128d60b98","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по архиепископу Геннадию в «Сказании», велено было сжечь, когда осуждённых еретиков провели по городу?","options":["шлемы на их головах","их книги и тетради","их дома и имущество","их священнические ризы"],"explanation":"Архиепископ велел водить еретиков по городу, чтобы встречные плевали в них, «после же повелел сжечь шлемы, бывшие у них на головах».","sources":[{"title":"Иосиф Волоцкий. Просветитель, Сказание о новой ереси","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"После же повелел сжечь шлемы, бывшие у них на головах"}]},{"id":"r2c8bb9c54b","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Кого Иосиф называет «скверным злобесным волком, облекшимся в пастырскую одежду»?","options":["митрополита Зосиму","протопопа Алексея","дьяка Фёдора Курицына","попа Дениса"],"explanation":"Иосиф пишет, что на престоле святителей Петра и Алексия «ныне сидит скверный злобесный волк», — так он говорит о митрополите Зосиме, тайном последователе ереси.","sources":[{"title":"Иосиф Волоцкий. Просветитель, предисловие издателя","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"ныне сидит скверный злобесный волк, облекшийся в пастырскую одежду"}]},{"id":"rda5faeba88","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какую должность при Иване III, по предисловию к «Просветителю», занимал Фёдор Курицын?","options":["думного дьяка","окольничего","боярина","печатника"],"explanation":"Среди сторонников ереси в окружении великого князя был «особо приближённый к великому князю думный дьяк Фёдор Курицын».","sources":[{"title":"Иосиф Волоцкий. Просветитель, предисловие издателя","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"особо приближенный к великому князю думный дьяк Федор Курицын"}]},{"id":"rb1eaa21b4b","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Каким монастырём, по предисловию к «Просветителю», управлял Зосима до поставления в митрополиты?","options":["Симоновым","Чудовым","Троицким","Андрониковым"],"explanation":"Среди тайных сторонников ереси назван «архимандрит Симонова монастыря Зосима», в 1490 году поставленный на митрополичью кафедру.","sources":[{"title":"Иосиф Волоцкий. Просветитель, предисловие издателя","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"невестка Иоанна III молдаванка Елена, архимандрит Симонова монастыря Зосима"}]},{"id":"r112af26c38","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Чьего совета, по предисловию, искал Геннадий Новгородский в борьбе с ересью?","options":["Нила Сорского и Паисия Ярославова","Иосифа Волоцкого и Кирилла Белозерского","Максима Грека и Вассиана Патрикеева","Сергия Радонежского и Стефана Пермского"],"explanation":"Святитель Геннадий «искал совета учёных старцев — преподобного Нила Сорского и Паисия Ярославова», позже участвовавших в Соборе 1490 года.","sources":[{"title":"Иосиф Волоцкий. Просветитель, предисловие издателя","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"святитель Геннадий искал совета ученых старцев – преподобного Нила Сорского"}]},{"id":"r5e2efcc44c","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Против какого учения направлено первое слово «Просветителя»?","options":["против отрицания Святой Троицы","против отрицания святых икон","против хулы на иноческое житие","против ожидания конца света"],"explanation":"Первое слово направлено против еретиков, говоривших, «будто у Бога Отца Вседержителя нет ни Сына, ни Святого Духа… и что нет Святой Троицы».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 1","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"будто у Бога Отца Вседержителя нет ни Сына, ни Святого Духа"}]},{"id":"r0c3a4f9759","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по изложению Иосифа во втором слове, еретики утверждали о Христе?","options":["Он ещё не родился, а родится потом","Он родился, но не воскрес","Он воскрес, но не вознёсся","Он был ангелом, а не человеком"],"explanation":"Второе слово — против говорящих, «что Христос ещё не родился, но придёт время, когда Он родится», а почитаемый христианами — простой человек.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 2","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"говорящих, что Христос еще не родился, но придет время, когда Он родится"}]},{"id":"rd5bc18886a","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по изложению Иосифа в третьем слове, еретики считали должным соблюдать?","options":["Моисеев закон с жертвами и обрезанием","субботний покой без всяких жертв","посты по древнему еврейскому уставу","праздники по лунному календарю"],"explanation":"Третье слово — против говорящих, «что надлежит придерживаться Моисеева закона, сохранять его, совершать жертвоприношения и обрезываться».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 3","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"что надлежит придерживаться Моисеева закона, сохранять его, совершать жертвоприношения и обрезываться"}]},{"id":"r1a40bb3920","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какой вопрос о вочеловечении, по Иосифу, задавали еретики в четвёртом слове?","options":["разве Бог не мог спасти Адама иначе","зачем Христос родился от Девы","почему Христос не сошёл с креста","для чего Он крестился в Иордане"],"explanation":"Еретики спрашивали: «Разве Бог не мог спасти Адама и род его», послав небесные воинства или пророков, но Сам сошёл «в виде нищего»?","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 4","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Разве Бог не мог спасти Адама и род его"}]},{"id":"ra085f829e9","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Чем, по Иосифу, еретики обосновывали запрет изображать Святую Троицу на иконах?","options":["Авраам видел Бога с двумя ангелами","Бога вообще не видел никто из людей","в Писании нет слова «Троица»","Троица — тайна, недоступная кисти"],"explanation":"Пятое слово — против говорящих, что не следует изображать Троицу, «ибо сказано в Писании, что Авраам видел Бога с двумя ангелами, а не Троицу».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 5","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"ибо сказано в Писании, что Авраам видел Бога с двумя ангелами, а не Троицу"}]},{"id":"r69b455cbf5","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Чьё свидетельство о том, что «у дубравы Мамре патриарх угощал ангелов», приводит Иосиф?","options":["Андрея Критского","Иоанна Дамаскина","Василия Великого","Ефрема Сирина"],"explanation":"В пятом слове Иосиф приводит: «Святой Андрей Критский утверждает: у дубравы Мамре патриарх угощал ангелов».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 5","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Святой Андрей Критский утверждает: у дубравы Мамре патриарх угощал ангелов"}]},{"id":"rb18f512d00","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Против какого утверждения направлено шестое слово «Просветителя»?","options":["будто не следует чтить рукотворное","будто не следует соблюдать посты","будто не следует почитать мощи","будто не следует освящать храмы"],"explanation":"Шестое слово — против говорящих, «будто не следует поклоняться рукотворным предметам»; Иосиф показывает, что и в Ветхом Законе поклонялись рукотворным вещам.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 6","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"будто не следует поклоняться рукотворным предметам"}]},{"id":"r948e77ad0b","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"О чём, по оглавлению, седьмое слово «Просветителя»?","options":["как и почему поклоняться иконам и Кресту","как распознать еретика по его речам","как вести себя в храме во время службы","как составлять пасхалию на новые лета"],"explanation":"Седьмое слово — «свидетельство святых книг о том, как и почему подобает христианам поклоняться божественным иконам», Кресту, Евангелию и Святым Тайнам.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 7","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"как и почему подобает христианам поклоняться божественным иконам и почитать их"}]},{"id":"re19284a4db","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какой довод, по Иосифу, приводят «неправо мудрствующие», говорящие, что «не нужно церкви»?","options":["человек сам — храм Божий","Бог вездесущ и без храма","первые христиане не строили храмов","храмы строят ради тщеславия"],"explanation":"«Некоторые, неправо мудрствующие» говорят, что «не нужно церкви, но сам человек — церковь», ссылаясь на апостола Павла и Златоуста.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 7","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"не нужно церкви, но сам человек – церковь"}]},{"id":"r7a6d10656f","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какие слова Златоуста о церкви, по Иосифу, приводят те, кто отвергает храмы?","options":["церковь — не стены, а собрание верных","церковь — дом молитвы для всех народов","церковь — столп и утверждение истины","церковь — корабль среди житейского моря"],"explanation":"Неправо мудрствующие ссылаются на то, что «святой Иоанн Златоуст говорит, что церковь — это не стены, но собрание верных и благочестивых людей».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 7","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Иоанн Златоуст говорит, что церковь – это не стены, но"}]},{"id":"raee7d750ff","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Почему, по Иосифу, следует служить царю, князю и начальникам?","options":["потому что это угодно Богу","потому что они сильнее","ради собственной выгоды","потому что так велит обычай"],"explanation":"«Следует поклоняться и служить потому, что это угодно Богу — оказывать властям покорность и послушание: ведь они пекутся и думают о нас».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 7","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"следует поклоняться и служить потому, что это угодно Богу"}]},{"id":"re28fdac922","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Кем, по Иосифу, является царь, над которым царствуют страсти и неверие?","options":["не царём, а мучителем","всё же Божьим слугой","царём, за которого надо молиться","карой, которую следует терпеть"],"explanation":"Если над царём царствуют сребролюбие, гнев, неверие и хула, «такой царь не Божий слуга, но дьяволов, и не царь, но мучитель».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 7","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"такой царь не Божий слуга, но дьяволов, и не царь, но мучитель"}]},{"id":"r5a1b734000","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Каким словом, по Иосифу, Христос называет нечестивого царя?","options":["лисицей","волком","змеем","псом"],"explanation":"Иосиф напоминает: такого царя «Господь наш Иисус Христос называет не царём, а лисицей: „Пойдите, скажите этой лисице“».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 7","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Господь наш Иисус Христос называет не царем, а лисицей"}]},{"id":"red77248482","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Чьи творения, по Иосифу, хулили еретики, называя их ложными?","options":["святого Ефрема","Иоанна Златоуста","Василия Великого","Иоанна Дамаскина"],"explanation":"Десятое слово — против еретиков, «хулящих творения святого Ефрема и говорящих, что творения его ложны».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 10","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"хулящих творения святого Ефрема и говорящих, что творения его ложны"}]},{"id":"r980912548e","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Против хулы на что направлено одиннадцатое слово «Просветителя»?","options":["на иноческое житие","на церковное пение","на таинство брака","на почитание мощей"],"explanation":"Одиннадцатое слово целиком — «против ереси новгородских еретиков, хулящих иноческое житие».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Слово 11-е, против ереси новгородских еретиков, хулящих иноческое житие"}]},{"id":"rb46a5f5689","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"В чём, по одному из еретических возражений против монашества, иноки отступили от заповедей?","options":["устроили житие по своему измышлению","отказались от брака вопреки Писанию","не платят податей государю","не трудятся своими руками"],"explanation":"Первая глава одиннадцатого слова — против говорящих, что иноки «по своему измышлению и самонаучению устроили себе житие и держатся предания человеческого».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"по своему измышлению и самонаучению устроили себе житие и держатся предания человеческого"}]},{"id":"r54143aba78","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"На какой довод, связанный с иконами, ссылались еретики, отвергая иноческое житие?","options":["Христа и апостолов пишут в мирской одежде","на иконах не пишут иноческих схим","древние иконы писали одни миряне","иконы монахов появились лишь недавно"],"explanation":"Еретики говорили: будь иночество угодно Богу, Христос и апостолы пребывали бы в иноческом образе, «но теперь мы видим Христа, а также и святых апостолов, изображаемыми в мирском» образе.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"мы видим Христа, а также и святых апостолов, изображаемыми в мирском"}]},{"id":"rad03bcbbe3","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Почему, по словам еретиков, схиму Пахомию передал не ангел Божий?","options":["явившийся был чёрным, а не светлым","схимы вовсе нет в Писании","Пахомий не видел никакого ангела","ангелы не носят никакой одежды"],"explanation":"Еретики говорили: «если бы это был ангел Божий, он явился бы светлым, но он явился чёрным — а это знак бесовского действия».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"если бы это был ангел Божий, он явился бы светлым, но он явился черным"}]},{"id":"re25c74ab13","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Чьи слова, по Иосифу, еретики извращали в споре о монашестве?","options":["апостола Павла к Тимофею","апостола Петра к рассеянным","апостола Иакова к двенадцати коленам","апостола Иоанна к избранной госпоже"],"explanation":"«Иные же извращают слова святого апостола Павла, которые он написал к Тимофею», о запрещающих вступать в брак, и прилагают их к инокам.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Иные же извращают слова святого апостола Павла, которые он написал к Тимофею"}]},{"id":"rdb30e7d0f5","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Кто, по Иосифу, установил иноческое житие?","options":["апостол Пётр","Антоний Великий","Пахомий Великий","Василий Великий"],"explanation":"Ссылаясь на Климента Римского, Иосиф заключает: «Итак, всем понятно, что великий апостол Пётр установил иноческое житие».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Итак, всем понятно, что великий апостол Петр установил иноческое житие"}]},{"id":"r5791e68aa6","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по Иосифу, носили подвижники, жившие до Пахомия Великого?","options":["малый иноческий образ","великую схиму","мирскую одежду","белые ризы"],"explanation":"Перечислив древних подвижников, Иосиф пишет: «И все они жили до Пахомия Великого, нося малый иноческий образ».","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"И все они жили до Пахомия Великого, нося малый иноческий образ"}]},{"id":"rc8ad4a34a0","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Сколько лет, по Иосифу, прожил в пустыне преподобный Онуфрий, которого обрёл Пафнутий?","options":["шестьдесят","сорок","тридцать","семьдесят"],"explanation":"Иосиф пишет, что преподобный Пафнутий «обрёл великого Онуфрия, жившего в пустыне шестьдесят лет», а прежде жившего в монастыре.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 11","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"обрел великого Онуфрия, жившего в пустыне шестьдесят лет"}]},{"id":"re42516c992","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по изложению Иосифа в двенадцатом слове, утверждали еретики о проклятии, наложенном епископом-еретиком?","options":["Божий суд последует его суду","оно недействительно и ничтожно","его может снять лишь Собор","оно падает на самого епископа"],"explanation":"Двенадцатое слово — против говорящих, будто если епископ-еретик проклянёт православного, «Божий суд последует его суду». Иосиф доказывает обратное.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 12","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"будто если епископ будет еретиком и не благословит или проклянет кого-либо из православных, Божий суд последует его суду"}]},{"id":"rc33ba6cb96","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по изложению Иосифа, говорили еретики о суде над еретиками и отступниками?","options":["что их нельзя осуждать","что их следует лишь проклинать","что их судит один царь","что их судит один Собор"],"explanation":"Тринадцатое слово — против говорящих, «что нельзя осуждать ни еретика, ни отступника».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 13","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"говорящих, что нельзя осуждать ни еретика, ни отступника"}]},{"id":"recb625fffd","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по Иосифу, подобает делать царям, князьям и судьям с еретиками и отступниками?","options":["отправлять в заточение и предавать казням","увещевать их и отпускать с миром","высылать их за пределы своей земли навсегда","передавать на суд одной Церкви"],"explanation":"В тринадцатом слове Иосиф собирает свидетельства, что еретика следует не только осуждать, но и проклинать, «царям же и князьям и судьям подобает отправлять их в заточение и предавать лютым казням».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 13","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"царям же и князьям и судьям подобает отправлять их в заточение и предавать лютым казням"}]},{"id":"r8e85499405","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по изложению Иосифа, утверждали еретики о розыске еретиков?","options":["не допытываться, если сами не признаются","следует искать их по всей Русской земле","розыск — дело одного митрополита","розыск надо вести лишь в монастырях"],"explanation":"Четырнадцатое слово — против говорящих, «что не следует особенно много дознаваться, выведывать и допытываться о еретиках», если они сами не исповедают ереси.","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 14","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"что не следует особенно много дознаваться, выведывать и допытываться о еретиках"}]},{"id":"ra22fff1e95","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Что, по изложению Иосифа в пятнадцатом слове, утверждали еретики о раскаявшемся еретике?","options":["его вскоре следует допускать к причастию","его следует навсегда отлучить от Церкви","его нужно вновь крестить в купели","его нужно постричь в монахи"],"explanation":"Пятнадцатое слово — против говорящих, «что если еретик или отступник покается, то вскоре следует ему входить во святую церковь и причащаться».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 15","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"что если еретик или отступник покается, то вскоре следует ему входить во святую церковь и причащаться"}]},{"id":"r10b5f2eb02","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Против какого мнения направлено последнее, шестнадцатое слово «Просветителя»?","options":["что каящихся осуждённых еретиков надо миловать","что ереси нужно опровергать одним словом","что еретиков нельзя судить мирским судом","что еретиков следует перекрещивать"],"explanation":"Шестнадцатое слово — против говорящих, что если обличённые и осуждённые еретики «начнут каяться, то следует принять их покаяние и удостоить их милости».","sources":[{"title":"Иосиф Волоцкий. Просветитель, оглавление, слово 16","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"начнут каяться, то следует принять их покаяние и удостоить их милости"}]},{"id":"r923141168f","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Как, по Иосифу, поступил император Андроник Палеолог с калабрийскими еретиками, проклятыми на Соборе?","options":["даровал им прощение","заточил их в темницу","предал их казни","выслал их в Италию"],"explanation":"Андроник собрал Собор и велел проклясть еретиков, но «не осудил их в заточение и в темницу, но даровал им прощение», и они прельстили многих. Иосиф приводит это как пример вредной милости.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 16","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"по проклятии же не осудил их в заточение и в темницу, но даровал им прощение"}]},{"id":"rb9846526b0","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Какая участь, по Иосифу, постигла Акиндина?","options":["царь осудил его в заточение","он был убит православными","он покаялся и стал монахом","он бежал обратно в Калабрию"],"explanation":"По Иосифу, Варлаам был убит православными людьми, «Акиндин же был осуждён царём в заточение», и ересь их прекратилась.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 16","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"Акиндин же был осужден царем в заточение"}]},{"id":"r6dff6a24c8","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Кто, по Иосифу, собрал Второй Вселенский Собор?","options":["Феодосий Великий","Константин Великий","Юстиниан Великий","Маркиан"],"explanation":"Иосиф пишет, что «преемник царя, Феодосий Великий, собрал Второй божественный Собор» против духоборцев.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 15","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"преемник царя, Феодосий Великий, собрал Второй божественный"}]},{"id":"r34959d63df","s":1,"topic":"Иосиф Волоцкий. «Просветитель»","text":"Чем, по Иосифу, отличается божество Христа от «божества» Моисея и Давида, о которых Писание говорит «боги»?","options":["Он Бог по существу, а не по благодати","Он Бог по усыновлению Отцом","Он больший пророк, чем все они","Он Бог лишь по Своему человечеству"],"explanation":"Иосиф поясняет, что Христос — Бог «не по благодати, как Моисей и Давид», но по Существу.","sources":[{"title":"Иосиф Волоцкий. Просветитель, слово 2","url":"https://azbyka.ru/otechnik/Iosif_Volotskij/prosvetitel/","quote":"чтобы не думали, что Он Бог не по Существу, но лишь по благодати, как Моисей и Давид"}]},{"id":"rfd5c478529","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какой митрополит, по Федотову, перенёс мощи Бориса и Глеба в новую церковь и составил им службу, хотя поначалу сомневался?","options":["Иоанн","Георгий","Иларион","Михаил"],"explanation":"Митрополит Иоанн был «преужасен и в усумнении», но именно он перенёс нетленные тела князей, установил им праздник и составил службу. Митрополит Георгий сомневался ещё в 1072 году.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 1 «Борис и Глеб — святые страстотерпцы»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Тем не менее именно этот Иоанн перенес нетленные тела князей в новую церковь"}]},{"id":"r5b07ea7bc9","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Почему, по Федотову, сомнения греков в святости Бориса и Глеба были «вполне естественны»?","options":["они погибли в усобице, а не за веру","их мощи долго не источали чудес","они не были крещены греками","их почитали лишь в одном Киеве"],"explanation":"«Борис и Глеб не были мучениками за Христа, но пали жертвой политического преступления, в княжеской усобице», как многие до и после них.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 1 «Борис и Глеб — святые страстотерпцы»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Борис и Глеб не были мучениками за Христа, но пали жертвой политического преступления"}]},{"id":"r1d47cbd36a","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какой третий брат, павший от руки того же убийцы, по Федотову, не был канонизован?","options":["Святослав","Ярослав","Мстислав","Судислав"],"explanation":"Одновременно с Борисом и Глебом от руки Святополка пал «и третий брат Святослав, о канонизации которого и речи не было».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 1 «Борис и Глеб — святые страстотерпцы»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"пал и третий брат Святослав, о канонизации которого и речи не было"}]},{"id":"r03dc03d445","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чем, по Федотову, кончается даже предсмертное причитание Глеба?","options":["выражением беззлобного непротивления","проклятием брату-убийце","мольбой о мести за кровь","призывом к дружине защитить его"],"explanation":"Глеб молит убийц пощадить его юность, «однако уже это причитание кончается выражением беззлобного непротивления».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 1 «Борис и Глеб — святые страстотерпцы»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Однако уже это причитание кончается выражением беззлобного непротивления"}]},{"id":"r4e6c2f8c5b","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какое страдание, по Федотову, есть «страдание за имя Христово»?","options":["всякое невинное и вольное страдание","лишь мученичество за исповедание веры","лишь страдание от рук язычников","всякая смерть в бою за Отечество"],"explanation":"По Федотову, Борис и Глеб показывают: «всякое невинное и вольное страдание в мире есть страдание за имя Христово».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 1 «Борис и Глеб — святые страстотерпцы»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"всякое невинное и вольное страдание в мире есть страдание за имя Христово"}]},{"id":"r08acd11757","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кого Федотов называет первым преподобным, канонизованным Русской Церковью?","options":["Феодосия Печерского","Антония Печерского","Сергия Радонежского","Варлаама Хутынского"],"explanation":"«Феодосий Печерский был вторым святым, торжественно канонизованным Русской Церковью, и первым её преподобным». Его учителя Антония канонизовали позже.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 2 «Преподобный Феодосий Печерский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Феодосий Печерский был вторым святым, торжественно канонизованным Русской Церковью, и первым ее преподобным"}]},{"id":"r501834501b","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кого Федотов называет «отцом русского монашества»?","options":["преподобного Феодосия","преподобного Сергия","преподобного Антония","преподобного Нила"],"explanation":"«Преподобный Феодосий — отец русского монашества. Все русские иноки — дети его, носящие на себе его фамильные черты».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 2 «Преподобный Феодосий Печерский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Преподобный Феодосий – отец русского монашества"}]},{"id":"r0f7ebf1a73","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чей труд, по Федотову, лёг в основу всей русской агиографии?","options":["Нестора","Епифания Премудрого","Пахомия Серба","Илариона"],"explanation":"Несторово житие Феодосия, по Федотову, «ложится в основу всей русской агиографии», вдохновляя на подвиги и описание их.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 2 «Преподобный Феодосий Печерский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Труд Нестора ложится в основу всей русской агиографии"}]},{"id":"rc49381f0f9","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Каково, по Федотову, общее впечатление от Несторова жития Феодосия?","options":["перед нами жизнь, а не литература","перед нами легенда, а не история","перед нами проповедь, а не рассказ","перед нами устав, а не житие"],"explanation":"Нестор нашёл свежее предание и назвал своих осведомителей: «Общее впечатление от его труда: перед нами жизнь, а не литература».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 2 «Преподобный Феодосий Печерский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Общее впечатление от его труда: перед нами жизнь, а не литература"}]},{"id":"r04e4a4b37a","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какая внешняя черта, по Федотову, отличает Феодосия даже в игуменстве?","options":["«худые ризы»","железные вериги","хождение босиком","долгие волосы"],"explanation":"«„Худые ризы“ Феодосия отличают его и в игуменстве»; подаренную светлую одежду он вскоре отдавал нищим.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 2 «Преподобный Феодосий Печерский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Худые ризы Феодосия отличают его и в игуменстве"}]},{"id":"r77310faa89","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Сколько святых, по Федотову, почивает в Ближней и Дальней пещерах Киево-Печерского монастыря?","options":["сто восемнадцать","сорок","семьдесят два","триста"],"explanation":"В пещерах «почивают мощи ста восемнадцати святых», большинство которых известно лишь по имени.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 3 «Святые Киево-Печерского патерика»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"почивают мощи ста восемнадцати святых"}]},{"id":"rc16fa94d44","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто, по Федотову, канонизовал киево-печерских святых, поручив составить им общую службу?","options":["митрополит Пётр Могила","митрополит Иов Борецкий","патриарх Никон","святитель Димитрий Ростовский"],"explanation":"«Митрополит Пётр Могила канонизовал их в 1643 г., поручив составить общую им службу».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 3 «Святые Киево-Печерского патерика»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Митрополит Петр Могила канонизовал их в 1643 г."}]},{"id":"r299f6ee285","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Когда, по Федотову, киевские святые были внесены в общерусские месяцесловы?","options":["в 1762 году, по указу Синода","в 1643 году, при Петре Могиле","в 1547 году, на Соборе при Макарии","в 1721 году, при учреждении Синода"],"explanation":"«И лишь в 1762 г., по указу Святейшего Синода, киевские святые были внесены в общерусские месяцесловы»; местно их канонизовали в 1643 году.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 3 «Святые Киево-Печерского патерика»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"И лишь в 1762 г., по указу Святейшего Синода, киевские святые были внесены в общерусские месяцесловы"}]},{"id":"r54ceb1a953","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Что, по Федотову, называется патериком?","options":["сводные жития подвижников одной местности","сборник поучений одного великого старца","устав общежительной монастырской жизни","летопись одного монастыря за века"],"explanation":"«Патериками… называются сводные жизнеописания подвижников-аскетов определённой местности: Египта, Сирии, Палестины».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 3 «Святые Киево-Печерского патерика»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Патериками в древней христианской письменности называются сводные жизнеописания подвижников-аскетов определенной местности"}]},{"id":"rae5274ceca","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто, по Федотову, назван в летописном сказании «о первых черноризцах печерских»?","options":["Дамиан, Иеремия, Матфей и Исаакий","Антоний, Феодосий, Никон и Варлаам","Агапит, Алимпий, Прохор и Марк","Моисей Угрин, Никита и Лаврентий"],"explanation":"Сказание «о первых черноризцах печерских» говорит о Дамиане, Иеремии, Матфее и Исаакии Затворнике; оно принадлежит автору XI века.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 3 «Святые Киево-Печерского патерика»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Дамиан, Иеремия, Матфей и Исаакий Затворник"}]},{"id":"r5b1125df63","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какой характер, по Федотову, имели домонгольские монастыри?","options":["городской или пригородный","пустынный, в глухих лесах","пещерный, в горах","островной, на озёрах"],"explanation":"«Все сведения о домонгольских монастырях указывают на их городской или пригородный характер». Уход в лесную пустыню начнётся лишь в XIV веке.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 4 «Преподобный Авраамий Смоленский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Все сведения о домонгольских монастырях указывают на их городской или пригородный характер"}]},{"id":"r958ef76e32","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Во имя какого праздника, по Федотову, Варлаам Хутынский построил монастырь близ Новгорода?","options":["Преображения Господня","Рождества Богородицы","Святой Троицы","Воскресения Христова"],"explanation":"Варлаам, сын богатого боярина, удалился на Хутынь в десяти верстах от Новгорода и «построил монастырь во имя Преображения Господня».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 4 «Преподобный Авраамий Смоленский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"построил монастырь во имя Преображения Господня"}]},{"id":"rb8d7d8f571","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Почему, по житию в изложении Федотова, разбойники убили Никиту Столпника?","options":["приняли блеск его вериг за серебро","хотели отомстить за прежние обиды","их подослали недовольные бояре","он обличал их злодеяния"],"explanation":"Никита Переяславский носил тяжёлые вериги; его убили разбойники, «которые приняли за серебро блеск его вериг».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 4 «Преподобный Авраамий Смоленский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Убитый разбойниками, которые приняли за серебро блеск его вериг"}]},{"id":"r2832582acf","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какую икону, по житию в изложении Федотова, написал Авраамий Смоленский?","options":["Страшный суд второго пришествия","Троицу Ветхозаветную у Мамре","Богоматерь Знамение Новгородскую","Спаса Нерукотворного на убрусе"],"explanation":"Смоленский инок был и художником: «Написа же две иконы: едину Страшный суд второго пришествиа», а другую — испытание мытарств.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 4 «Преподобный Авраамий Смоленский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Написа же две иконы: едину Страшный суд второго пришествиа"}]},{"id":"r32f2f94cee","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кем Федотов называет Авраамия Смоленского?","options":["страстотерпцем православного гнозиса","апостолом северных народов","игуменом всей Русской земли","печальником за угнетённый народ"],"explanation":"Уточняя содержание учёности Авраамия, Федотов пишет, что «св. Авраамий был страстотерпцем православного гнозиса».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 4 «Преподобный Авраамий Смоленский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"св. Авраамий был страстотерпцем православного гнозиса"}]},{"id":"r08aa604b69","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Сколько князей и княгинь, по Федотову, канонизовано к общему или местному почитанию?","options":["около пятидесяти","около десяти","около двухсот","около двадцати"],"explanation":"«Можно насчитать около пятидесяти князей и княгинь, канонизованных к общему или местному почитанию».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 5 «Святые князья»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Можно насчитать около пятидесяти князей и княгинь, канонизованных"}]},{"id":"rd6238b6c17","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Когда, по Федотову, особенно усиливается почитание святых князей?","options":["во времена монгольского ига","в эпоху Киевской Руси","при первых царях из Романовых","в эпоху Петра Великого"],"explanation":"Почитание князей начинается с первых лет христианства, «но особенно усиливается во времена монгольского ига», чтобы прекратиться с ним к концу XV века.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 5 «Святые князья»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"но особенно усиливается во времена монгольского ига"}]},{"id":"r5264ad1185","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какую долю русских святых мирян, по Федотову, составляют святые князья?","options":["больше половины","около десятой части","около четверти","почти всех"],"explanation":"Федотова поражает «обширность этой общественной группы (больше половины русских святых мирян)».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 5 «Святые князья»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"больше половины русских святых мирян"}]},{"id":"r3c8f93b925","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Зачем, по житию в изложении Федотова, Михаил Тверской пошёл в Орду, предчувствуя гибель?","options":["чтобы отвратить погром от своей земли","чтобы получить ярлык на великое княжение","чтобы обличить хана в беззаконии","чтобы выкупить пленных тверичей"],"explanation":"Михаил Тверской «предчувствует свою гибель, но хочет отвратить ею татарский погром от своей земли».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 5 «Святые князья»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Он предчувствует свою гибель, но хочет отвратить ею татарский погром от своей земли"}]},{"id":"ra12501e32f","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Сколько епископов, по Федотову, Русская Церковь почитает среди святых?","options":["около семидесяти","около тридцати","около ста пятидесяти","около двадцати"],"explanation":"«Русская Церковь почитает среди своих святых около семидесяти епископов» — это чин святителей.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 6 «Святители»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Русская Церковь почитает среди своих святых около семидесяти епископов"}]},{"id":"ra9f15e4f10","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Из кого, по Федотову, на Руси почти исключительно избирали епископов?","options":["из чёрного духовенства","из белого духовенства","из княжеских родов","из греческого клира"],"explanation":"«У нас установился обычай почти исключительного избрания епископов из чёрного духовенства. Почти всякий епископ — монах».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 6 «Святители»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"у нас установился обычай почти исключительного избрания епископов из черного духовенства"}]},{"id":"rb22775dddf","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"О чём, по Федотову, святитель «тихими и кроткими словесы» напоминал царю при разрыве из-за опричнины?","options":["о страшном суде Божием","о канонах Вселенских соборов","о славе его предков","о милости к врагам"],"explanation":"В беседе с царём наедине святитель (митрополит Филипп) «тихими и кроткими словесы» напоминал о страшном суде Божием, взыскующем со всех.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 6 «Святители»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"святитель тихими и кроткими словесы напоминал царю о страшном суде Божием"}]},{"id":"rc6bdbd73f8","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Где, по Федотову, святитель Дионисий основал «второй Печерский монастырь»?","options":["в Нижнем Новгороде","в Пскове","в Ростове","во Владимире"],"explanation":"«Св. Дионисий долго подвизался в пещере в Нижнем Новгороде, основав здесь второй Печерский монастырь», прежде чем стал епископом Суздальским.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 6 «Святители»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Св. Дионисий долго подвизался в пещере в Нижнем Новгороде, основав здесь второй Печерский монастырь"}]},{"id":"r94f8f564df","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кем, по Федотову, прежде всего был святитель Стефан Пермский?","options":["миссионером среди язычников","строителем монастырей","обличителем еретиков","переводчиком греческих книг"],"explanation":"«Святитель Стефан — миссионер, отдавший свою жизнь на обращение языческого народа».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 7 «Святитель Стефан Пермский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Святитель Стефан – миссионер, отдавший свою жизнь на обращение языческого народа"}]},{"id":"r2fe2d5b783","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто, по Федотову, написал житие Стефана Пермского?","options":["Епифаний Премудрый","Пахомий Серб","Нестор Летописец","митрополит Киприан"],"explanation":"«Биографом его был тот же Епифаний Премудрый, который написал и первое житие преподобного Сергия».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 7 «Святитель Стефан Пермский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Биографом его был тот же Епифаний Премудрый"}]},{"id":"rad4b89934a","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Откуда, по Федотову, был родом Стефан Пермский?","options":["из Устюга Великого","из Ростова Великого","из Новгорода Великого","из Вологды"],"explanation":"«Св. Стефан был родом из Устюга Великого в Двинской земле», вокруг которого начинались поселения пермяков.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 7 «Святитель Стефан Пермский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Св. Стефан был родом из Устюга Великого в Двинской земле"}]},{"id":"ree4a212266","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Как, по Федотову, по-русски называли западных пермяков, которых крестил Стефан?","options":["зырянами","вотяками","вогулами","остяками"],"explanation":"Вокруг Устюга жили западные пермяки, «или, по нашему наименованию, зыряне»; восточных пермяков на Каме крестили преемники Стефана.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 7 «Святитель Стефан Пермский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"поселения западных пермяков, или, по нашему наименованию, зырян"}]},{"id":"rfcb9a8cf45","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Как Федотов называет нисхождение Стефана «из учёного затвора» к пермякам?","options":["плодоносным кенозисом","апостольским хождением","подвигом юродства","миссионерским походом"],"explanation":"Ради пермяков Стефан, по Федотову, «совершает своё нисхождение из учёного затвора, свой плодоносный кенозис».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 7 «Святитель Стефан Пермский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Для них он совершает свое нисхождение из ученого затвора, свой плодоносный кенозис"}]},{"id":"rcc0add3152","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"С кем из святых, по Федотову, Стефана Пермского связывала духовная дружба?","options":["с Сергием Радонежским","с Кириллом Белозерским","с митрополитом Алексием","с Димитрием Прилуцким"],"explanation":"«Стефан и Сергий были связаны между собой узами духовной дружбы»; Стефан посещал обитель Святой Троицы.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 7 «Святитель Стефан Пермский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Стефан и Сергий были связаны между собой узами духовной дружбы"}]},{"id":"rf6b6333da9","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Как, по Федотову, первое столетие монгольского завоевания сказалось на духовной жизни Руси?","options":["надолго заглушило её","вызвало расцвет святости","никак на ней не сказалось","обратило её к Востоку"],"explanation":"Монгольское завоевание, по Федотову, разгромило государственную и культурную жизнь и «заглушило надолго и её духовную жизнь».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 8 «Преподобный Сергий Радонежский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"оно заглушило надолго и ее духовную жизнь"}]},{"id":"ra89c882bb1","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чем, по Федотову, новое подвижничество XIV века отличается от древнерусского?","options":["это подвижничество пустынножителей","это подвижничество городских затворников","это подвижничество святых князей","это подвижничество юродивых"],"explanation":"Монастыри Киевской Руси были городскими, а новое подвижничество «существенными чертами отличается от древнерусского. Это подвижничество пустынножителей».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 8 «Преподобный Сергий Радонежский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"существенными чертами отличается от древнерусского. Это подвижничество пустынножителей"}]},{"id":"rc76a153a10","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кого Федотов называет «величайшим из святых Древней Руси»?","options":["преподобного Сергия","преподобного Феодосия","святителя Стефана","преподобного Нила"],"explanation":"Главой нового пустынножительного иночества был «преподобный Сергий, величайший из святых Древней Руси».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 8 «Преподобный Сергий Радонежский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"преподобный Сергий, величайший из святых Древней Руси"}]},{"id":"r1096d7d7aa","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"По каким двум направлениям, по Федотову, растекался духовный поток из Троице-Сергиевой обители?","options":["на юг, в Москву, и на север, в лесные пустыни","на запад, в Литву, и на восток, в Сибирь","в Киев и в Новгород","на Афон и в Царьград"],"explanation":"Поток из Троицы бежал «на юг, в Москву… и на север, в лесные пустыни по Волге и в Заволжье»; с этим связано раздвоение путей русской духовной жизни.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 9 «Северная Фиваида»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"на юг, в Москву, в ее городские и подмосковные монастыри, и на север, в лесные пустыни"}]},{"id":"rba1801a71e","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто, по Федотову, был преемником Сергия в игуменстве?","options":["Никон","Кирилл","Савва","Андроник"],"explanation":"Из лаврских святых, по Федотову, отчётливо виден «только Никон, преемник Сергия во игуменстве», в котором любовь к безмолвию боролась с хозяйственными заботами.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 9 «Северная Фиваида»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"только Никон, преемник Сергия во игуменстве"}]},{"id":"ra720448e39","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чем, по Федотову, Нил Сорский единствен среди древних русских святых?","options":["он один писал о духовной жизни","он один побывал на Афоне","он один отказался от игуменства","он один был из дворян"],"explanation":"«Единственный из древних наших святых, он писал о духовной жизни и… оставил полное и точное руководство духовного пути».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 10 «Преподобный Нил Сорский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Единственный из древних наших святых, он писал о духовной жизни"}]},{"id":"rc32633c559","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Что, по преданию в изложении Федотова, случилось с житием Нила Сорского?","options":["оно сгорело при татарском разорении","оно было запрещено иосифлянами","оно было увезено учениками на Афон","оно хранится в Соловецкой обители"],"explanation":"Жития Нила у нас нет: «предание говорит, что оно сгорело во время татарского разорения вологодских скитов в 1538 г.».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 10 «Преподобный Нил Сорский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"оно сгорело во время татарского разорения вологодских скитов в 1538 г"}]},{"id":"r7477c7cce4","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Где, по Федотову, побывал Нил Сорский вместе с учеником Иннокентием?","options":["на Афоне и в Царьграде","в Иерусалиме и на Синае","в Киеве и в Чернигове","в Риме и во Флоренции"],"explanation":"«Очень важно, что преподобный Нил побывал на Афоне и „в странах Цареграда“», куда ходил с учеником Иннокентием (Охлябининым).","sources":[{"title":"Федотов. Святые Древней Руси, гл. 10 «Преподобный Нил Сорский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"преподобный Нил побывал на Афоне и в странах Цареграда"}]},{"id":"r2b4b0ae594","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какой дворянский род, по Федотову, считает Нила Сорского своим предком?","options":["Майковы","Шереметевы","Ртищевы","Головины"],"explanation":"«Дворянский род Майковых считает Нила Сорского в числе своих предков. Даже это недостоверно».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 10 «Преподобный Нил Сорский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Дворянский род Майковых считает Нила Сорского в числе своих предков"}]},{"id":"r8dcc5cc47d","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кем, по одному известию, был Нил Сорский в миру?","options":["скорописцем, переписчиком книг","купцом, торговавшим с Царьградом","воином в княжеской дружине","иконописцем при соборе"],"explanation":"«Есть известие, что он был в миру „скорописцем“, списателем книг».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 10 «Преподобный Нил Сорский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"он был в миру скорописцем, списателем книг"}]},{"id":"re1e0b4a747","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"К чему, по Федотову, стремились московские ученики Сергия в отличие от северных пустынножителей?","options":["к идеалу совершенного общежития","к уединённому лесному созерцанию","к миссии среди северных язычников","к подвигу юродства в городах"],"explanation":"«Северные пустынножители искали уединённого созерцания, московские ученики преподобного Сергия стремились осуществить идеал совершенного общежития».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 11 «Преподобный Иосиф Волоцкий»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"московские ученики преподобного Сергия стремились осуществить идеал совершенного общежития"}]},{"id":"rd93d37d17f","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто, по Федотову, был учителем Иосифа Волоцкого?","options":["Пафнутий Боровский","Нил Сорский","Кирилл Белозерский","Паисий Ярославов"],"explanation":"Пафнутий Боровский, ученик игумена Никиты (ученика Сергия), «в свою очередь был учителем Иосифа».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 11 «Преподобный Иосиф Волоцкий»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"и в свою очередь был учителем Иосифа"}]},{"id":"r5dbdcd2cf2","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Каким, по житию в изложении Федотова, был тверской игумен Савва?","options":["строгим: бил жезлом и сажал в затвор","кротким: ни разу не наказывал братию","учёным: переписывал книги ночами","молчаливым: годами не говорил с братией"],"explanation":"О тверском игумене Савве читаем: «Овогда жезлом бияше, овогда и в затвор посылаше», — игуменская строгость была условием уставной жизни.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 11 «Преподобный Иосиф Волоцкий»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Овогда жезлом бияше, овогда и в затвор посылаше"}]},{"id":"r446594a7a1","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Из чего, по Федотову, исходят «нестяжатели» в отличие от иосифлян?","options":["из любви, а не из страха","из страха, а не из любви","из разума, а не из веры","из обычая, а не из устава"],"explanation":"Противоположность заволжских «нестяжателей» и иосифлян огромна: «Одни исходят из любви, другие — из страха»; одни являют кротость, другие строгость к грешнику.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 12 «Трагедия древнерусской святости»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Одни исходят из любви, другие – из страха"}]},{"id":"rb27236fc6c","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какие практические вопросы, по Федотову, сделали борьбу нестяжателей и иосифлян неизбежной?","options":["монастырские вотчины и отношение к еретикам","календарь и порядок церковного богослужения","отношение к Флорентийской унии с Римом","перевод книг и исправление обрядов"],"explanation":"Сама противоположность направлений не требует борьбы, но «практические выводы — отношение к монастырским вотчинам и еретикам — сделали борьбу неизбежной».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 12 «Трагедия древнерусской святости»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"отношение к монастырским вотчинам и еретикам – сделали борьбу неизбежной"}]},{"id":"r3a3eaac18c","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Как, по Федотову, вёл себя в этой борьбе сам Нил Сорский?","options":["воздерживался от полемических посланий","писал резкие послания против Иосифа","просил великого князя вмешаться","требовал Собора против иосифлян"],"explanation":"«Сам преподобный Нил воздерживался от полемических посланий, как и вообще от участия в политической жизни».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 12 «Трагедия древнерусской святости»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Сам преподобный Нил воздерживался от полемических посланий"}]},{"id":"re6545766da","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какой митрополит, по Федотову, осудил Максима Грека и Вассиана Патрикеева?","options":["Даниил","Макарий","Варлаам","Иоасаф"],"explanation":"«Осудивший Максима и Вассиана митрополит Даниил был сам из игуменов Волоколамского монастыря и учеников преподобного Иосифа».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 12 «Трагедия древнерусской святости»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Осудивший Максима и Вассиана митрополит Даниил был сам из игуменов Волоколамского монастыря"}]},{"id":"r53e54f52d5","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"На какое столетие, по Федотову, падает расцвет русского юродства?","options":["на XVI век","на XIV век","на XII век","на XVIII век"],"explanation":"Чин юродивых входит в Русскую Церковь с начала XIV века, а «его расцвет падает на XVI столетие».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Его расцвет падает на XVI столетие"}]},{"id":"r4b3eaf2a80","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Как Федотов оценивает мнение, будто юродство — исключительное призвание Русской Церкви?","options":["как преувеличение истины","как совершенную правду","как выдумку иностранцев","как старообрядческий миф"],"explanation":"«Это мнение заключает в себе преувеличение истины»: Греческая Церковь тоже чтит юродивых.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Это мнение заключает в себе преувеличение истины"}]},{"id":"r1e0bdad1a8","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Сколько юродивых, по Федотову, чтит Греческая Церковь?","options":["шестерых","двоих","двенадцать","ни одного"],"explanation":"«Греческая Церковь чтит шестерых юродивых»; двое из них, Симеон и Андрей, получили обширные жития.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Греческая Церковь чтит шестерых юродивых"}]},{"id":"re07cd0577b","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто, по Федотову, был первым настоящим юродивым на Руси?","options":["Прокопий Устюжский","Василий Блаженный","Николай Салос","Михаил Клопский"],"explanation":"«Первым настоящим юродивым на Руси был Прокопий Устюжский», хотя его житие составлено лишь в XVI веке.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Первым настоящим юродивым на Руси был Прокопий Устюжский"}]},{"id":"r191d0777ec","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"С кого, по Федотову, начинается ряд московских юродивых?","options":["с Максима","с Василия","с Иоанна","с Прокопия"],"explanation":"«Ряд московских юродивых начинается с Максима († 1433)»; XVI век дал Москве Василия Блаженного и Иоанна Большого Колпака.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Ряд московских юродивых начинается с Максима"}]},{"id":"rb7b68f434f","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какой собор, по Федотову, народ переименовал в собор Василия Блаженного?","options":["Покровский","Успенский","Архангельский","Благовещенский"],"explanation":"Почитание Василия Блаженного показывает «переименование народом Покровского (и Троицкого) собора, в котором он был погребён, в собор Василия Блаженного».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"переименование народом Покровского (и Троицкого) собора, в котором он был погребен, в собор Василия Блаженного"}]},{"id":"r6afcf1a59d","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кто из преподобных, по Федотову, временно нёс «тяжкое бремя юродства»?","options":["Кирилл Белозерский","Сергий Радонежский","Пафнутий Боровский","Иосиф Волоцкий"],"explanation":"«Временно нёс тяжкое бремя юродства и преподобный Кирилл Белозерский», как прежде Исаакий Печерский.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 13 «Юродивые»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Временно нес тяжкое бремя юродства и преподобный Кирилл Белозерский"}]},{"id":"rd90f5f5839","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какие два противоположных начала, по Федотову, воплощают святые князья и юродивые?","options":["социальный долг и отвержение мира","книжную учёность и простоту веры","строгость закона и милость к грешнику","верность Царьграду и верность Москве"],"explanation":"Князья и юродивые воплощают «несение социального долга в самом высоком… из мирских призваний — и самое радикальное отвержение мира, совместимое с пребыванием в миру».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 14 «Святые миряне и их жены»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"несение социального долга в самом высоком и почетном из мирских призваний"}]},{"id":"rc125a5d481","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Кем, по Федотову, был Артемий Веркольский?","options":["крестьянским мальчиком, убитым молнией","княжичем, убитым в братской усобице","монахом-отшельником на реке Пинеге","юродивым из города Холмогор"],"explanation":"Артемий Веркольский — «крестьянский мальчик (Архангельская губерния), убитый молнией в двенадцатилетнем возрасте».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 14 «Святые миряне и их жены»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"крестьянский мальчик (Архангельская губерния), убитый молнией в двенадцатилетнем возрасте"}]},{"id":"reec875d047","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чем, по Федотову, зарабатывал на хлеб Симеон Верхотурский?","options":["шитьём шуб и рыбной ловлей","переписыванием церковных книг","иконописью и резьбой по дереву","торговлей сибирской пушниной"],"explanation":"Симеон Верхотурский вёл странническую жизнь, «зарабатывая себе хлеб шитьём шуб» и рыбной ловлей.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 14 «Святые миряне и их жены»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"зарабатывая себе хлеб шитьем шуб"}]},{"id":"r4716653e62","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Что, по Федотову, история знает о муромских святых Петре и Февронии?","options":["ничего, даже имён в летописи нет","точные годы их княжения","подробное житие XIII века","место их погребения в Киеве"],"explanation":"О Петре и Февронии «история не знает ничего… даже имена их не встречаются в летописи»; есть лишь народная легенда.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 14 «Святые миряне и их жены»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"История не знает ничего о них, даже имена их не встречаются в летописи"}]},{"id":"r56f59ef99d","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чем, по Федотову, отличаются русские жития святых?","options":["большой трезвостью","обилием вымысла","пышными чудесами","светским духом"],"explanation":"«Русские жития святых отличаются большою трезвостью»: при недостатке преданий агиограф не давал воли воображению.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 15 «Легендарные мотивы в русских житиях»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Русские жития святых отличаются большою трезвостью"}]},{"id":"r20763c9f5c","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Как, по Федотову, агиограф обычно восполнял недостаток преданий о святом?","options":["«риторическим плетением словес»","вымышленными яркими чудесами","пересказами историй из Библии","народными сказками и былинами"],"explanation":"Агиограф «обыкновенно развивал скудные воспоминания „риторическим плетением словес“» или вставлял их в типическую рамку.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 15 «Легендарные мотивы в русских житиях»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"обыкновенно развивал скудные воспоминания риторическим плетением словес"}]},{"id":"r5ad774e9d9","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"С какими сказками, по Федотову, перекликается легенда о бесе в рукомойнике и путешествии на нём?","options":["«Тысяча и одна ночь»","сказки братьев Гримм","басни Эзопа","«Декамерон»"],"explanation":"Джинн, запечатанный в сосуде, и путешествие на спине джинна «всем знакомы по сказкам „Тысячи и одной ночи“».","sources":[{"title":"Федотов. Святые Древней Руси, гл. 15 «Легендарные мотивы в русских житиях»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"всем знакомы по сказкам Тысячи и одной ночи"}]},{"id":"r7bcb398aa2","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"На какой век, по Федотову, приходится вершина допетровской святости?","options":["на XV век","на XI век","на XIII век","на XVII век"],"explanation":"Допетровская святость — «духовный процесс, имеющий своё возрастание, свою вершину (XV век) и свой упадок».","sources":[{"title":"Федотов. Святые Древней Руси, заключение","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"свое возрастание, свою вершину (XV век) и свой упадок"}]},{"id":"r123ba12661","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Какое первое и последнее впечатление, по Федотову, оставляет древнерусская святость?","options":["светлая мерность без радикализма","суровость и жестокая аскеза подвижников","мистическая восторженность и экстаз","обрядовая строгость и буквализм"],"explanation":"«Первое и последнее впечатление… — её светлая мерность, отсутствие радикализма, крайних и резких отклонений» от христианского идеала.","sources":[{"title":"Федотов. Святые Древней Руси, заключение","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"ее светлая мерность, отсутствие радикализма"}]},{"id":"r8e3fd5315f","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Чего, по Федотову, мы почти не видим в русском монашестве?","options":["жестокой аскезы и самоистязаний","общежительных монастырей с уставом","лесного пустынножительства","умного молитвенного делания"],"explanation":"«В монашестве мы почти не видим жестокой аскезы, практики самоистязаний».","sources":[{"title":"Федотов. Святые Древней Руси, заключение","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"В монашестве мы почти не видим жестокой аскезы, практики самоистязаний"}]},{"id":"r450fb4333d","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"Что, по Федотову, в XVIII веке происходило чаще канонизации святых?","options":["деканонизация","перенесение мощей","составление житий","освящение храмов"],"explanation":"При Святейшем Синоде канонизации были редки; «в XVIII веке чаще деканонизировали святых».","sources":[{"title":"Федотов. Святые Древней Руси, заключение","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"в XVIII веке чаще деканонизировали святых"}]},{"id":"r51fd7b4e22","s":1,"topic":"Федотов. «Святые Древней Руси»","text":"При каком игумене, по Федотову, был пострижен в Печерском монастыре Нестор?","options":["при Стефане, преемнике Феодосия","при самом Феодосии","при Никоне, преемнике Антония","при Варлааме, первом игумене"],"explanation":"«Преподобный Нестор был пострижен в Печерском монастыре в игуменство Стефана, первого преемника Феодосия», поэтому очевидцем жизни Феодосия не был.","sources":[{"title":"Федотов. Святые Древней Руси, гл. 2 «Преподобный Феодосий Печерский»","url":"https://azbyka.ru/otechnik/Georgij_Fedotov/svjatye-drevnej-rusi/","quote":"Преподобный Нестор был пострижен в Печерском монастыре в игуменство Стефана, первого преемника Феодосия"}]},{"id":"rb312d0ecd4","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Где, по помете в начале первой книги, Радищев начал трактат «О человеке, о его смертности и бессмертии»?","options":["в Илимске","в Тобольске","в Петербурге","в Москве"],"explanation":"Первая книга помечена: «Начато 1792 года генваря 15. Илимск». Радищев писал трактат в сибирской ссылке.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"НАЧАТО 1792 ГОДА ГЕНВАРЯ 15. ИЛИМСК"}]},{"id":"rccc62df40f","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чьи слова «Настоящее чревато будущим» Радищев взял эпиграфом к трактату?","options":["Лейбница","Вольтера","Гердера","Руссо"],"explanation":"Эпиграф дан по-французски: «Le temps présent est gros de l'avenir. Leibnitz».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I, эпиграф","url":"","quote":"Le temps présent est gros de l'avenir. Leibnitz"}]},{"id":"rf17c2f38f7","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Что, по признанию Радищева, побудило его обратить мысль на будущее состояние человека по смерти?","options":["нечаянное переселение в отдалённую страну","смерть близкого друга и учителя","чтение сочинений французских философов","долгая и тяжёлая болезнь"],"explanation":"Радищев обращается к друзьям: нечаянное переселение «в страну отдалённую, разлучив меня с вами», побудило его думать о будущем состоянии своего существа.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"мое преселение в страну отдаленную, разлучив меня с вами"}]},{"id":"r1522baeeab","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чем, по Радищеву, следует руководствоваться, отложив предрассудки, в поисках истины о человеке?","options":["светильником опытности","светом Откровения","преданиями предков","авторитетом древних"],"explanation":"«Удалим от нас все предрассудки, все предубеждения и, водимые светильником опытности», постараемся собрать факты о природе.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"Удалим от нас все предрассудки, все предубеждения и, водимые светильником опытности"}]},{"id":"rdcef946871","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"С чего Радищев начинает рассуждение о посмертной участи человека?","options":["с того, чем он был до рождения","с описания смерти и тления тела","с учения Церкви о Страшном суде","с мнений древних о душе"],"explanation":"Прежде чем предречь, чем человек будет после смерти, Радищев хочет сказать, «что человек был до его рождения».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"я скажу, что человек был до его рождения"}]},{"id":"r1e90b77b92","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какое качество, по Радищеву, «паче всего» отличает человека?","options":["способность и совершенствоваться, и развращаться","способность к членораздельной речи и счёту","прямохождение и руки, свободные для труда","неистребимое стремление жить в обществе"],"explanation":"«Сие то и есть паче всего человека отличающее качество, что совершенствовать он может, равно и развращаться; пределы тому и другому ещё неизвестны».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"что совершенствовать он может, равно и развращаться"}]},{"id":"rd4ca0bf5af","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"О чём, по Радищеву, свидетельствует строение человеческой ступни?","options":["человек должен смотреть за пределы земли","человек создан для долгой ходьбы по земле","человек родствен человекообразным обезьянам","человек рождён для тяжёлого труда"],"explanation":"Строение ступни и её мышц, по Радищеву, — «явное доказательство, что человек не пресмыкаться должен по земле, а смотреть за её пределы».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"человек не пресмыкаться должен по земле, а смотреть за ее пределы"}]},{"id":"r173bf2c35f","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какое свойство человека Радищев называет «зверством неограниченным»?","options":["хладнокровно убивать братию, повинуясь власти","поедать мясо животных ради насыщения","охотиться на зверей ради одной забавы","воевать за свою землю и отцовскую веру"],"explanation":"Человек, по Радищеву, способен к «зверству неограниченному»: убивать братию хладнокровно, «повинуяся власти, которую сам создал».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"зверство его неограниченное убивая братию свою хладнокровно, повинуяся власти, которую сам создал"}]},{"id":"r09594ec943","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какой лицевой угол, по Радищеву, имеют обезьяны?","options":["от 42 до 50 градусов","от 60 до 70 градусов","от 80 до 90 градусов","от 20 до 30 градусов"],"explanation":"«Обезьяны имеют в образе своём сей угол от 42 до 50 степеней»; у европейцев он около 80, а «греческая вообразимая красота» — от 90 до 100.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"Обезьяны имеют в образе своем сей угол от 42 до 50 степеней"}]},{"id":"r64353a42d5","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чем, по объяснению, которое приводит Радищев, определяется сходство животного с человеком по лицевому углу?","options":["горизонтальным или вертикальным строением тела","величиной и весом его головного мозга","образом жизни и способом добывания пищи","климатом и местом его обитания"],"explanation":"Радищев излагает объяснение Гердера: дело «в отношении животного к его горизонтальному или перпендикулярному строению» и положению головы.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"говорит, что она состоит в отношении животного к его горизонтальному или перпендикулярному строению"}]},{"id":"rd2a42e0eb7","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кто, по Радищеву, «не без вероятности» утверждал, что руки были человеку путеводительницей к разуму?","options":["Гельвеций","Гердер","Локк","Руссо"],"explanation":"«Гельвеций не без вероятности утверждал, что руки были человеку путеводительницы к разуму»: им человек обязан всеми художествами и рукоделиями.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"Гельвеций не без вероятности утверждал, что руки были человеку путеводительницы к разуму"}]},{"id":"rfa514095a4","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Каким, по Радищеву, является время?","options":["человеческим","природным","божественным","всеобщим"],"explanation":"У природы, по Радищеву, не шаги, а беспредельность: «время есть не её, но человеческое».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"время есть не ее, но человеческое"}]},{"id":"rcafc4d3f7d","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Для чего, по Радищеву, рождён человек?","options":["для общежития","для уединения","для войны","для труда"],"explanation":"«Человек рождён для общежития»: позднее совершеннолетие не позволяет людям разойтись, как зверям.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"вот первое начальство и царство первое. Человек рожден для общежития"}]},{"id":"r5797c8a29d","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"К кому Радищев обращается с упрёком: «куда тебя завлекла чувствительность необъятная?»","options":["к Руссо","к Гельвецию","к Вольтеру","к Гердеру"],"explanation":"Возражая против мысли о естественной одинокости человека, Радищев восклицает: «О, Руссо! куда тебя завлекла чувствительность необъятная?»","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"О, Руссо! куда тебя завлекла чувствительность необъятная"}]},{"id":"r2756e609a8","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"От чего, по Радищеву, зависит «развержение народного разума»?","options":["от стечения счастливых обстоятельств","от климата и почвы всей страны","от врождённых свойств самого племени","от воли мудрых правителей"],"explanation":"Радищев заключает, что «развержение народного разума зависит от стечения счастливых обстоятельств», а не от природных различий народов.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"развержение народного разума зависит от стечения"}]},{"id":"r72068e7c58","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какие доказательства Гельвеция Радищев называет слабыми?","options":["о единосилии разумов","о происхождении идей из чувств","о пользе как мериле добра","о роли рук в развитии ума"],"explanation":"Различие разумов между отдельными людьми, по Радищеву, реально: «сколь Гельвеций ни остроумен, доказательства его о единосилии разумов суть слабы».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"доказательства его о единосилии разумов суть слабы"}]},{"id":"re3e14ce150","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Каковы, по Радищеву, разумные силы человека при рождении?","options":["они ничто","они уже совершенны","они развиты наполовину","они у всех различны"],"explanation":"«Четвёртое, что замечается при рассмотрении разумных сил человека, есть то, что силы сии ничто при рождении»: они развиваются лишь со временем.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"есть то, что силы сии ничто при рождении"}]},{"id":"r7883c55a5f","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"На какие три рода, по Руссо в изложении Радищева, делится воспитание?","options":["воспитание природы, человека и вещей","воспитание семьи, школы и Церкви","воспитание тела, ума и сердца","воспитание словом, примером и делом"],"explanation":"Руссо, «изящнейший учитель о воспитании», делит его на воспитание природы, человека и вещей.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"Ж. Ж. Руссо 38, разделяет его на три рода"}]},{"id":"r4f22a9c53b","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чьи опыты, по Радищеву, показали, сколь сложно вещество, которым мы дышим?","options":["Пристли","Лавуазье","Ломоносова","Франклина"],"explanation":"«Опыты одного доктора Пристлея… показали, сколь вещество, нами вдыхаемое, есть сложно».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. II","url":"","quote":"Опыты одного доктора Пристлея45, не говоря о последствующих"}]},{"id":"r52cb3f04c1","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Каким примером противник бессмертия у Радищева показывает, что душа может разрушиться?","options":["разрезанный шар даёт половины, а не шары","разбитый сосуд больше не держит воды","погасшая свеча больше не даёт света","срубленное дерево уже не растёт"],"explanation":"Довод материалиста: «Разрежь… один шар на двое, выдут ли из того два шара? Выдут две половины, но шара не будет».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. II","url":"","quote":"один шар на двое, выдут ли из того два шара?"}]},{"id":"r7cbc00671f","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какой довод о связи души с телом Радищев вкладывает в уста противника бессмертия?","options":["душа растёт, мужает и вянет вместе с телом","душа рождается от души обоих родителей","душа живёт в крови и движется с ней","душа есть дыхание, покидающее тело"],"explanation":"«Не с телом ли растёт душа, не с ним ли мужает и крепится, не с ним ли вянет и тупеет?» — спрашивает противник бессмертия.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. II","url":"","quote":"Не с телом ли растет душа, не с ним ли мужает и крепится"}]},{"id":"rb9b728d4a2","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чьё учение о том, что все мысли, даже отвлечённые, начинаются в чувствах, приводит Радищев?","options":["Локка","Лейбница","Декарта","Беркли"],"explanation":"Противник бессмертия советует: «прочти Локка. Он удивит тебя, что все мысли твои, и самые отвлечённейшие, в чувствах твоих имеют своё начало».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. II","url":"","quote":"прочти Локка. Он удивит тебя, что все мысли твои, и самые отвлеченнейшие, в чувствах твоих имеют свое начало"}]},{"id":"re7c8bf4c15","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"С кем, по доводу противника бессмертия, сравним тот, кто отделяет мыслящее начало от чувственности?","options":["с тем, кто дал бы особую душу носу, уху и глазу","с тем, кто ищет ветер в поле и тень в полдень","с тем, кто строит свой дом на зыбком песке","с тем, кто носит воду решетом из колодца"],"explanation":"«Ты похож в сём случае на того, кто бы захотел дать душу носу твоему, дать душу уху, дать её глазу».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. II","url":"","quote":"Ты похож в сем случае на того, кто бы захотел дать душу носу твоему"}]},{"id":"r3b2b58fda0","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Как Радищев называет «столь чувствуемое я», которое, быть может, продлится за пределы дней наших?","options":["единственность","самость","личность","сущность"],"explanation":"Радищев хочет найти, продлится ли «бытие наше, или, лучше сказать, наша единственность, сие столь чувствуемое я» за предел жизни.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I","url":"","quote":"наша единственность, сие столь чувствуемое я"}]},{"id":"r9a0d1e1683","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Что, по одному из предположений Радищева, есть душа?","options":["сила, действующая органом","тонкое огненное вещество","кровь, движимая сердцем","гармония частей тела"],"explanation":"Радищев допускает: «душа есть сила, действующая органом, а орган разрушится», — и спрашивает, сохранит ли она тождественность.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. I, примечание","url":"","quote":"ибо душа есть сила, действующая органом, а орган разрушится"}]},{"id":"r6de0b59c24","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Зачем, по признанию Радищева, он изложил доводы о смертности души «во всей их блистательности»?","options":["чтобы явнее стала их слабая сторона","чтобы убедить друзей в смертности души","чтобы опровергнуть учение Церкви","чтобы показать силу материализма"],"explanation":"В начале третьей книги Радищев объясняет: он старался придать доводам смертности блеск, «дабы тем явнее могла быть их слабая сторона».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"дабы тем явнее могла быть их слабая сторона"}]},{"id":"rf4d0d3327c","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Как, по приводимому Радищевым изречению, происходят перемены в природе?","options":["постепенно, без скачков","скачками и переворотами","по произволу случая","кругами, возвращаясь назад"],"explanation":"Силы природы действуют непрестанно и производят перемены постепенные: «Ничто не происходит скоком, говорит Лейбниц, всё в ней постепенно».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Ничто не происходит скоком 60, говорит Лейбниц"}]},{"id":"r48a7213bca","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какое третье посредство, по Радищеву, возможно между мыслящими и немыслящими силами частей, из которых складывается мыслящая сила?","options":["никакого: оно невозможно","смешанные полумыслящие силы","силы, мыслящие лишь во сне","силы, мыслящие по воле Бога"],"explanation":"Силы частей либо сходны с мыслящей силой, либо нет: «Третие посредство кажется быть невозможно».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Третие посредство кажется быть невозможно"}]},{"id":"r45d4746f41","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Почему, по Радищеву, нельзя вообразить уничтожение силы?","options":["это противоречие само в себе","силы невидимы для наших глаз","это запрещает вера в Бога","силы бесконечно малы"],"explanation":"Части тела разлагаются, «но как вообразить разрушение силы? Даже понятие о сём есть противоречие само в себе».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"как вообразить разрушение силы? Даже понятие о сем есть противоречие само в себе"}]},{"id":"re979883fef","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чьи слова «что действует единожды, действует вечно» Радищев приводит в защиту бессмертия?","options":["Гердера","Лейбница","Мендельсона","Боннета"],"explanation":"«Что всеоживляющий, говорит Гердер, к жизни воззвал, живёт; что действует единожды, действует вечно».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Что всеоживляющий, говорит Гердер, к жизни воззвал, живет; что действует единожды, действует вечно"}]},{"id":"r2df7416e8c","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"С какой механической игрушкой Радищев сравнивает человека, если бы в нём не было особой мыслящей силы?","options":["с куклой Вокансона","с часами Гюйгенса","с органом Баха","с машиной Герона"],"explanation":"Без особой силы, возглавляющей все прочие, человек, по Радищеву, был бы автоматом: «ты кукла Вокансонова».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"во главе твоей быть силе; ты кукла Вокансонова"}]},{"id":"rb69286890e","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кто, по Радищеву, написал многие бессмертные сочинения «среди болезни непрестанной»?","options":["Руссо","Вольтер","Гельвеций","Дидро"],"explanation":"В доказательство власти духа над телом Радищев напоминает, что «Руссо многие из своих бессмертных сочинений написал среди болезни непрестанной».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"кто не знает, что Руссо многие из своих бессмертных сочинений написал среди болезни непрестанной"}]},{"id":"r52113e7993","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кто, по Радищеву, страдая слабостью нервов, в старости вознёсся «на высоту своея юности»?","options":["Мендельсон","Кант","Вольтер","Лессинг"],"explanation":"«Мендельсон, страдавший от несказанныя слабости нервов многие лета, мог… ещё в старости своей вознестись паки на высоту своея юности».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Мендельсон 8С, страдавший от несказанныя слабости нервов"}]},{"id":"r781e1d2d6d","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чьи монологи, по Радищеву, прекрасны, но имеют «один порок»?","options":["Гамлета у Шекспира и Катона у Аддисона","Фауста у Гёте и Карла Моора у Шиллера","Федры у Расина и Сида у Корнеля","Прометея у Эсхила и Эдипа у Софокла"],"explanation":"Радищев пишет: «Вы знаете… монолог Гамлета Шекеспирова и единословие Катона Утикского у Аддисона. Они прекрасны, но один в них порок».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Вы знаете единословие или монолог Гамлета Шекеспирова и единословие Катона Утикского у Аддисона58"}]},{"id":"r15150d3d84","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кто, по Радищеву, «помнил ясно» о своём прежнем бытии?","options":["Пифагор","Сократ","Платон","Эмпедокл"],"explanation":"История, по Радищеву, сохранила примеры воспоминаний о прежнем бытии: «Пифагор помнил то ясно, Архий, Аполлоний Тианейский».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Пифагор 01 помнил то ясно, Архий, Аполлоний Тианейский"}]},{"id":"r11138064ea","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кого Радищев ставит в один ряд с Гусом и Галилеем, говоря о гонимых за мысль?","options":["самого себя, сосланного в Илимск","Новикова, заточённого в крепость","Ломоносова, гонимого академиками","Сковороду, странствовавшего всю жизнь"],"explanation":"Без благоприятных обстоятельств «Иоган Гус издыхает во пламени, Галилей влечётся в темницу, друг ваш в Илимск заточается».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Галилей влечется в темницу, друг ваш в Илимск заточается"}]},{"id":"r953e040060","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кого, по Радищеву, время сделало «преобразователями»?","options":["Лютера и Декарта","Гуса и Галилея","Петра и Екатерину","Ньютона и Лейбница"],"explanation":"Время, по Радищеву, отъемлет все препоны: «Лутер стал преобразователь, Декарт преобразователь».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"Лутер стал преобразователь, Декарт преобразователь"}]},{"id":"r683d69ea90","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"С чем, по Радищеву, сравнимо распространение «электра души», однажды возродившегося?","options":["с жидкостями, стремящимися к равновесию","с молнией, сходящей с неба на землю","с огнём, пожирающим сухой лес","с семенем, падающим в добрую землю"],"explanation":"«Электр души, возродяся единожды, изливается во все окрестности и стремится, подобно жидкостям, к равновесию».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. III","url":"","quote":"изливается во все окрестности и стремится, подобно жидкостям, к равновесию"}]},{"id":"r52b3ebbc8e","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Сколько родов доводов в защиту бессмертия души, по итогу Радищева, было приведено?","options":["три","два","четыре","пять"],"explanation":"В начале четвёртой книги Радищев подытоживает: «Доводы наши… были троякие» — метафизические, от постепенности существ и от нашей чувственности.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"Доводы наши, как то вы видели, были троякие"}]},{"id":"r80cbe60867","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Что, по первому, метафизическому доводу Радищева, следует из простоты мыслящего в нас существа?","options":["его неразрушимость, а значит бессмертие","его зависимость от состава всего тела","его происхождение от обоих родителей","его постепенное угасание со старостью"],"explanation":"Мыслящее в нас существо, по Радищеву, «есть простое и несложное, а потому неразрушимое, следовательно, бессмертное».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"есть простое и несложное, а потому неразрушимое, следовательно, бессмертное"}]},{"id":"rf3ecd54c1f","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"На чём, по Радищеву, основан второй род доводов о бессмертии?","options":["на восходящей постепенности существ","на всеобщем согласии всех народов","на свидетельстве Священного Писания","на опыте сновидений и видений"],"explanation":"Второй род доводов основан «на явственной восходящей постепенности всех известных нам существ» — «лествице» творения, во главе которой человек.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"основывался на явственной восходящей постепенности всех известных нам существ"}]},{"id":"r0474e81c84","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"С чем, по уподоблению «умственного исполина», которое приводит Радищев, сравнимо прехождение человека по смерти?","options":["с превращением червяка в бабочку","с переходом ночи в утро","с прорастанием зерна","с переливанием вина в новые мехи"],"explanation":"Лейбниц, по Радищеву, «прехождение человека уподобляет прерождению червяка в бабочку», в котором будущее строение бабочки сохранено в червяке.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"прехождение человека уподобляет прерождению червяка в бабочку"}]},{"id":"rdc156001b8","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Кто, по Радищеву, старается доказать, что душа человеческая всегда будет сопряжена с телом?","options":["Боннет","Гердер","Пристли","Локк"],"explanation":"«Боннет старается доказать, что душа человеческая всегда будет сопряжена с телом» и после смерти человек родится вновь из сохранившегося семени.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"Боннет 102 старается доказать, что душа человеческая всегда будет сопряжена с телом"}]},{"id":"rf1011a6dc8","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какие два пути, по Радищеву, открыты душе после смерти, если без чувств нет новых знаний?","options":["трудиться над прежними мыслями или обрести новое тело","раствориться в мировой душе или уснуть навсегда","переселиться в животное или в другого человека","вернуться в прежнее тело или остаться без тела"],"explanation":"Радищев рассуждает: «или вновь понятия уже приобретать душа не будет, а действовать будет над прежними, или человек будет иметь новую организацию».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"или вновь понятия уже приобретать душа не будет, а действовать будет над прежними, или человек будет иметь новую организацию"}]},{"id":"rcdc6f6986c","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Что, по Радищеву, есть «мета человечества»?","options":["совершенствование и блаженство","познание всех законов природы","покорность воле Творца","продолжение рода"],"explanation":"«Мета человечества есть совершенствование и блаженство, которое есть следствие добродетели». Если бы блаженство кончалось с жизнью, мы были бы игралищем.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"что мета человечества есть совершенствование и блаженство"}]},{"id":"re31b6f854f","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Каким, по Радищеву, не может быть состояние человека по смерти, если его цель — совершенствование?","options":["хуже настоящего","лучше настоящего","таким же, как ныне","телесным"],"explanation":"«Возвратный путь для него невозможен, и состояние его по смерти не может быть хуже настоящего».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"Возвратный путь для него невозможен, и состояние его по смерти не может быть хуже настоящего"}]},{"id":"r7fa56738b6","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Что, по Радищеву, человек сделает «в новой своей организации» после смерти?","options":["исправит свои прежние заблуждения","забудет всё земное и начнёт жизнь заново","получит награду или кару за всё прошлое","соединится с душами предков и друзей"],"explanation":"«В новой своей организации он заблуждения свои исправит, склонности устремит к истине», сохранив приобретённые мысли.","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"в новой своей организации он заблуждения свои исправит, склонности устремит к истине"}]},{"id":"rd3ec4b657a","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Что, по Радищеву, «живёт сосмежна» злоупотреблению дарованиями?","options":["казнь","слава","награда","забвение"],"explanation":"«Берегись, да не употребишь их во зло. Казнь живёт сосмежна злоупотреблению. Ты в себе заключаешь блаженство твоё и злополучие».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"но берегись, да не употребишь их во зло. Казнь живет сосмежна злоупотреблению"}]},{"id":"r3637418261","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Чем, по Радищеву, человек определяет своё будущее?","options":["настоящим","прошлым","судьбой","случаем"],"explanation":"В заключении трактата: «Ты будущее твоё определяешь настоящим; и верь… вечность не есть мечта».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"Ты будущее твое определяешь настоящим"}]},{"id":"rc331146c19","s":1,"topic":"Радищев. «О человеке, о его смертности и бессмертии»","text":"Какими словами Радищев заканчивает трактат «О человеке, о его смертности и бессмертии»?","options":["«вечность не есть мечта»","«смерть есть вечный сон»","«истина одна и вечна»","«человек есть машина»"],"explanation":"Последние слова трактата: «и верь, скажу паки, верь, вечность не есть мечта».","sources":[{"title":"Радищев. О человеке, о его смертности и бессмертии, кн. IV","url":"","quote":"верь, скажу паки, верь, вечность не есть мечта"}]},{"id":"rc0b4fc3065","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Какую загадку древнерусской мысли Флоровский ставит в начало своей книги?","options":["вековое, затяжное русское молчание","отсутствие на Руси летописания","раннее появление русской философии","обилие богословских споров на Руси"],"explanation":"Книга открывается вопросом: «что означает это вековое, слишком долгое и затяжное русское молчание?», то есть позднее пробуждение русской мысли.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 1","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"что означает это вековое, слишком долгое и затяжное русское молчание"}]},{"id":"r21093e4dbd","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Кто, по Флоровскому, утверждал, что древняя Русь до Петра не имела ни образованности, ни даже книжности?","options":["Голубинский","Ключевский","Карамзин","Шевырёв"],"explanation":"«Сейчас уже никто не решится вместе с Голубинским сказать, что древняя Русь вплоть до… Петровского переворота не имела не то что образованности, но даже и книжности».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 1","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Сейчас уже никто не решится вместе с Голубинским сказать"}]},{"id":"r6d078d8723","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Чью точку зрения, по Флоровскому, выражают слова «la miserable Byzance»?","options":["Чаадаева","Герцена","Белинского","Вольтера"],"explanation":"Невысказанность древней Руси иногда объясняли «роковым влиянием жалкой Византии» — «такова была в сущности точка зрения Чаадаева („la miserable Byzance“)».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 1","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"такова была в сущности точка зрения Чаадаева"}]},{"id":"r39384e5190","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"С чего, по Флоровскому, начинается история русской культуры?","options":["с Крещения Руси","с призвания варягов","с основания Киева","с ордынского ига"],"explanation":"«История русской культуры начинается с Крещения Руси. Языческое время остаётся за порогом истории», хотя его следы надолго сохраняются в быту.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 2","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"История русской культуры начинается с Крещения Руси"}]},{"id":"r4d2f9787c4","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Какое воображение, по Флоровскому, слишком долго ускользало в древней Руси от «умного» испытания?","options":["«ночное»","«дневное»","«книжное»","«пророческое»"],"explanation":"Болезненность древнерусского развития Флоровский видит в том, что «„ночное“ воображение слишком долго и слишком упорно укрывается и ускользает от „умного“ испытания».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 2","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"ночное воображение слишком долго и слишком упорно укрывается и ускользает от умного испытания"}]},{"id":"rf981e3b34e","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"В чём, по Флоровскому, изъян и слабость древнерусского духовного развития?","options":["в нехватке аскетического закала","в чрезмерности монашеского аскетизма","в избытке холодной рассудочности","в увлечении латинской схоластикой"],"explanation":"Слабость — «в недостаточности аскетического закала (и совсем уже не в чрезмерности аскетизма)», в чрезмерной «душевности» и «поэтичности».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 2","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"в недостаточности аскетического закала (и совсем уже не в чрезмерности аскетизма)"}]},{"id":"rc608ac2100","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Каким, по Флоровскому, должен быть путь духовного развития?","options":["от стихийной безвольности к ответственности","от наивности к полной сознательности","от веры к научному знанию","от доверчивости к недоверию и критике"],"explanation":"«Путь идёт не от „наивности“ к „сознательности“, и не от „веры“ к „знанию“… Но есть путь от стихийной безвольности к волевой ответственности».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 2","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Но есть путь от стихийной безвольности к волевой ответственности"}]},{"id":"ra87bdb831a","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"К чему, по Флоровскому, было призывом Крещение Руси?","options":["от мечтательности к духовной трезвости","от войны и набегов к мирной торговле","от язычества к греческой учёности","от кочевья к оседлой городской жизни"],"explanation":"«Крещение было пробуждением русского духа, — призыв от „поэтической“ мечтательности к духовной трезвости и раздумью».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Крещение было пробуждением русского духа, – призыв от поэтической мечтательности к духовной трезвости"}]},{"id":"rfa285060ee","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Во что, по Флоровскому, вступала Русь, ещё до Владимира устанавливая связи с Симеоновской Болгарией?","options":["в права на Кирилло-Мефодиевское наследство","в союз против Византийской империи","в общение с Римской Церковью","в права на престол болгарских царей"],"explanation":"Связи Киева с Болгарией и, может быть, Моравией до Владимира, по Флоровскому, были «вхождением в права на Кирилло-Мефодиевское наследство».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Это было вхождением в права на Кирилло-Мефодиевское наследство"}]},{"id":"r105b701697","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Какое учение Флоровский называет «болгарской ересью»?","options":["богомильство","арианство","несторианство","монофелитство"],"explanation":"Из Болгарии времён Косьмы пресвитера уместнее выводить «мрачную доктрину», ведь «богомильство было как раз „болгарской ересью“».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"ведь богомильство было как раз болгарской ересью"}]},{"id":"r02818b45c5","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Кто из славянофилов, по Флоровскому, особенно говорил об «отсутствии классического наследия» как черте различия русской и европейской культур?","options":["Иван Киреевский","Алексей Хомяков","Константин Аксаков","Юрий Самарин"],"explanation":"Об этом «говорили уже давно, говорили именно славянофилы, в частности Иван Киреевский». Флоровский предостерегает от упрощения.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"говорили именно славянофилы, в частности Иван Киреевский"}]},{"id":"r5e5feffc0d","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Чем, по Флоровскому, всегда бывал перевод Библии в народной судьбе?","options":["подлинным событием, сдвигом и подвигом","частным делом немногих учёных книжников","неизбежным поводом к ересям и расколам","данью иноземной моде и вкусам двора"],"explanation":"«Перевод Библии всегда бывал подлинным событием в народной судьбе, означал всегда известный сдвиг и подвиг».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Ведь перевод Библии всегда бывал подлинным событием в народной судьбе"}]},{"id":"rfea0db9d92","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Как, по Флоровскому, о «Слове о законе и благодати» вынужден был отозваться даже самый придирчивый историк Церкви?","options":["как о безупречной академической речи","как о подражании греческим образцам","как о слабом ученическом опыте","как о поздней подделке"],"explanation":"О слове митрополита Илариона даже придирчивый Голубинский «принуждён был отозваться, как о „безупречной академической речи“».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"как о безупречной академической речи"}]},{"id":"r04b3685b9f","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Кто из древнерусских писателей, по Флоровскому, напоминал, что учит и пишет «не от себя, но от книг»?","options":["Кирилл Туровский","Климент Смолятич","Серапион Владимирский","Даниил Заточник"],"explanation":"«Кирилл Туровский и сам напоминал, что учит он и пишет „не от себя, но от книг“» — древнерусские писатели следовали византийской письменности.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 3","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Кирилл Туровский и сам напоминал, что учит он и пишет не от себя, но от книг"}]},{"id":"r7a32f8b682","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Каким, по Флоровскому, был XIII век в истории русской культуры и письменности?","options":["не временем упадка, а начинаний","временем полного оскудения книжности","временем расцвета богословия","временем разрыва с Византией"],"explanation":"«В истории русской культуры и письменности XIII-ый век не был временем упадка и оскудения»: к нему относятся Печерский патерик, Толковая Палея и летописание.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"XIII-ый век не был временем упадка и оскудения"}]},{"id":"rfd3fb5263a","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Каким, по Флоровскому, был XIV век в монашеской жизни Руси?","options":["временем монастырского возрождения","временем упадка и запустения обителей","временем гонений на монахов","временем расцвета городских монастырей"],"explanation":"«XIV-ый век был временем отшельнического и монастырского возрождения, — это век преподобного Сергия».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"XIV-ый век был временем отшельнического и монастырского возрождения"}]},{"id":"r8042de0e37","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Какой, по Флоровскому, была по своему смыслу теория «Третьего Рима» в её первоначальном виде?","options":["эсхатологической","дипломатической","юридической","династической"],"explanation":"«Это была именно эсхатологическая теория»: если Москва — Третий Рим, то и последний, конец приближается.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Это была именно эсхатологическая теория"}]},{"id":"r943b1fab43","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Кому, по Флоровскому, принадлежат слова «Яко два Рима падоша, а третий стоит, а четвёртому не быти»?","options":["старцу Филофею","Иосифу Волоцкому","митрополиту Зосиме","Максиму Греку"],"explanation":"Теория Третьего Рима «у самого старца Филофея… строго выдержана в эсхатологических тонах и категориях».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"у самого старца Филофея она строго выдержана в эсхатологических тонах"}]},{"id":"r5e8b9897c0","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Какой аспект схемы «странствующего Царства», по Флоровскому, был первичным в русском восприятии?","options":["апокалиптический минор","хилиастический мажор","имперское торжество","миссионерский призыв"],"explanation":"В схеме два аспекта — «минор и мажор, апокалиптика и хилиазм», и «в русском восприятии первичным и основным был именно апокалиптический минор».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"В русском восприятии первичным и основным был именно апокалиптический"}]},{"id":"r5a9c53a06b","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Чем, по Флоровскому, в действительности был брак Ивана III с Софией Палеолог?","options":["началом русского западничества","подъёмом византийского влияния","союзом Москвы с турками","разрывом с Литвой"],"explanation":"Часто думают, что брак означал подъём византийского влияния, «а в действительности, напротив, это было началом русского западничества» — «брак Царя в Ватикане».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"А в действительности, напротив, это было началом русского западничества"}]},{"id":"r3c6a3d0812","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"В каком духе, по Флоровскому, была воспитана София Палеолог?","options":["в духе Унии","в духе Афона","в духе Студита","в духе исихастов"],"explanation":"Зоя-София была византийской царевной, «но ведь воспитана она была в Унии, по началам Флорентийского собора».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Но ведь воспитана она была в Унии"}]},{"id":"rfb4ffddecd","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Каких мастеров, по Флоровскому, Иван III вызывал перестраивать Кремль?","options":["итальянских","греческих","немецких","голландских"],"explanation":"«Иван III имел несомненный вкус и склонность к Италии»: он вызывал Аристотеля Фиораванти, Алевиза, Пьетро Солари.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Иван III имел несомненный вкус и склонность к Италии"}]},{"id":"rcc08542169","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Как, по Флоровскому, Курбский называет мать Василия III Софию?","options":["«чародеицей греческой»","«царевной ромейской»","«латинской прелестью»","«византийской вдовой»"],"explanation":"Василий III — сын «„чародеицы греческой“ (так называет Софию Курбский)».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"сына чародеицы греческой (так называет Софию Курбский)"}]},{"id":"r1d40ab36db","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"С кем, по мнению Забелина, приводимому Флоровским, сравнимы действия Ивана III?","options":["с Макиавелли","с Карлом Великим","с Юстинианом","с Людовиком XI"],"explanation":"«Забелин не без основания говорил, что в действиях Ивана III многое заставляет вспоминать о Маккиавели».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 4","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Забелин не без основания говорил, что в действиях Ивана III многое заставляет вспоминать о Маккиавели"}]},{"id":"r9d5076d6fe","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Каким движением, по Флоровскому, была «ересь стригольников»?","options":["прежде всего противоиерархическим","прежде всего иудействующим","прежде всего астрологическим","прежде всего монашеским"],"explanation":"В Новгороде XIV века «эта „ересь стригольников“ была, кажется, прежде всего противо-иерархическим движением».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 5","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"эта ересь стригольников была, кажется, прежде всего противо-иерархическим движением"}]},{"id":"rb639023d74","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Чьи сочинения, по Флоровскому, переводились в кругах «жидовствующих»?","options":["Маймонида и Аль-Газали","Аристотеля и Платона","Фомы Аквинского и Дунса Скота","Авиценны и Аверроэса"],"explanation":"В кругах жидовствующих ходили библейские переводы с еврейского, астрологические книги, «ещё переводы из Маймонода и Ал-Газали».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 5","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"еще переводы из Маймонода и Ал-Газали"}]},{"id":"r69ea6e47e2","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Чем, по Флоровскому, была прежде всего «ересь жидовствующих»?","options":["брожением умов","стройной системой","иудейской миссией","боярским заговором"],"explanation":"«„Ересь жидовствующих“ была прежде всего брожением умов»; по словам Иосифа, «вси о вере пытают».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 5","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Ересь жидовствующих была прежде всего брожением умов"}]},{"id":"r3cd28d2444","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Что, по Флоровскому, вернее всего можно сказать о «еретическом сообществе» жидовствующих?","options":["что его вообще не было","что оно было тайным орденом","что им правили из Литвы","что оно было многочисленным"],"explanation":"«Всего вернее, что еретического сообщества и вообще не было. Были известные настроения, именно „шатание умов“, вольнодумство».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 5","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Всего вернее, что еретического сообщества и вообще не было"}]},{"id":"rcc53d8d4ba","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Какое латинское сочинение, по Флоровскому, перевели «в Архиепископском дому» при Геннадии?","options":["трактат Дурантия о богослужении","«Сумму теологии» Фомы Аквинского","«Подражание Христу» Фомы Кемпийского","«Молот ведьм» Шпренгера и Инститориса"],"explanation":"Для работы над богослужебным Уставом была переведена «знаменитая книга Дурантия, Rationale divinorum officiorum».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 5","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"знаменитая книга Дурантия, Rationale divinorum officiorum"}]},{"id":"ra7835b2448","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"На пример какого государя, по Флоровскому, ссылались, требуя градской казни еретиков?","options":["испанского короля","французского короля","английского короля","польского короля"],"explanation":"Флоровский напоминает «об острой постановке вопроса о градской казни еретиков со ссылкой на „спанского короля“», очистившего свою землю.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 5","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"со ссылкой на спанского короля"}]},{"id":"r7657299a7b","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Кто, по Флоровскому, был гораздо крепче привержен старине?","options":["заволжцы","осифляне","жидовствующие","стригольники"],"explanation":"Осифлян неверно изображают традиционалистами: «Гораздо крепче привержены старине именно противники осифлян, заволжцы».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 6","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Гораздо крепче привержены старине именно противники осифлян, заволжцы"}]},{"id":"r38806e4eac","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Как, по Флоровскому, один из сотрудников называет митрополита Макария, задумавшего собрать все книги, читаемые на Руси?","options":["«вторым Филадельфом»","«новым Златоустом»","«русским Дамаскином»","«вторым Константином»"],"explanation":"Замысел собрать все книги «чтомые в Русской земле» принадлежит осифлянину Макарию: «„Вторым Филадельфом“ называет его один из его сотрудников».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 6","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Вторым Филадельфом5 называет его один из его сотрудников"}]},{"id":"re4dc1ca8f4","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Кем, по Флоровскому, входит в историю преподобный Нил Сорский, не будучи ни мыслителем, ни богословом?","options":["учителем безмолвия, старцем","обличителем ересей","строителем монастырей","переводчиком отеческих книг"],"explanation":"Нил «не был ни мыслителем, ни писателем, ни богословом. В историю он входит, однако, именно как „старец“ или учитель, учитель безмолвия».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 6","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"В историю он входит, однако, именно как старец или учитель, учитель безмолвия"}]},{"id":"rb0a07c5058","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Как Орест Миллер, по Флоровскому, назвал заволжцев?","options":["«духовным ополчением»","«северной Фиваидой»","«малым стадом»","«братством молчальников»"],"explanation":"«Орест Миллер назвал как-то Заволжцев „духовным ополчением“. Это был некий духовный отбор».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 6","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Орест Миллер назвал как-то Заволжцев духовным ополчением"}]},{"id":"ra46a4d365b","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"К какому противопоставлению, по Флоровскому, сводится разногласие осифлян и заволжцев?","options":["внешняя работа в мире или преображение человека","любовь к Москве или верность вольному Новгороду","греческий или латинский образец благочестия","книжная учёность или простая неграмотность"],"explanation":"Разногласие сводится к противопоставлению: «завоевание мира на путях внешней работы в нём или преодоление мира через преображение и воспитание нового человека».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 6","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"завоевание мира на путях внешней работы в нем или преодоление мира через преображение"}]},{"id":"rf107177913","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"О чём, по Флоровскому, свидетельствовало осуждение Максима Грека?","options":["об отрыве от византийского преемства","о торжестве нестяжателей","о влиянии латинян на Москву","о слабости великокняжеской власти"],"explanation":"«Осуждение Максима означало и свидетельствовало отрыв от Византийского преемства, отречение от его творческого продолжения».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 6","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Осуждение Максима означало и свидетельствовало отрыв от Византийского преемства"}]},{"id":"ra63f3a72fb","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"С чем Виппер, по Флоровскому, сравнивает Стоглав?","options":["с Тридентским собором","с Флорентийским собором","с Аугсбургским рейхстагом","с Лионским собором"],"explanation":"Виппер сравнивает время Макария с «католической реформацией», «а в Стоглаве видит некое подобие Тридентского собора».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 7","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"а в Стоглаве видит некое подобие Тридентского собора"}]},{"id":"rcb581e26e7","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Чем, по Флоровскому, был «Домострой»?","options":["скорее программой, чем описанием быта","точной записью московских нравов","сборником народных пословиц","переводом латинского трактата"],"explanation":"«„Домострой“, такой типический памятник этой эпохи, был ведь скорее партийной программой» — книга дидактическая, а не описательная.","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 7","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Домострой, такой типический памятник этой эпохи, был ведь скорее партийной программой"}]},{"id":"ra188eb2db8","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Что, по Флоровскому, смущало дьяка Висковатого в новой иконографии XVI века?","options":["отступление от Евангелия к ветхозаветным «сеням»","подражание латинской и немецкой живописи","слишком яркие краски и обилие золота","изображение живых людей и государей"],"explanation":"Висковатого беспокоила не новизна, а замысел: «Он увидел в ней как бы отступление в Ветхий Завет», от Евангельской «истины» к пророческим «образам».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 7","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"Он увидел в ней как бы отступление в Ветхий Завет"}]},{"id":"r5e2b1c6d50","s":1,"topic":"Флоровский. «Пути русского богословия»: древняя Русь","text":"Против чьей пропаганды, по Флоровскому, была составлена книга Зиновия Отенского «Истины показание»?","options":["Феодосия Косого","Матвея Башкина","старца Артемия","Максима Грека"],"explanation":"Книга Зиновия Отенского «Истины показание, к вопросившим о новом учении» составлена «в ответ на недоумения, вызванные пропагандой Феодосия Косого».","sources":[{"title":"Флоровский. Пути русского богословия, гл. I, § 7","url":"https://azbyka.ru/otechnik/Georgij_Florovskij/puti-russkogo-bogoslovija/","quote":"составленной в ответ на недоумения, вызванные пропагандой Феодосия Косого"}]},{"id":"r8673c3450b","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"С какого века, по Зеньковскому, должна начинать своё исследование история русской философии?","options":["с XVIII века","с XI века","с XVI века","с XIX века"],"explanation":"До XVIII века в России нет «никаких самостоятельных трудов или набросков философского характера», хотя философские запросы жили и раньше.","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"история русской философии должна начинать свое исследование лишь с XVIII в."}]},{"id":"rbcabfbc427","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Каким, по Зеньковскому, всегда был аскетизм у русских людей?","options":["производным явлением","главной основой веры","гнушением миром","заимствованием с Запада"],"explanation":"Мнение о преувеличенном аскетизме и «гнушении миром» Зеньковский считает неверным: «Аскетизм у русских людей всегда был явлением производным».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"Аскетизм у русских людей всегда был явлением производным"}]},{"id":"r6f69137baa","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Какой образ, по Зеньковскому, особенно излюблен в русском церковном сознании?","options":["образ «света»","образ «креста»","образ «пустыни»","образ «града»"],"explanation":"Аскетизм есть путь к преображению мира; поэтому излюблен образ «света» — свою веру народ называет «пресветлое Православие».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"почему так излюблен в русском церковном сознании образ света"}]},{"id":"r084db2b323","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Какую черту, по Зеньковскому, «красной чертой» проходящую через историю русской духовной жизни, он связывает с природными особенностями русской души?","options":["максимализм","рационализм","индивидуализм","квиетизм"],"explanation":"Зеньковский отмечает русский «максимализм», «проходящий красной чертой через всю историю духовной жизни в России», и выводит его не из религии, а из природных особенностей.","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"проходящий красной чертой через всю историю духовной жизни в России"}]},{"id":"rae8f5b1c5d","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Каким, по Зеньковскому, было юродство в греческой Церкви по сравнению с русской?","options":["довольно редким явлением","самым распространённым подвигом","запрещённым соборами делом","неизвестным вовсе явлением"],"explanation":"Юродство было очень распространено в России; оно было и в греческой Церкви, «но сравнительно с русской церковной действительностью оно было там редким явлением».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"оно было там редким явлением"}]},{"id":"r17aecbe269","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Какой поклонник Якоба Бёме, по Зеньковскому, погиб в Москве в конце XVII века за свою проповедь?","options":["Квирин Кульман","Иоганн Арндт","Пьер Пуаре","Валентин Вейгель"],"explanation":"Когда «заезжий поклонник Я. Беме, Квирин Кульман» стал проповедовать в Москве хилиастические учения, он «был схвачен и погиб мученической смертью».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"Квирин Кульман (немец из Бреславля), появился в Москве"}]},{"id":"r5d9e4785d7","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"В каком направлении, по Зеньковскому, развивалась в России теократическая тема христианства?","options":["к усвоению государству священной миссии","к первенству духовной власти над светской","к полному отделению Церкви от государства","к подчинению царя патриарху"],"explanation":"Теократическая тема развивается «не в смысле примата духовной власти над светской, как это случилось на Западе, а в сторону усвоения государственной власти священной миссии».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"а в сторону усвоения государственной власти священной миссии"}]},{"id":"rea973bd5ca","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"В каком памятнике, по Зеньковскому, утверждается избрание свыше русской Церкви для хранения истины Христовой?","options":["в повести о Белом клобуке","в сказании о граде Китеже","в повести о Петре и Февронии","в сказании о Мамаевом побоище"],"explanation":"К концу XV века относится «замечательная легенда о „Белом клобуке“, в которой утверждается избрание свыше русской Церкви».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"возникновение замечательной легенды о Белом клобуке30"}]},{"id":"rb255a38670","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Когда, по Зеньковскому, впервые выдвигается учение о «святой Руси» и всемирном значении России?","options":["в XVI веке","в XII веке","в XVIII веке","в XIX веке"],"explanation":"«Как раз в XVI веке впервые выдвигается учение о „святой Руси“, об универсальном всемирном значении России».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. I","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"Как раз в XVI веке впервые выдвигается учение о святой Руси"}]},{"id":"r6b849ff151","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Как Зеньковский называет XVIII век в России?","options":["веком «секуляризации»","веком «возрождения»","веком «реформации»","веком «мистицизма»"],"explanation":"«XVIII век в России есть век „секуляризации“»: возникает светская культура, а церковное сознание отрывается от мечты о священной миссии государства.","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. II","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"XVIII век в России есть век секуляризации"}]},{"id":"r5f86530e40","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"С чьим именем, по Зеньковскому, связана вся история русского старчества, особенно Оптиной пустыни?","options":["Паисия Величковского","Тихона Задонского","Серафима Саровского","Нила Сорского"],"explanation":"Старец Паисий Величковский (1722–1794) — тот, «с именем которого связана вся история русского старчества, особенно знаменитой Оптиной пустыни».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. II","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"с именем которого связана вся история русского старчества, особенно знаменитой Оптиной пустыни"}]},{"id":"ra6630c246b","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Кого Зеньковский называет первым философом на Руси «в точном смысле слова»?","options":["Сковороду","Ломоносова","Радищева","Новикова"],"explanation":"«Григорий Саввич Сковорода (1722–1794) примечателен, как первый философ на Руси в точном смысле слова».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. II","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"примечателен, как первый философ на Руси в точном смысле слова"}]},{"id":"ra792311527","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Кем, по собственным словам Сковороды, приводимым Зеньковским, он пожелал быть «на Руси»?","options":["Сократом","Диогеном","Платоном","Эпикуром"],"explanation":"Сковороду зовут «русским Сократом»; он и сам писал, что «замыслил умом и пожелал волею быть Сократом на Руси».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. II","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"замыслил умом и пожелал волею быть Сократом на Руси"}]},{"id":"r75e0a91a7b","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Какие слова, по Зеньковскому, были помещены в эпитафии на могиле Сковороды?","options":["«Мир ловил меня, но не поймал»","«Истина Господня, а не бесовская»","«Всяк есть то, каково сердце в нём»","«Трудно жить в несродном деле»"],"explanation":"На могиле Сковороды помещена сочинённая им самим эпитафия: «Мир ловил меня, но не поймал».","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. II","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"Мир ловил меня, но не поймал"}]},{"id":"r496b58ae1f","s":1,"topic":"Зеньковский. «История русской философии»: до XIX века","text":"Какое понятие, по Зеньковскому, становится центральным в этике Сковороды?","options":["«сродность»","«соборность»","«всеединство»","«смирение»"],"explanation":"Страдания человека — от жизни против того, к чему он создан: «Какое мучение… трудиться в несродном деле». Понятие «сродности» становится центральным.","sources":[{"title":"Зеньковский. История русской философии, ч. I, гл. II","url":"https://azbyka.ru/otechnik/Vasilij_Zenkovskij/istorija-russkoj-filosofii/","quote":"Понятие сродности или следования своему призванию становится центральным в этике Сковороды"}]},{"id":"r866860cf23","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Что, по Чаадаеву, разделяет народы и питает национальную ненависть?","options":["любовь к родине","любовь к истине","религиозная вражда","торговое соперничество"],"explanation":"В «Апологии сумасшедшего» Чаадаев противопоставляет два чувства: любовь к родине разделяет народы и подчас «одевает землю в траур», а любовь к истине распространяет свет знания. Религиозная вражда и торговля здесь не обсуждаются.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Любовь к родине разделяет народы, питает национальную ненависть"}]},{"id":"r853528e814","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Кого, по Чаадаеву, создаёт любовь к истине?","options":["мудрецов, благодетелей человечества","героев, защитников своего отечества","пророков и мучеников за истинную веру","законодателей и мудрых государей"],"explanation":"По Чаадаеву, любовь к отечеству рождает героев, а любовь к истине создаёт мудрецов, благодетелей человечества. Пророков и законодателей он в этом сравнении не называет.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"любовь к истине создает мудрецов, благодетелей человечества"}]},{"id":"r4bd98b7b98","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Кого Чаадаев противопоставляет английскому гражданину, говоря о разных способах любить своё отечество?","options":["самоеда","киргиза","лапландца","чукчу"],"explanation":"Чаадаев пишет, что самоед, любящий свои снега и задымлённую юрту, любит страну иначе, чем английский гражданин, гордый учреждениями своего острова. Киргизов, лапландцев и чукчей он в этом месте не упоминает.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Есть разные способы любить свое отечество; например, самоед"}]},{"id":"reeda606140","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Как Чаадаев заканчивает фразу «Я не научился любить свою родину…»?","options":["с закрытыми глазами и запертыми устами","вдали от неё, глядя из чужих краёв","по книгам, летописям и преданиям","без веры в её будущее величие"],"explanation":"Полностью: «Я не научился любить свою родину с закрытыми глазами, с преклонённой головой, с запертыми устами». Чаадаев считает, что полезен стране лишь тот, кто ясно её видит.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Я не научился любить свою родину с закрытыми глазами, с преклоненной головой, с запертыми устами"}]},{"id":"r4100c8679f","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Кто, по словам Чаадаева, научил его любить отечество?","options":["Пётр Великий","Екатерина Великая","Александр I","Иван Грозный"],"explanation":"Чаадаев пишет: «Я люблю моё отечество, как Пётр Великий научил меня любить его». Петровская любовь к родине для него — трезвая и обращённая к будущему.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Я люблю мое отечество, как Петр Великий научил меня любить его"}]},{"id":"r4167ecfcc1","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Для чего, по Чаадаеву, Россия «пришла после других» народов?","options":["чтобы делать лучше и не повторять их ошибок","чтобы веками смиренно учиться у них","чтобы сохранить веру, утраченную ими","чтобы спасти их от упадка и гибели"],"explanation":"Чаадаев полагает, что мы пришли после других, «чтобы делать лучше их, чтобы не впадать в их ошибки, в их заблуждения и суеверия». Повторять «весь длинный ряд безумств» других народов Россия не обречена.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Я полагаю, что мы пришли после других для того, чтобы делать лучше их"}]},{"id":"raf6e733136","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Что, по глубокому убеждению Чаадаева, Россия призвана решить?","options":["проблемы социального порядка","спор Востока и Запада о вере","освобождение славянских народов","соединение христианских Церквей"],"explanation":"Чаадаев пишет, что мы призваны решить большую часть проблем социального порядка и ответить на важнейшие вопросы, занимающие человечество. Освобождение славян и соединение Церквей здесь не упоминаются.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"мы призваны решить большую часть проблем социального порядка"}]},{"id":"rd19a60cdc8","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Кем, по Чаадаеву, Россия «самой природой вещей» предназначена быть в тяжбах человеческого духа?","options":["совестным судом","третейским посредником","беспристрастным свидетелем","последней апелляцией"],"explanation":"Чаадаев охотно повторяет, что мы предназначены быть «настоящим совестным судом» по многим тяжбам, которые ведутся перед великими трибуналами человеческого духа и общества.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"предназначены быть настоящим совестным судом по многим тяжбам"}]},{"id":"rd2af7875bc","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Что, по образу Чаадаева, Пётр Великий написал на «листе белой бумаги», который нашёл у себя дома?","options":["слова «Европа» и «Запад»","слова «Империя» и «Флот»","слова «Наука» и «Просвещение»","слова «Порядок» и «Закон»"],"explanation":"По Чаадаеву, Пётр нашёл дома лишь лист белой бумаги и своей сильной рукой написал на нём слова Европа и Запад, — «и с тех пор мы принадлежим к Европе и Западу».","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"своей сильной рукой написал на нем слова Европа и Запад"}]},{"id":"r51cca88710","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Почему, по Чаадаеву, преобразования Петра оказались возможны?","options":["прошлое не давало повода сопротивляться","Пётр опирался на поддержку дворянства","народ устал от смут и долгих войн","Церковь поддержала преобразования"],"explanation":"Чаадаев считает, что Пётр мог безнаказанно стереть воспоминания нации, потому что в нашем прошлом «не было ничего, что могло бы оправдать сопротивление». О дворянстве, смутах и Церкви он здесь не говорит.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"в нашем прошлом не было ничего, что могло бы оправдать сопротивление"}]},{"id":"r283f61dcbc","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Каким, по Чаадаеву, Пётр стал на Западе и каким вернулся в Россию?","options":["там самым малым, а дома самым великим","там учеником, а дома врагом Запада","там простым плотником, а дома мастером","там великим, а дома униженным"],"explanation":"Чаадаев пишет, что Пётр «сам пошёл в страны Запада и стал там самым малым, а к нам вернулся самым великим»; он преклонился пред Западом и стал нашим законодателем.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"стал там самым малым, а к нам вернулся самым великим"}]},{"id":"rc79ecc7b94","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"От чего, по Чаадаеву, Пётр полтораста лет назад «пред лицом всего мира» отрёкся?","options":["от старой России","от византийского наследства","от московского патриаршества","от союза с православным Востоком"],"explanation":"По Чаадаеву, Пётр отрёкся от старой России, смёл её учреждения и вырыл пропасть между нашим прошлым и настоящим. Патриаршество и Византия в этой фразе не названы.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"полтораста лет назад пред лицом всего мира отрекся от старой России"}]},{"id":"rf465503b76","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Чем, по Чаадаеву, является деление мира на Восток и Запад, кроме географического деления?","options":["порядком вещей, заданным природой разума","следствием различия климатов и почв","наследием распада Римской империи","плодом разделения Церквей"],"explanation":"Чаадаев пишет, что это «не только географическое деление, но также и порядок вещей, обусловленный самой природой разумного существа»: два принципа, две идеи, обнимающие жизнь человечества.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Это не только географическое деление, но также и порядок вещей"}]},{"id":"ra8ca18ce19","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Как, по Чаадаеву, созидался человеческий ум на Востоке?","options":["углубляясь и замыкаясь в самом себе","раскидываясь вовне во все стороны","опираясь на опыт и наблюдение","соединяя веру с наукой"],"explanation":"На Востоке ум созидался, «сосредоточиваясь, углубляясь, замыкаясь в самом себе», а на Западе развивался, «раскидываясь вовне, излучаясь во все стороны». Опыт и соединение веры с наукой здесь не упомянуты.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Сосредоточиваясь, углубляясь, замыкаясь в самом себе, созидался человеческий ум на Востоке"}]},{"id":"rcca6c8d2b2","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"На каком принципе, по Чаадаеву, Запад основал власть?","options":["на принципе права","на принципе традиции","на принципе веры","на принципе силы"],"explanation":"Чаадаев пишет: на Западе идея, вступаясь за все нужды человека, «основала власть на принципе права». На Востоке мысль ушла в себя и предоставила распоряжение земными благами общественной власти.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"основала власть на принципе права"}]},{"id":"r5081d4e392","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Как, по Чаадаеву, Запад поступил с трудами Востока?","options":["овладел ими и кончил начатое Востоком","отверг их как восточные суеверия","сохранил их, ничего не прибавив","вернул их Востоку очищенными"],"explanation":"По Чаадаеву, первым выступил Восток, затем пришёл Запад со своей деятельностью и анализом, «овладел его трудами, кончил начатое Востоком» и поглотил его в своём широком обхвате.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"овладел его трудами, кончил начатое Востоком"}]},{"id":"r83dd123626","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Что, по Чаадаеву, идея Востока поставила во главу общества?","options":["духовное начало","светскую власть","родовой обычай","торговый интерес"],"explanation":"Идея Востока, по Чаадаеву, «поставила духовное начало во главу общества» и подчинила все власти закону истории. В России, напротив, духовное начало всегда было подчинено светскому.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Эта идея поставила духовное начало во главу общества"}]},{"id":"r659b3c068a","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Какая судьба, по Чаадаеву, ждёт плодотворную идею Востока?","options":["ей уже не суждено снова проявиться","ей суждено возродиться в России","ей суждено слиться с идеей Запада","ей суждено со временем покорить Запад"],"explanation":"Чаадаев признаёт, что идея Востока в своё время обусловила громадное развитие разума, «но которой уже не суждено снова проявиться на мировой сцене». Возрождение в России он прямо отвергает: мы никогда не принадлежали к Востоку.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"но которой уже не суждено снова проявиться на мировой сцене"}]},{"id":"r4584019aba","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Как Чаадаев отвечает тем, кто провозглашает русских «любимыми детьми Востока»?","options":["Россия не принадлежит к Востоку","Россия — мост между Востоком и Западом","Россия — Восток, обращённый к Западу","Россия — особый мир между ними"],"explanation":"Чаадаев пишет: «Мы живём на востоке Европы — это верно, и тем не менее мы никогда не принадлежали к Востоку». У Востока своя история, не имеющая ничего общего с нашей.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Мы живем на востоке Европы — это верно, и тем не менее мы никогда не принадлежали к Востоку"}]},{"id":"r1fd7d2851a","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Как Чаадаев называет течение, которое хочет «разрушить создание Петра Великого» и «снова уйти в пустыню»?","options":["новая школа","старая партия","народная партия","восточная секта"],"explanation":"«Но вот является новая школа. Больше не нужно Запада…» — так Чаадаев говорит о славянофилах, которые отвергают и Европу, и Петра и объявляют нас «любимыми детьми Востока».","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Но вот является новая школа. Больше не нужно Запада"}]},{"id":"r8ae2c0a97e","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Каким выражением Чаадаев называет искателей русской старины, «откапывающих диковинки для наших музеев»?","options":["«наши фанатические славяне»","«наши ревнители старины»","«наши любители древностей»","«наши народолюбцы»"],"explanation":"Чаадаев сомневается, что «наши фанатические славяне» сумеют извлечь из исторической почвы то, что заполнит пустоту наших душ. Остальные выражения в «Апологии» не встречаются.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Возможно, конечно, что наши фанатические славяне при их разнообразных поисках"}]},{"id":"rae0d9ebc7f","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Кто, по Чаадаеву, «звучным слогом» рассказал о делах и подвигах русских государей?","options":["Карамзин","Татищев","Ломоносов","Щербатов"],"explanation":"Чаадаев перечисляет: немецкие учёные открыли наших летописцев, потом Карамзин звучным слогом рассказал о делах государей, а ныне плохие писатели и неудавшиеся поэты бродят по старине. Татищев, Ломоносов и Щербатов здесь не названы.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"потом Карамзин рассказал звучным слогом дела и подвиги наших государей"}]},{"id":"rfec09b7c1c","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Кто, по Чаадаеву, пятьдесят лет назад «открыл наших летописцев»?","options":["немецкие учёные","монастырские книжники","французские просветители","московские антиквары"],"explanation":"По «Апологии», пятьдесят лет назад наших летописцев открыли немецкие учёные, и лишь после этого начался интерес к русской старине.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Пятьдесят лет назад немецкие ученые открыли наших летописцев"}]},{"id":"r083648cd9b","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Какой патриотизм, по признанию Чаадаева, ему чужд?","options":["блаженный патриотизм лени","воинственный патриотизм толпы","казённый патриотизм чиновников","книжный патриотизм учёных"],"explanation":"Чаадаеву чужд «блаженный патриотизм лени», который всё видит в розовом свете и носится со своими иллюзиями. Он считает, что время слепых влюблённостей прошло.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"Мне чужд, признаюсь, этот блаженный патриотизм лени"}]},{"id":"rf4502b307f","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Что, по Чаадаеву, «отнюдь не тождественно с безусловным разумом»?","options":["общее мнение","личное убеждение","церковное предание","научное знание"],"explanation":"Чаадаев не согласен с «одним великим писателем», считавшим общее мнение тождественным безусловному разуму. По его убеждению, инстинкты масс более страстны и эгоистичны, чем инстинкты отдельного человека.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"что общее мнение отнюдь не тождественно с безусловным разумом"}]},{"id":"ra09e6380f4","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"За кем, по Чаадаеву, должен следовать род человеческий, чтобы идти по пути истинного прогресса?","options":["за естественными вождями, помазанниками Бога","за большинством, выражающим волю всего народа","за учёными, открывающими законы природы","за собственной совестью каждого человека"],"explanation":"Чаадаев пишет, что никогда не искал народных рукоплесканий: род человеческий должен следовать за естественными вождями, получившими от неба назначение и силу вести его.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"род человеческий должен следовать только за своими естественными вождями, помазанниками Бога"}]},{"id":"rf4a529842f","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Как Чаадаев характеризует инстинкты масс в сравнении с инстинктами отдельного человека?","options":["они более страстны, узки и эгоистичны","они более здоровы и бескорыстны","они более верны и долговечны","они более робки и покорны"],"explanation":"Чаадаев считает, что инстинкты масс «бесконечно более страстны, более узки и эгоистичны», чем инстинкты отдельного человека, а так называемый здравый смысл народа вовсе не есть здравый смысл.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"инстинкты масс бесконечно более страстны, более узки и эгоистичны"}]},{"id":"r767e735ab9","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"В чём, по Чаадаеву, «большое преимущество» положения России?","options":["судить мир с высоты бесстрастной мысли","хранить древнюю веру нетронутой","владеть огромными пространствами","жить в единстве царя и народа"],"explanation":"Чаадаев считает положение России счастливым: она может «созерцать и судить мир со всей высоты мысли», свободной от страстей и корыстей, которые в других местах мутят взор человека.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"иметь возможность созерцать и судить мир со всей высоты мысли"}]},{"id":"r5099667a81","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"Перед кем, по «Апологии», Чаадаев «в один прекрасный день» очутился, когда его мысль «бросилась на улицу»?","options":["перед разгневанной публикой","перед судом сената","перед следственной комиссией","перед собранием дворянства"],"explanation":"Чаадаев недоумевает, как его мысль, долго известная в тесном кругу, «бежала из своего монастыря и бросилась на улицу», а он очутился перед разгневанной публикой, чьих похвал никогда не искал.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"в один прекрасный день я очутился перед разгневанной публикой"}]},{"id":"r202ffd38d0","s":2,"topic":"Чаадаев. «Апология сумасшедшего»","text":"По чьему приговору, как с горечью пишет Чаадаев, он был «поражён безумием»?","options":["по приговору высшей юрисдикции","по приговору общественного мнения","по приговору церковного суда","по приговору собственной совести"],"explanation":"Чаадаев пишет о человеке, «поражённом безумием по приговору высшей юрисдикции», — намёк на то, что после публикации «Философического письма» власти официально объявили его сумасшедшим.","sources":[{"title":"Чаадаев. Апология сумасшедшего","url":"http://www.vehi.net/chaadaev/apologiya.html","quote":"человек, пораженный безумием по приговору высшей юрисдикции"}]},{"id":"re992c66ce1","s":2,"topic":"Хомяков. «Церковь одна»","text":"Из чего, по Хомякову, необходимо следует единство Церкви?","options":["из единства Божия","из единства епископата","из единства Символа веры","из единства обряда"],"explanation":"Первая же фраза «Церковь одна»: единство Церкви «следует необходимо из единства Божьего». Епископат, Символ и обряд — проявления жизни Церкви, а не основание её единства.","sources":[{"title":"Хомяков. Церковь одна, гл. 1 «Единство Церкви»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Единство Церкви следует необходимо из единства Божьего"}]},{"id":"r80f1557127","s":2,"topic":"Хомяков. «Церковь одна»","text":"Чем, по Хомякову, является Церковь?","options":["единство благодати, живущей во многих творениях","союз лиц, исповедующих одну и ту же веру","общество верующих под властью епископов","собрание поместных общин одного обряда"],"explanation":"По Хомякову, Церковь «не есть множество лиц в их личной отдельности, но единство Божией благодати», живущей во множестве разумных творений, покоряющихся благодати. Понимание Церкви как союза или общества лиц он отвергает.","sources":[{"title":"Хомяков. Церковь одна, гл. 1 «Единство Церкви»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Церковь не есть множество лиц в их личной отдельности, но единство Божией благодати"}]},{"id":"ra4a453a704","s":2,"topic":"Хомяков. «Церковь одна»","text":"В каком отношении, по Хомякову, допустимо делить Церковь на видимую и невидимую?","options":["только в отношении к человеку","только в отношении к таинствам","в отношении к церковной иерархии","в отношении к Самому Богу"],"explanation":"Хомяков пишет, что раздел на видимую и невидимую можно признавать «только в отношении к человеку», ещё живущему на земле; единство же Церкви истинное и безусловное.","sources":[{"title":"Хомяков. Церковь одна, гл. 1 «Единство Церкви»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Только в отношении к человеку можно признавать раздел Церкви на видимую и невидимую"}]},{"id":"r3e713b0b3f","s":2,"topic":"Хомяков. «Церковь одна»","text":"Кто, кроме живущих ныне, по Хомякову, соединён в одной Церкви?","options":["усопшие, ангелы и будущие поколения","одни прославленные святые","праведники Ветхого Завета, но не ангелы","крещёные, но ещё не рождённые не входят"],"explanation":"В одной Церкви, по Хомякову, соединены и совершившие земной путь, и не созданные для него ангелы, и будущие поколения, ещё не начавшие земного пути.","sources":[{"title":"Хомяков. Церковь одна, гл. 1 «Единство Церкви»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"не созданный для земного пути (как ангелы), не начинавший еще земного пути (будущие поколения)"}]},{"id":"rb3d2e1098e","s":2,"topic":"Хомяков. «Церковь одна»","text":"Кого, по Хомякову, земная Церковь признаёт не принадлежащими ей?","options":["тех, кто сам от неё отлучается","всех некрещёных людей","всех, кто не знает её учения","всех грешников, не принёсших покаяния"],"explanation":"Земная Церковь, по Хомякову, «не судит остальному человечеству» и признаёт отлучёнными лишь тех, «которые от неё сами отлучаются».","sources":[{"title":"Хомяков. Церковь одна, гл. 2 «Церковь видимая и невидимая»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"признавая отлученными, т.е. не принадлежащими ей, тех, которые от нее сами отлучаются"}]},{"id":"rda68dfcbf9","s":2,"topic":"Хомяков. «Церковь одна»","text":"Какие признаки Церкви Хомяков называет в главе «Церковь Христова на земле»?","options":["внутреннюю святость и внешнюю неизменность","древность и всемирное распространение","единство иерархии и обряда","чудеса и подвиг мученичества"],"explanation":"Признаки Церкви, по Хомякову, — внутренняя святость, не допускающая примеси лжи, и внешняя неизменность, ибо неизменен её Хранитель и Глава Христос.","sources":[{"title":"Хомяков. Церковь одна, гл. 3 «Церковь Христова на земле»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Признаки же ее суть: внутренняя святость, не дозволяющая никакой примеси лжи"}]},{"id":"r9befd348ca","s":2,"topic":"Хомяков. «Церковь одна»","text":"Почему, по Хомякову, признаки Церкви непонятны чуждым и непризванным?","options":["изменение обряда кажется им изменением Духа","им недоступны церковные книги","они судят о Церкви по поведению клира","они не знают истории Вселенских Соборов"],"explanation":"Хомяков пишет, что внешнее изменение обряда представляется непризванному изменением самого Духа, прославляемого в обряде. Признаки Церкви познаются лишь ею самой и призванными благодатью.","sources":[{"title":"Хомяков. Церковь одна, гл. 3 «Церковь Христова на земле»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"внешнее изменение обряда представляется непризванному изменением самого Духа"}]},{"id":"rb2a02b7c75","s":2,"topic":"Хомяков. «Церковь одна»","text":"Как Хомяков раскрывает слово «соборная» в Символе веры?","options":["кафолическая, принадлежащая всему миру","основанная на решениях Вселенских Соборов","управляемая собором епископов","собранная многими народами под одним главой"],"explanation":"Церковь называется соборной, то есть «кафолической и вселенской», потому что принадлежит всему миру, а не какой-нибудь местности. Соборы и власть епископов здесь не составляют смысла слова.","sources":[{"title":"Хомяков. Церковь одна, гл. 4 «Едина, Святая, Соборная и Апостольская»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"называется единою, святою, соборною (кафолической и вселенской), апостольской"}]},{"id":"r237dd606f6","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, означает название вроде «российская Церковь»?","options":["собрание членов Церкви в одной стране","самостоятельную Церковь со своим учением","особую ветвь Вселенской Церкви","общину, вправе самой толковать догматы"],"explanation":"Название местной Церкви, по Хомякову, значит «только собрание членов Церкви, живущих в такой-то стране», и не предполагает, что одна община может дать учению догматическое толкование.","sources":[{"title":"Хомяков. Церковь одна, гл. 4 «Едина, Святая, Соборная и Апостольская»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"такое название значит только собрание членов Церкви, живущих в такой-то стране"}]},{"id":"r43c464d48b","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, предшествует и Писанию, и Преданию?","options":["дело","соборное определение","церковная иерархия","богослужебный обряд"],"explanation":"Хомяков спрашивает: «Не предшествует ли дело Писанию и Преданию?» — угодны Богу были дела Ноя и Авраама ещё до всякого Писания. Соборы, иерархия и обряд в этом ряду не названы.","sources":[{"title":"Хомяков. Церковь одна, гл. 5 «Писание и Предание»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Не предшествует ли дело Писанию и Преданию?"}]},{"id":"ra916fd79d7","s":2,"topic":"Хомяков. «Церковь одна»","text":"Кто, по Хомякову, хранит в Церкви Предание и пишет Писание?","options":["Дух Божий в совокупности церковной","епископы, преемники апостолов","Вселенские Соборы и их отцы","монашество и учёные богословы"],"explanation":"«Не лица и не множество лиц в Церкви хранят предание и пишут, но Дух Божий, живущий в совокупности церковной». Поэтому, по Хомякову, нельзя искать основу Преданию в Писании и наоборот.","sources":[{"title":"Хомяков. Церковь одна, гл. 5 «Писание и Предание»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Не лица и не множество лиц в Церкви хранят предание и пишут, но Дух Божий"}]},{"id":"r7c17b01f10","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, показывает всякий, кто ищет доказательств церковной истины?","options":["своё сомнение, исключающее его из Церкви","свою ревность о чистоте веры","свою учёность и усердие к истине","свою верность святоотеческому Преданию"],"explanation":"Ищущий доказательств, по Хомякову, «тем самым или показывает своё сомнение и исключает себя из Церкви», или надеется дойти до истины силой разума, но силы разума до истины Божией не доходят.","sources":[{"title":"Хомяков. Церковь одна, гл. 5 «Писание и Предание»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Всякий, ищущий доказательств церковной истины, тем самым или показывает свое сомнение"}]},{"id":"r374c5c5152","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, представляет собой каждое действие Церкви, направляемое Святым Духом?","options":["совокупность веры, надежды и любви","проявление одной лишь веры","исполнение одной заповеди любви","плод покаяния и смирения"],"explanation":"Каждое действие Церкви, по Хомякову, представляет совокупность всех даров Духа: и в Писании, и в деле, и в Предании проявляются вместе вера, надежда и любовь.","sources":[{"title":"Хомяков. Церковь одна, гл. 6 «Исповедь, молитва и дела»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"представляет совокупность всех его даров - веры, надежды и любви"}]},{"id":"r03da883d2c","s":2,"topic":"Хомяков. «Церковь одна»","text":"Чем, по Хомякову, являются исповедание, молитва и дело сами по себе?","options":["ничем, кроме внешнего проявления духа","средствами заслужить спасение","обязанностями каждого члена Церкви","ступенями духовного восхождения"],"explanation":"Хомяков пишет, что исповедание, молитва и дело «суть ничто сами по себе», но лишь внешнее проявление внутреннего духа: угоден Богу тот, кто творит и молится по живущему в нём духу Христову.","sources":[{"title":"Хомяков. Церковь одна, гл. 6 «Исповедь, молитва и дела»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"исповедание, и молитва, и дело суть ничто сами по себе"}]},{"id":"r11a10fedb0","s":2,"topic":"Хомяков. «Церковь одна»","text":"Почему, по Хомякову, в Символе веры о будущем сказано «чаем», а не просто «веруем»?","options":["чтобы исповедать и надежду Церкви","так точнее переведён греческий текст","чтобы отличить догмат от мнения","потому что будущее недоступно вере"],"explanation":"Хомяков объясняет: чтобы было ведомо, что надежда Церкви неотделима от её учения, в Символе исповедуется и надежда — «чаем» (ожидаем).","sources":[{"title":"Хомяков. Церковь одна, гл. 7 «Символ веры»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"исповедуется также и надежда ее: ибо говорится чаем"}]},{"id":"rfe4071d2d5","s":2,"topic":"Хомяков. «Церковь одна»","text":"Как, по Хомякову, Церковь обращается с Символом веры как с полным исповеданием?","options":["не позволяет ничего исключать и прибавлять","позволяет поместным Церквам дополнять его","допускает уточнения на новых Соборах","считает его кратким наставлением оглашенным"],"explanation":"Символ веры, по Хомякову, — «полное и совершенное исповедание Церкви», из которого она не позволяет ничего исключить и ничего к нему прибавить.","sources":[{"title":"Хомяков. Церковь одна, гл. 7 «Символ веры»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"из которого она не позволяет ничего исключить и ничего к нему прибавить"}]},{"id":"r9ab0a0184f","s":2,"topic":"Хомяков. «Церковь одна»","text":"Чему, по Хомякову, доступно знание о существовании Церкви?","options":["только вере, а не разуму","только разуму, а не вере","и вере, и исторической науке","только святым подвижникам"],"explanation":"Исповедуя веру в Троицу, Церковь исповедует веру и в саму себя: знание о её существовании есть дар благодати, «доступной только вере, а не разуму».","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"даруемой свыше и доступной только вере, а не разуму"}]},{"id":"r210e1cfdff","s":2,"topic":"Хомяков. «Церковь одна»","text":"Чем, по Хомякову, таинство является для неверующего?","options":["только обрядом","только символом","соблазном","чудом"],"explanation":"Видимая Церковь видима только верующему: «для неверующего таинство есть только обряд, и Церковь только общество».","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"для неверующего таинство есть только обряд, и Церковь только общество"}]},{"id":"re413f51c5a","s":2,"topic":"Хомяков. «Церковь одна»","text":"Как, по Хомякову, Церковь относится к тем, кто не стал её членом через Крещение?","options":["не судит их, ибо судит лишь саму себя","считает их всех без исключения погибшими","признаёт их своими членами по желанию","предаёт их анафеме как еретиков"],"explanation":"Хомяков пишет, что Церковь не судит не принявших Крещения, «ибо она знает и судит только саму себя»; многие спаслись, не прияв таинства крещения водою.","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Церковь не судит тех, которые не сделались причастными ей через крещение"}]},{"id":"rd19e55b3d6","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что Хомяков говорит о числе таинств?","options":["исповедуются семь, но есть и много других","их ровно семь, и иных быть не может","истинных таинств лишь два, остальные — обряды","их число Церковью вовсе не определено"],"explanation":"Хомяков вместе с Церковью исповедует семь таинств, но добавляет: «Много есть и других таинств», ибо всякое дело, совершаемое в вере, любви и надежде, призывает невидимую благодать.","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Много есть и других таинств; ибо всякое дело, совершаемое в вере, любви и надежде"}]},{"id":"ra06a447e49","s":2,"topic":"Хомяков. «Церковь одна»","text":"Как, по Хомякову, Церковь относится к слову «пресуществление»?","options":["не отвергает его, но без вещественного смысла","отвергает его как латинское новшество","принимает его в том смысле, что у схоластов","заменяет его словом «символ» или «образ»"],"explanation":"Церковь, по Хомякову, учит о преложении хлеба и вина в Тело и Кровь Христову и не отвергает слова «пресуществление», но не приписывает ему вещественного смысла, данного учителями отпавших церквей.","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Не отвергает она и слова пресуществление, но не приписывает ему того вещественного смысла"}]},{"id":"r1689a23735","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, может совершить всякий христианин и без рукоположения?","options":["через крещение открыть человеку дверь Церкви","в случае нужды совершить Евхаристию","освятить миро для таинства Миропомазания","разрешить грехи кающегося на исповеди"],"explanation":"Рукоположение, по Хомякову, содержит полноту благодати таинств, но не так, будто ничто не совершается иначе: «всякий христианин может через крещение отворить» младенцу, еврею или язычнику дверь Церкви.","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"всякий христианин может через крещение отворить младенцу, или еврею, или язычнику дверь Церкви"}]},{"id":"r83c128b3c4","s":2,"topic":"Хомяков. «Церковь одна»","text":"Почему, по Хомякову, человек не может сам разрешать свои грехи?","options":["он властен лишь осуждать себя, а не оправдывать","он не способен помнить все свои грехи","грех ранит ближних, а не одного его самого","так установили правила святых апостолов"],"explanation":"В таинстве Покаяния, по Хомякову, нужна Церковь, ибо «мы властны только осуждать себя, а не оправдывать»; силу оправдания имеет одна Церковь, в которой живёт полнота духа Христова.","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"ибо мы властны только осуждать себя, а не оправдывать"}]},{"id":"rc605c1338d","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, выражается в таинстве Елеосвящения?","options":["суд Божий над земным составом человека","прощение забытых на исповеди грехов","благословение на монашеский подвиг","освящение дома от злых сил"],"explanation":"В Елеосвящении, по Хомякову, благословляется весь пройденный человеком путь и выражается «самый суд божественный над земным составом человека»: Бог исцеляет его или дозволяет смерти разрушить тленное тело.","sources":[{"title":"Хомяков. Церковь одна, гл. 8 «Церковь и её Таинства»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"в елеосвящении выражается самый суд божественный над земным составом человека"}]},{"id":"r49378c59c2","s":2,"topic":"Хомяков. «Церковь одна»","text":"Чем, по Хомякову, внешнее единство Церкви отличается от внутреннего?","options":["первое — общение в таинствах, второе — единство духа","первое — единство иерархии, второе — единство догматов","первое — общий обряд, второе — общий Символ веры","первое — подчинение собору, второе — личная вера"],"explanation":"Хомяков определяет: «Внешнее единство есть единство, проявленное в общении таинств, внутреннее же единство есть единство духа». Многие мученики спаслись без таинств, но никто — без внутренней святости Церкви.","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Внешнее единство есть единство, проявленное в общении таинств, внутреннее же единство есть единство духа"}]},{"id":"r992c0349a3","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, сделали из «мёртвой веры» те, кто принял её за истинную?","options":["восьмое таинство","новый догмат","церковный закон","школьную науку"],"explanation":"Принявшие внешнее знание за истинную веру, по Хомякову, «из этой мёртвой веры, сами того не зная, сделали восьмое таинство». Церковь же имеет веру живую, ибо имеет и святость.","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"из этой мертвой веры, сами того не зная, сделали восьмое таинство"}]},{"id":"r920ad4fe2d","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, спасает человека?","options":["предмет веры","сама вера","любовь к ближнему","добрые дела"],"explanation":"Хомяков пишет, что спасает не вера, не надежда и не любовь сами по себе (спасёт ли вера в разум или любовь к плоти?), «но спасёт предмет веры»: веруешь во Христа — Христом спасёшься.","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"любовь к плоти?), но спасет предмет веры"}]},{"id":"r0a48bf1360","s":2,"topic":"Хомяков. «Церковь одна»","text":"Как Хомяков заканчивает мысль «когда падает кто из нас, он падает один, но…»?","options":["никто один не спасается","всякий восстаёт с помощью братьев","вся Церковь скорбит о падшем","падение его видит один Бог"],"explanation":"Полностью: «Мы знаем, когда падает кто из нас, он падает один, но никто один не спасается». Спасающийся спасается в Церкви как её член, в единстве со всеми другими членами.","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"он падает один, но никто один не спасается"}]},{"id":"rc7a3b63812","s":2,"topic":"Хомяков. «Церковь одна»","text":"За кого, по Хомякову, каждый член Церкви должен молиться?","options":["за живых, усопших и ещё не рождённых","за живых и усопших, но не за не рождённых","лишь за живых крещёных собратьев","за себя, своих ближних и врагов"],"explanation":"Каждый, по Хомякову, требует молитвы от всех и сам всем должен молитвами — «живым и усопшим и даже ещё не рождённым», ибо мы просим и за поколения, которые Бог ещё вызовет к жизни.","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"живым и усопшим и даже еще не рожденным"}]},{"id":"r17d39d70c2","s":2,"topic":"Хомяков. «Церковь одна»","text":"Когда, по Хомякову, человек ставит себе кумира?","options":["когда думает, что Бог похож на его воображение","когда пишет икону для памяти о невидимом Боге","когда молится перед написанной иконой святого","когда почитает мощи, кресты и святые места"],"explanation":"Икона, написанная для напоминания о невидимом Боге, по Хомякову, не кумир; кумира ставит себе тот, кто воображает Бога и думает, что Он похож на это воображение. В этом смысл ветхозаветного запрета.","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"думаешь, что Он похож на твое воображение, ты ставишь себе кумир"}]},{"id":"r3ef526e184","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, нужно понимать, чтобы понимать Церковь?","options":["Литургию","Символ веры","Священное Писание","соборные каноны"],"explanation":"Выше всех обрядов Церковь признаёт Литургию, в которой выражается вся полнота её учения: «Только тот понимает Церковь, кто понимает Литургию».","sources":[{"title":"Хомяков. Церковь одна, гл. 9 «Вера и жизнь в единстве с Церковью»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Только тот понимает Церковь, кто понимает Литургию"}]},{"id":"rb263fec236","s":2,"topic":"Хомяков. «Церковь одна»","text":"Почему, по Хомякову, будущая жизнь принадлежит не только духу, но и воскрешённому телу?","options":["совершенно бестелесный дух — один Бог","тело — храм Святого Духа","так учит Писание о воскрешении Лазаря","душа без тела не способна любить"],"explanation":"Церковь, по Хомякову, отвергает гордость проповедующих бестелесность человека в будущей жизни, «ибо только Бог есть совершенно бестелесный дух».","sources":[{"title":"Хомяков. Церковь одна, гл. 10 «Спасение»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"ибо только Бог есть совершенно бестелесный дух"}]},{"id":"r067ada3d16","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, станет с верой и надеждой на общем суде?","options":["не погибнут, но имя сохранит одна Любовь","упразднятся, уступив место одной Любви","сольются с Любовью в единое знание Бога","останутся неизменными, как и сейчас"],"explanation":"Над всем, по Хомякову, будет Любовь; веру и надежду нельзя считать погибшими, ибо они нераздельны с Любовью, «но одна Любовь сохраняет своё имя».","sources":[{"title":"Хомяков. Церковь одна, гл. 10 «Спасение»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"но одна Любовь сохраняет свое имя"}]},{"id":"r83749cb0c4","s":2,"topic":"Хомяков. «Церковь одна»","text":"Что, по Хомякову, станет с именем «Православная», когда исчезнут ложные учения?","options":["оно станет излишним","оно станет общим для всех христиан","его заменит имя «Вселенская»","оно сохранится навеки"],"explanation":"Названия «Православная», «Восточная», «Греко-Российская», по Хомякову, временны: когда исчезнут ложные учения, «излишним станет и имя православия», ибо ложного христианства не будет.","sources":[{"title":"Хомяков. Церковь одна, гл. 11 «Единство Православия»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"Когда исчезнут ложные учения, излишнем станет и имя православия"}]},{"id":"r758dc2102b","s":2,"topic":"Хомяков. «Церковь одна»","text":"Какие общины, по Хомякову, могут признавать себя вполне христианскими?","options":["сохраняющие единство с восточными патриархатами","признающие Символ веры без всяких добавлений","имеющие апостольское преемство иерархии","принимающие все семь церковных таинств"],"explanation":"После отпадения расколов и римского патриаршества, по Хомякову, «только те общины могут признавать себя вполне христианскими, которые сохраняют единство с восточными патриаршествами или вступают в это единство».","sources":[{"title":"Хомяков. Церковь одна, гл. 11 «Единство Православия»","url":"http://www.vehi.net/khomyakov/cerkov.html","quote":"только те общины могут признавать себя вполне христианскими, которые сохраняют единство с восточными патриаршествами"}]},{"id":"r4466dca123","s":2,"topic":"Хомяков. «О старом и новом»","text":"Какие два начала, по мнению хвалителей старины, с которого Хомяков начинает статью, хранили землю русскую?","options":["власть, дружная с народом, и свобода Церкви","самодержавие царя и крепостной порядок","вечевое собрание и княжеская дружина","сельская община и неизменный обряд"],"explanation":"Статья открывается мнением, будто в старые годы всё было лучше: землю хранили «власть правительства, дружного с народом, и свобода церкви». Затем Хомяков излагает противоположный взгляд и сопоставляет оба.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"власть правительства, дружного с народом, и свобода церкви, чистой и просвещенной"}]},{"id":"rd2b958dda1","s":2,"topic":"Хомяков. «О старом и новом»","text":"К какому выводу Хомяков приходит, сопоставив два противоположных взгляда на старую Русь?","options":["оба равно подтверждаются и опровергаются","факты подтверждают тех, кто хвалит старину","факты подтверждают тех, кто её порицает","для суждения пока недостаточно памятников"],"explanation":"Хомяков пишет, что два противоположных воззрения «одинаково оправдываются и одинаково опровергаются фактами неоспоримыми», и никакая система их не объясняет.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Два воззрения, совершенно противоположные одинаково оправдываются и одинаково опровергаются фактами неоспоримыми"}]},{"id":"rb2a00ff5f4","s":2,"topic":"Хомяков. «О старом и новом»","text":"Почему, по Хомякову, нельзя оставить нерешённым вопрос о старой Руси?","options":["от понимания прошлого зависит путь будущего","от него зависит честь народа перед Европой","его настоятельно требует историческая наука","его поставило перед обществом правительство"],"explanation":"Настоящее, по Хомякову, — переходный момент, и «направление будущего почти вполне зависит от понятия нашего о прошедшем».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"направление будущего почти вполне зависит от понятия нашего о прошедшем"}]},{"id":"rdd5920a6e2","s":2,"topic":"Хомяков. «О старом и новом»","text":"Каким образом Хомяков описывает действия тех, кто уверен, что в прошлом России не было ничего доброго?","options":["прививать чужие плоды к домашнему дичку","строить новый дом на чужом фундаменте","пересаживать чужое дерево вместе с корнями","лечить больного чужими лекарствами"],"explanation":"Если в старине не было ничего плодотворного, пишет Хомяков, можно смело «прививать чужие плоды к домашнему дичку» и перепахивать землю, не таящую семян.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"прививать чужие плоды к домашнему дичку, перепахивать землю"}]},{"id":"rdc731047e8","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, нужно сделать со старой Русью, в отличие от современной России, которую «мы видим»?","options":["угадать","забыть","воскресить","осудить"],"explanation":"«Современную Россию мы видим… но старую Русь надобно — угадать»: памятники противоречат друг другу, и смысл старины приходится восстанавливать.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"но старую Русь надобно -- угадать"}]},{"id":"rcde874047e","s":2,"topic":"Хомяков. «О старом и новом»","text":"Какое постоянное несогласие, по Хомякову, обнаруживает сличение памятников русской старины?","options":["между законом и жизнью","между Церковью и государством","между князьями и народом","между Севером и Югом Руси"],"explanation":"Сличение памятников, по Хомякову, приводит к выводу: прежде, как и теперь, было «постоянное несогласие между законом и жизнию», между писаными учреждениями и живыми нравами.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"было постоянное несогласие между законом и жизнию, между учреждениями писаными и живыми нравами"}]},{"id":"rb9a1d6e967","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что Хомяков называет среди «прекрасных начал», освящённых законом в России XIX века?","options":["отмену смертной казни","отмену крепостного права","введение суда присяжных","созыв Земского собора"],"explanation":"Сравнивая XIX век с XVII, Хомяков называет отмену смертной казни, человеколюбие в уголовном праве и возможность низшим сословиям подниматься по службе. Крепостное право отменили и суд присяжных ввели позже, чем написана статья (1839).","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"такова отмена смертной казни, человеколюбие в праве уголовном"}]},{"id":"r6ece2192c7","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что Хомяков относит к недостаткам новой России «в жизни и ходе просвещения»?","options":["излишний космополитизм и протестантство мыслей","забвение древних языков в народных училищах","упадок монастырей и иконописи","засилье схоластики в духовных академиях"],"explanation":"В ходе просвещения новой России Хомяков видит «излишний космополитизм, некоторое протестантство мыслей и отчуждение от положительных начал веры».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"излишний космополитизм, некоторое протестантство мыслей и отчуждение от положительных начал веры"}]},{"id":"re1885a4a94","s":2,"topic":"Хомяков. «О старом и новом»","text":"Как, по Хомякову, погибли прекрасные стихии старой Руси?","options":["сначала убиты народом, потом схоронены государями","сначала отменены указами, потом забыты народом","были разрушены монгольским нашествием","были вытеснены иноземными обычаями"],"explanation":"Хомяков показывает, что лучшие стихии старины уничтожены обрядами прежде, чем их коснулись законы: «Они прежде были убиты народом, потом уже схоронены государями».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Они прежде были убиты народом, потом уже схоронены государями"}]},{"id":"raa9b75339b","s":2,"topic":"Хомяков. «О старом и новом»","text":"Чьи слова о том, что устарелость закона — самая справедливая и горькая его критика, приводит Хомяков?","options":["Камбасереса","Монтескьё","Бентама","Савиньи"],"explanation":"Хомяков цитирует по-французски Камбасереса, одного из составителей Кодекса Наполеона, и добавляет: «Это правда, но правда неполная».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Камбасерес сказал: La desuetude est la plus juste"}]},{"id":"r3ab34cf88e","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, произвели «лучшие инстинкты души русской», облагороженной христианством?","options":["освобождение Греции и греческой Церкви","присоединение Сибири к России","основание Академии наук","первое университетское образование"],"explanation":"Среди плодов лучших русских инстинктов Хомяков называет отмену смертной казни, освобождение Греции и греческой Церкви «в недрах самой Турции» и мирное направление политики.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"освобождение Греции и церкви греческой в недрах самой Турции"}]},{"id":"raf2eae3e3c","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, было бы стыдно России по отношению к Западу?","options":["не перегнать его","подражать ему","не учиться у него","враждовать с ним"],"explanation":"Хомяков пишет: «Нам стыдно бы было не перегнать Запада», ведь прежние русские начала могут развиваться собственной неумирающей силой.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Нам стыдно бы было не перегнать Запада"}]},{"id":"r00ad5d626d","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, видят англичане, французы и немцы, оглядываясь на своё прошлое?","options":["чем дальше, тем хуже и безнравственнее общество","славное рыцарское и христианское прошлое","чем дальше, тем свободнее и счастливее народ","единство Церкви, утраченное ими позже"],"explanation":"По Хомякову, у англичан, французов и немцев нет ничего хорошего за спиной: чем дальше они оглядываются, «тем хуже и безнравственнее представляется им общество».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Чем дальше они оглядываются, тем хуже и безнравственнее представляется им общество"}]},{"id":"r95bea8f5e5","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, составляло внутреннюю сторону государства в первые века русской истории?","options":["областные веча","княжеская дружина","варяжские князья","монастыри и епископы"],"explanation":"Хомяков пишет: «Правительство из варягов представляет внешнюю сторону; областные веча — внутреннюю сторону государства». Суд, обычаи и внутренние дела решало народное совещание.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Правительство из варягов представляет внешнюю сторону; областные веча -- внутреннюю сторону государства"}]},{"id":"r5fcde253e6","s":2,"topic":"Хомяков. «О старом и новом»","text":"Между какими близкими городами, по Хомякову, не было совершенного единства обычаев?","options":["Новгородом и Псковом","Киевом и Черниговом","Владимиром и Суздалем","Ростовом и Ярославлем"],"explanation":"Совершенного единства обычаев, по Хомякову, не было даже между Новгородом и Псковом, «столь близкими и по месту, и по выгодам». Из этого он делает вывод о слабости внутренней связи областей.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"ниже между Новгородом и Псковом, столь близкими и по месту, и по выгодам"}]},{"id":"r5524b19408","s":2,"topic":"Хомяков. «О старом и новом»","text":"Как, по Хомякову, народ домонгольской Руси относился к единству государства?","options":["не просил и не желал его","требовал его на вечах","видел в нём волю Божию","ждал его от Церкви"],"explanation":"Федерация племён под охраной дома Рюрикова, по Хомякову, не была единым целым: области жили отдельно, Новгород и Киев не защищали друг друга, а «народ не просил единства, не желал его».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Народ не просил единства, не желал его"}]},{"id":"rae40b31d72","s":2,"topic":"Хомяков. «О старом и новом»","text":"Как Хомяков оценивает монгольское нашествие?","options":["как правосудную кару, нужную для перерождения","как случайное бедствие без всякого смысла","как наказание за принятие христианства","как благо, сблизившее Русь с Азией"],"explanation":"Церковь молчала, народ был равнодушен, князья враждовали: «Кара была правосудна, перерождение было необходимо», — пишет Хомяков.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Кара была правосудна, перерождение было необходимо"}]},{"id":"rd4dd1c52f1","s":2,"topic":"Хомяков. «О старом и новом»","text":"В чём, по Хомякову, было достоинство Москвы, позволившее ей возвыситься?","options":["она была новым городом без прошлого","она была древнейшим городом Руси","она лежала на важных торговых путях","она получила ярлык от ханов первой"],"explanation":"Хомяков пишет: «Москва была город новый, не имеющий прошедшего», смешение разных славянских семей, «и это её достоинство».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Москва была город новый, не имеющий прошедшего"}]},{"id":"r99069094f4","s":2,"topic":"Хомяков. «О старом и новом»","text":"В чём, по Хомякову, заключалась «тайна силы» Москвы?","options":["в союзе государственной внешности и внутренности","в покровительстве ханов Золотой Орды","в богатстве и торговле московского купечества","в святости московских митрополитов"],"explanation":"Москва, по Хомякову, была и созданием князей, и «дочерью народа», поэтому совместила в тесном союзе государственную внешность и внутренность, «и вот тайна её силы».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"она совместила в тесном союзе государственную внешность и внутренность, и вот тайна ее силы"}]},{"id":"r2be304e43d","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что Хомяков относит к последствиям торжества Москвы?","options":["угнетение общинного быта и областных прав","расцвет вечевой свободы северных городов","ослабление власти государя","распад страны на новые уделы"],"explanation":"Последствия торжества Москвы, по Хомякову, — распространение России и рост вещественных сил, но также «уничтожение областных прав, угнетение быта общинного» и сосредоточение мысли государства в лице государя.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"уничтожение областных прав, угнетение быта общинного"}]},{"id":"rffdc3e7b0a","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, «выдумывает» Иоанн Четвёртый?","options":["опричнину","местничество","Судебник","патриаршество"],"explanation":"Хомяков перечисляет: Иоанн Третий утверждает обряды местничества, Иоанн Четвёртый «выдумывает опричнину», Феодор учреждает в Москве патриаршество.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"общею нумерациею боярских родов; Иоанн Четвертый выдумывает опричнину"}]},{"id":"rea948deb72","s":2,"topic":"Хомяков. «О старом и новом»","text":"Где, по Хомякову, патриарший престол мог быть свободным, а где — уже нет?","options":["в Царьграде — мог, в Москве — нет","в Москве — мог, в Царьграде — нет","в Киеве — мог, во Владимире — нет","в Новгороде — мог, в Москве — нет"],"explanation":"Перенесение патриаршего престола внутрь государства, по Хомякову, уничтожило независимость Церкви: престол «мог быть свободным в Царьграде, но не мог уже быть свободным в Москве».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"который мог быть свободным в Царьграде, но не мог уже быть свободным в Москве"}]},{"id":"r627f5bdda4","s":2,"topic":"Хомяков. «О старом и новом»","text":"Почему, по Хомякову, византийское духовенство не могло развить на Руси начала гражданской жизни?","options":["оно не знало их в собственном отечестве","оно было подчинено русским князьям","оно не владело славянским языком","оно презирало всякие мирские дела"],"explanation":"Хомяков пишет, что духовенство византийское не могло развить в России начала жизни гражданской, «о которой не знало оно в своём отечестве».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Не могло духовенство византийское развить в России начала жизни гражданской"}]},{"id":"r7ca7d5ab5d","s":2,"topic":"Хомяков. «О старом и новом»","text":"Какая честь, по Хомякову, остаётся за Петром Великим, несмотря на его ошибки?","options":["пробуждение России к силе и сознанию силы","освобождение Церкви от опеки государства","примирение всех сословий между собой","возвращение к забытым началам старины"],"explanation":"«Много ошибок помрачают славу преобразователя России, но ему остаётся честь пробуждения её к силе и к сознанию силы», — пишет Хомяков.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"ему остается честь пробуждения ее к силе и к сознанию силы"}]},{"id":"r2388cbc14d","s":2,"topic":"Хомяков. «О старом и новом»","text":"Кому, по Хомякову, принадлежат силы духовные?","options":["народу и Церкви","правительству","дворянству и учёным","одному государю"],"explanation":"Хомяков напоминает, что «силы духовные принадлежат народу и церкви, а не правительству»; правительство может лишь пробуждать или убивать их деятельность.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"силы духовные принадлежат народу и церкви, а не правительству"}]},{"id":"raf82d2dae1","s":2,"topic":"Хомяков. «О старом и новом»","text":"О чём, по Хомякову, забыл Пётр, поработив государству и свою личность, и личность подданных?","options":["что сила лишь там, где любовь","что Церковь выше государства","что народ хранит предание старины","что закон должен уважать обычай"],"explanation":"Хомяков с грустью пишет, что Пётр, так живо понявший смысл государства, «не вспомнил… что там только сила, где любовь».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"не вспомнил в то же время, что там только сила, где любовь"}]},{"id":"r441a041c08","s":2,"topic":"Хомяков. «О старом и новом»","text":"Что, по Хомякову, заключает в себе всякая федерация?","options":["безмолвный протест против общего начала","залог будущего государственного единства","добровольный договор свободных общин","высшую форму народной свободы"],"explanation":"Хомяков пишет: «Всякая федерация заключает в себе безмолвный протест против одного общего начала», а случайная федерация доказывает отчуждение людей друг от друга.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Всякая федерация заключает в себе безмолвный протест против одного общего начала"}]},{"id":"rdc3d097e8f","s":2,"topic":"Хомяков. «О старом и новом»","text":"Какая выгода, по Хомякову, есть у России перед Западом в её первоначальной истории?","options":["на ней не лежит пятно завоевания","она древнее западной истории","она подробно записана в летописях","в ней не было княжеских усобиц"],"explanation":"«На нашей первоначальной истории не лежит пятно завоевания»: кровь и вражда, по Хомякову, не служили основанием русскому государству.","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"На нашей первоначальной истории не лежит пятно завоевания"}]},{"id":"r0cf17753dc","s":2,"topic":"Хомяков. «О старом и новом»","text":"Каким, по Хомякову, оказался мир, созданный западной Церковью, обратившейся к рационализму?","options":["прекрасным, соблазнительным, но обречённым на гибель","суровым, аскетичным, но прочным и долговечным","бедным и тёмным, но чистым в своей вере","свободным, разумным и навсегда торжествующим"],"explanation":"Западная Церковь, по Хомякову, утратила чистоту, но развила силы человечества и «создала мир прекрасный, соблазнительный, но обречённый на гибель, мир католицизма и реформации».","sources":[{"title":"Хомяков. О старом и новом","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"создала мир прекрасный, соблазнительный, но обреченный на гибель"}]},{"id":"r77c4e9c57c","s":2,"topic":"Хомяков. «О старом и новом»","text":"Для чего Хомяков в 1839 году написал статью «О старом и новом»?","options":["для вечеров в доме И. В. Киреевского","для журнала «Москвитянин»","для журнала «Телескоп»","для речи в Московском университете"],"explanation":"Статья была написана для вечеров в московском доме Ивана Киреевского и не предназначалась для печати. Её считают одним из первых текстов славянофильства.","sources":[{"title":"Хомяков. О старом и новом, примечание","url":"http://az.lib.ru/h/homjakow_a_s/text_1839_o_starom_i_novom.shtml","quote":"Статья была написана А.С. Хомяковым в 1839 г. для вечеров"}]},{"id":"rfb3c7020f9","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"В форме письма к кому написана статья Киреевского «О характере просвещения Европы и о его отношении к просвещению России»?","options":["к графу Е. Е. Комаровскому","к другу А. С. Хомякову","к философу П. Я. Чаадаеву","к издателю М. П. Погодину"],"explanation":"Статья 1852 года написана как письмо к графу Евграфу Комаровскому и начинается с воспоминания о беседе с ним о характере европейского и русского просвещения.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России, вступление","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Письмо к гр. Е. Е. Комаровскому"}]},{"id":"r59d6333371","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Где, по рассказу Киреевского, Пётр, «осушая стакан», говорил о переходе наук из Греции в Италию и далее по Европе?","options":["в Риге, на новоспущенном корабле","в Амстердаме, на верфи Ост-Индской компании","в Петербурге, на заседании Сената","под Полтавой, на пиру после победы"],"explanation":"Киреевский приводит речь Петра, сказанную в Риге на новоспущенном корабле: науки из Греции перешли в Италию и по всей Европе, и теперь очередь России.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России, вступление","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"говорил Петр в 1714 году, в Риге, осушая стакан на новоспущенном корабле"}]},{"id":"r6270462f0b","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Дальше какой страны, по словам Петра в передаче Киреевского, невежество предков не пустило науки?","options":["Польши","Литвы","Швеции","Венгрии"],"explanation":"В приведённой речи Пётр говорит, что невежество предков помешало наукам проникнуть далее Польши, хотя и поляки прежде находились в таком же мраке.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России, вступление","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"помешало им проникнуть далее Польши, хотя и Поляки находились прежде"}]},{"id":"rcc68ce3a8a","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Когда, по Киреевскому, начался круг развития европейского просвещения, завершённый в XIX веке?","options":["в IX веке","в V веке","в XII веке","в XV веке"],"explanation":"Киреевский пишет: «Европа высказалась вполне. В девятнадцатом веке она… докончила круг своего развития, начавшийся в девятом».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"В девятнадцатом веке она, можно сказать, докончила круг своего развития, начавшийся в девятом"}]},{"id":"ra44a547567","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Какое чувство, по Киреевскому, обнаружилось в западном человеке, когда европейское просвещение достигло полноты?","options":["недовольство и безнадёжность","гордость и самоуверенность","спокойная удовлетворённость","жажда новых завоеваний"],"explanation":"Достигнув полноты развития, европейское просвещение, по Киреевскому, принесло западному человеку чувство недовольства и безнадёжности, хотя оно обнаружилось не сразу.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"чувство недовольства и безнадежности не вдруг обнаружилось в Западном человеке"}]},{"id":"rb8cd2070ff","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"К какому «избегу», по Киреевскому, обратились мыслящие люди Европы, чтобы не остаться без убеждений?","options":["каждый изобретал свои начала истины","все подчинились мнению большинства","все ушли в изучение одной природы","все обратились к восточным учениям"],"explanation":"По Киреевскому, каждый «начал в своей голове изобретать для всего мира новые общие начала жизни и истины», отыскивая их в собственных мечтаниях.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"каждый начал в своей голове изобретать для всего мира новые общие начала жизни и истины"}]},{"id":"r4133da1f83","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Через что, по Киреевскому, христианство проникало в Западную Европу?","options":["единственно через Церковь Римскую","через греческих странствующих миссионеров","через ирландских и шотландских монахов","через Византию и славянских учителей"],"explanation":"Христианство было душою умственной жизни и на Западе, и в России, «но в Западную Европу проникало оно единственно через Церковь Римскую».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Но в Западную Европу проникало оно единственно через Церковь Римскую"}]},{"id":"rd087081e1b","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Как, по Киреевскому, христианство «зажигалось» в России в отличие от Запада?","options":["на светильниках всей Церкви Православной","на светильнике одного Константинополя","на светильниках киевских монастырей","на светильнике княжеской власти"],"explanation":"В итоговом сопоставлении Киреевский пишет, что христианство проникало на Запад через одну Римскую Церковь, а в России «зажигалось на светильниках всей Церкви Православной».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"в России оно зажигалось на светильниках всей Церкви Православной"}]},{"id":"ra09fc757d8","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Какие три элемента западного просвещения, по Киреевскому, были совершенно чужды древней России?","options":["Римская Церковь, римская образованность, завоевание","греческая вера, славянская грамота, вечевой строй","монашество, иконопись и церковное пение","Римская Церковь, рыцарство и Реформация"],"explanation":"Три элемента Запада — Римская Церковь, древнеримская образованность и государственность, «возникшая из насилий завоевания», — по Киреевскому, были совершенно чужды древней России.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Эти три элемента Запада: Римская Церковь, древне – Римская образованность и возникшая из насилий завоевания государственность"}]},{"id":"r6883910cc4","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, Западная Церковь ещё в IX веке положила внутри себя?","options":["неминуемое семя реформации","учение о непогрешимости папы","основание монашеских орденов","закон о безбрачии духовенства"],"explanation":"Подчинив веру логическим выводам рассудка, Западная Церковь, по Киреевскому, ещё в IX веке «положила внутри себя неминуемое семя реформации», которая поставила её перед судом того же разума.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Западная Церковь еще в 9-м веке положила внутри себя неминуемое семя реформации"}]},{"id":"r87ae6efc97","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"К чему, по Киреевскому, привело то, что Западная Церковь поставила над собой главу, соединившую власть духовную и светскую?","options":["к раздвоению её деятельности и интересов","к укреплению её внутреннего единства","к отделению Церкви от государства","к расцвету созерцательного монашества"],"explanation":"Устроив себе наружное единство под одной главой, Западная Церковь, по Киреевскому, «произвела раздвоение в своей духовной деятельности» и в своих интересах.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Церковь Западная произвела раздвоение в своей духовной деятельности"}]},{"id":"rbfdaf9162b","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Каким выражением Киреевский обозначает папу, которому подчинились светские государи Запада?","options":["тривенчанный правитель Церкви","первосвященник всего Запада","наместник апостола Петра","вселенский епископ Рима"],"explanation":"Светские правители, по Киреевскому, подчинились «главенству тривенчанного правителя Церкви» (намёк на папскую тиару с тремя венцами) и сомкнули феодальное устройство Священной Римской империи.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"подчинившиеся главенству тривенчанного правителя Церкви"}]},{"id":"r30071969a3","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Чем, по Киреевскому, был каждый благородный рыцарь внутри своего замка?","options":["отдельным государством","вассалом своего короля","слугой Римской Церкви","судьёй сельской общины"],"explanation":"Киреевский пишет: «Каждый благородный рыцарь, внутри своего замка, был отдельное государство», поэтому отношения между ними строились как между отдельными державами.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Каждый благородный рыцарь, внутри своего замка, был отдельное государство"}]},{"id":"re7fa2d866f","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, благодаря обособленности рыцарских «государств» легко привилось к европейским народам?","options":["римское право","греческая философия","германский обычай","каноническое право"],"explanation":"Обособленностью рыцарских замков Киреевский объясняет, почему чужое для европейских народов римское право «так легко могло привиться к ним».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"чужое для Европейских народов, Римское право так легко могло привиться к ним"}]},{"id":"r3408a6be37","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Почему, по Киреевскому, европейские государства должны были развиваться переворотами?","options":["потому что начались насилием","потому что их раздирали войны за веру","потому что в них правили чужие династии","потому что их народы любили свободу"],"explanation":"Киреевский пишет: «Начавшись насилием, государства Европейские должны были развиваться переворотами», ибо развитие государства есть раскрытие его внутренних начал.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Но, начавшись насилием, государства Европейские должны были развиваться переворотами"}]},{"id":"r13ea9b7252","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Кто, по Киреевскому, был «душою схоластики»?","options":["Аристотель","Платон","Августин","Боэций"],"explanation":"Аристотель, «никогда не понятый вполне, но до бесконечности изучаемый в частностях», был, по Киреевскому, душою схоластики.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Аристотель, никогда не понятый вполне, но до бесконечности изучаемый в частностях"}]},{"id":"rc7f03fa380","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Как Киреевский определяет схоластику?","options":["стремление к наукообразному богословию","учение о двух независимых истинах","толкование Писания по святым отцам","искусство спора номиналистов"],"explanation":"«Схоластика была не что иное, как стремление к наукообразному богословию», ибо богословие было тогда высшей целью и главной пружиной умственной жизни Запада.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Схоластика была не что иное, как стремление к наукообразному богословию"}]},{"id":"r2cdebd2d88","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Сколько, по Киреевскому, продолжалась «бесконечная, утомительная игра понятий» схоластики?","options":["семьсот лет","триста лет","пятьсот лет","тысячу лет"],"explanation":"Киреевский говорит о «бесконечной, утомительной игре понятий в продолжение семисот лет», которая лишь усилила рассудочность западного мышления.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Такая бесконечная, утомительная игра понятий в продолжение семи сот лет"}]},{"id":"r48d845726d","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, произошло со схоластикой, когда после взятия Константинополя на Запад повеяло греческой мыслью?","options":["её здание мгновенно разрушилось","она расцвела с новой силой","она слилась с платонизмом","она укрылась в монастырях"],"explanation":"С «неиспорченным воздухом» греческой мысли, по Киреевскому, «всё здание схоластики мгновенно разрушилось», хотя перевес рассудочности остался в умах.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"то все здание схоластики мгновенно разрушилось"}]},{"id":"rfd5d48a71c","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что «родоначальник новейшей философии», по Киреевскому, не считал убедительным, пока не вывел из силлогизма?","options":["сознание о собственном бытии","бытие Бога как совершенного существа","бытие внешнего протяжённого мира","бессмертие разумной души"],"explanation":"Декарт, по Киреевскому, был так слеп к живым истинам, что своё непосредственное сознание о собственном бытии «почитал ещё неубедительным», покуда не вывел его из силлогизма.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"свое внутреннее, непосредственное сознание о собственном своем бытии почитал еще неубедительным"}]},{"id":"r0febd1fd1d","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"В чём, по Киреевскому, «добродушно мог убедиться» Декарт, увлечённый необходимостью своих умозаключений?","options":["что животные — лишь искусные машины","что мир — призрак воображения","что Бог и природа — одно и то же","что дух сознаёт себя в человеке"],"explanation":"Киреевский напоминает, что Декарт счёл всех животных, кроме человека, «только наружными машинами, искусно построенными Создателем». Призрачность мира — мысль Фихте, тождество Бога и природы — Спинозы.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"все животные, выключая человека, суть только наружные машины"}]},{"id":"r2ff7ba2767","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Чего, по Киреевскому, Спиноза не смог разглядеть сквозь «сплошную сеть теорем и силлогизмов»?","options":["следов Живого Создателя в мире","законов движения тел в природе","единства субстанции мироздания","логики математического метода"],"explanation":"Спиноза, по Киреевскому, так плотно сковал разумные выводы о первой причине, что «не мог во всём создании разглядеть следов Живого Создателя», ни заметить внутренней свободы человека.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"не мог во всем создании разглядеть следов Живого Создателя"}]},{"id":"r3ac9659010","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, избыток логической рассудочности заставил предположить Лейбница?","options":["предустановленную гармонию","врождённые идеи разума","«чистую доску» сознания","непознаваемую вещь в себе"],"explanation":"Рассудочность, по Киреевскому, скрыла от Лейбница очевидное сцепление причины и действия и заставила его предположить «Предустановленную Гармонию». Врождённые идеи связывают с Декартом, «чистую доску» — с Локком, вещь в себе — с Кантом.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"заставил его предположить свою Предустановленную Гармонию"}]},{"id":"r9266e95af1","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, «удивительным построением силлогизмов» доказал Фихте?","options":["что мир — призрак, а существует одно Я","что дух и природа тождественны в абсолюте","что вещи в себе непознаваемы для разума","что история есть развитие свободы духа"],"explanation":"По Киреевскому, Фихте доказал, «что весь внешний мир есть только мнимый призрак воображения», а существует лишь одно саморазвивающееся Я. Тождество духа и природы — мысль Шеллинга, непознаваемость вещей в себе — Канта.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"внешний мир есть только мнимый призрак воображения, и что существует в самом деле только одно саморазвивающееся Я"}]},{"id":"rdf1e8ede94","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Кто, по Киреевскому, смог доказать односторонность всего логического мышления благодаря полноте выводов Гегеля?","options":["Шеллинг","Фихте","Кант","Якоби"],"explanation":"Гегель, по Киреевскому, довёл законы логического мышления до последней ясности и тем «дал возможность тому же Шеллингу доказать односторонность всего логического» мышления.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"дал возможность тому же Шеллингу доказать односторонность всего логического"}]},{"id":"r1d7671844e","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Как, по Киреевскому, западные мыслители отнеслись к духовной философии восточных отцов, писавших после X века?","options":["она осталась им почти вовсе неизвестной","они переводили её, чтобы опровергнуть","они переняли её психологический метод","они ставили её выше своей схоластики"],"explanation":"Философия восточных отцов, «прямо и чисто христианская», по Киреевскому, была так мало доступна рассудочному Западу, что «до сих пор осталась им почти вовсе неизвестною».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"до сих пор осталась им почти вовсе неизвестною"}]},{"id":"r8b8dceb525","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"В чём, по Киреевскому, Русская земля даже в удельные времена находила своё притягательное средоточие?","options":["в единстве убеждений, идущих от веры","в единстве языка и общего племени","в единстве правящего княжеского рода","в единстве торговых путей и рынков"],"explanation":"Русская земля, по Киреевскому, сознавала себя одним живым телом, находя средоточие «не столько в единстве языка», сколько в единстве убеждений, происходящих из единства веры.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"не столько в единстве языка находила свое притягательное средоточие, сколько в единстве убеждений"}]},{"id":"rbf9818e3c8","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Какое «прекрасно необдуманное» желание святого Владимира, по Киреевскому, остановила сама Церковь?","options":["прощать всем преступникам","раздать всё имение нищим","уйти от власти в монастырь","крестить всех подданных силой"],"explanation":"Желание Владимира прощать всем преступникам Киреевский считает лучшим выражением готовности русского человека осуществить новое убеждение в жизни. Церковь остановила князя.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"желание Св. Владимира: прощать всем преступникам"}]},{"id":"r0455b3246f","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, Церковь «сначала навсегда» определила, удержав князя от неосуществимого решения?","options":["твёрдые границы между собой и государством","своё главенство над княжеской властью","обязанность князя советоваться с епископами","право суда над всеми мирянами"],"explanation":"Различив личные духовные обязанности и светско-правительственные, Церковь, по Киреевскому, «определила… твёрдые границы между собою и государством», оставаясь вне его мирских отношений.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"определила она, сначала навсегда, твердые границы между собою и государством"}]},{"id":"r0a223b9b6f","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Чем, по Киреевскому, мнение отличается от убеждения?","options":["мнение — вывод логики, убеждение — итог жизни","мнение твёрже, убеждение изменчивее","мнение — от веры, убеждение — от науки","мнение — дело власти, убеждение — личное"],"explanation":"Мнение и убеждение — «две совершенно особые пружины» двух общественных устройств: «первое — вывод из логических соображений; второе — итог всей жизни».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"первое – вывод из логических соображений; второе – итог всей жизни"}]},{"id":"rab9d1c7a03","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, было первым основанием русской общественности?","options":["личность","поземельная собственность","родовая знать","княжеская власть"],"explanation":"«В устройстве Русской общественности, личность есть первое основание, а право собственности только её случайное отношение». На Западе, напротив, первым основанием была поземельная собственность.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"В устройстве Русской общественности, личность есть первое основание, а право собственности только ее случайное отношение"}]},{"id":"rbc4e8ee523","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Почему, по Киреевскому, земля принадлежала общине?","options":["она состоит из семей, способных её возделывать","так было определено княжеской жалованной грамотой","так было удобнее собирать подати с земли","земля считалась достоянием Церкви и князя"],"explanation":"Киреевский пишет: «Общине земля принадлежит потому, что община состоит из семей, состоящих из лиц, могущих землю возделывать»; с ростом семей земля переделялась.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Общине земля принадлежит потому, что община состоит из семей, состоящих из лиц, могущих землю возделывать"}]},{"id":"r032de74885","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, русский человек особенно старается сохранить во время молитвы?","options":["трезвый ум и цельность духа","пламенное умиление сердца","строгость внешнего обряда","непрерывность поклонов"],"explanation":"Русский человек, по Киреевскому, не кричит от восторга и не падает без чувств от умиления: «во время подвига молитвенного он особенно старается сохранить трезвый ум и цельность духа».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"он особенно старается сохранить трезвый ум и цельность духа"}]},{"id":"r44dc87c29e","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Какой характер, по Киреевскому, приняло богословие на Западе?","options":["рассудочной отвлечённости","мистического созерцания","пастырской практичности","аскетической строгости"],"explanation":"В итоговом сравнении Киреевский пишет: «богословие на Западе приняло характер рассудочной отвлечённости», а в православном мире сохранило внутреннюю цельность духа.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"богословие на Западе приняло характер рассудочной отвлеченности"}]},{"id":"r8cd6e275db","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Как, по Киреевскому, в православном мире ум стремится к истине?","options":["возвышая самосознание к сердечной цельности","посредством логического сцепления понятий","через опыт и наблюдение над природой","через буквальное послушание Писанию"],"explanation":"На Западе, по Киреевскому, ум движется к истине «посредством логического сцепления понятий», а в православном мире — «посредством внутреннего возвышения самосознания к сердечной цельности».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"посредством внутреннего возвышения самосознания к сердечной цельности и средоточию разума"}]},{"id":"r7eeb33751b","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Какое единство, по Киреевскому, искал Запад в отличие от древней России?","options":["наружное, мёртвое","внутреннее, живое","соборное, духовное","родовое, кровное"],"explanation":"В итоговом сопоставлении: «там искание наружного, мёртвого единства, — здесь стремление к внутреннему, живому».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"там искание наружного, мертвого единства"}]},{"id":"r4b0813d702","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Где, по Киреевскому, в древней России было сосредоточено высшее знание?","options":["в молитвенных монастырях","при княжеских дворах","в городских училищах","в архиерейских школах"],"explanation":"Киреевский противопоставляет схоластические и юридические университеты Запада молитвенным монастырям древней России, «сосредоточивавшим в себе высшее знание».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"в древней России молитвенные монастыри, сосредоточивавшие в себе высшее знание"}]},{"id":"r58c6773ff6","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Из чего, по Киреевскому, выросла государственность древней России?","options":["из естественного развития народного быта","из насилий завоевания чужих земель","из договора общин с призванными варягами","из подражания византийскому образцу"],"explanation":"На Западе государственность возникла «из насилий завоевания», а в России — «из естественного развития народного быта, проникнутого единством основного убеждения».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"здесь из естественного развития народного быта"}]},{"id":"re7254def34","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Каким, по Киреевскому, было отношение сословий в древней России?","options":["единодушная совокупность при разновидности","враждебная разграниченность сословий","полное равенство без всяких различий","строгое кастовое деление по рождению"],"explanation":"«Там враждебная разграниченность сословий, — в древней России их единодушная совокупность, при естественной разновидности».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"в древней России их единодушная совокупность, при естественной разновидности"}]},{"id":"r7339980894","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Откуда, по Киреевскому, рождались законы в древней России?","options":["естественно из быта","из воли государя","из церковных канонов","из господствующего мнения"],"explanation":"«Там законы исходят искусственно из господствующего мнения, — здесь они рождались естественно из быта».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"там законы исходят искусственно из господствующего мнения, – здесь они рождались естественно из быта"}]},{"id":"r2c0efb4517","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Как, по Киреевскому, совершались улучшения в древней России?","options":["стройным естественным возрастанием","насильственными и внезапными переменами","указами, данными сверху государями","заимствованием у соседних народов"],"explanation":"«Там улучшения всегда совершались насильственными переменами, — здесь стройным естественным возрастанием».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"там улучшения всегда совершались насильственными переменами, – здесь стройным естественным возрастанием"}]},{"id":"r5377201e96","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Что, по Киреевскому, в древней России противостояло западной «прихоти моды»?","options":["твёрдость быта","строгость поста","простота одежды","почитание старцев"],"explanation":"В ряду противопоставлений Киреевский пишет: «там прихоть моды, — здесь твёрдость быта».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"там прихоть моды, – здесь твердость быта"}]},{"id":"re665e89a11","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Как, по Киреевскому, русский человек относится к себе, в отличие от западного с его «рассудочной уверенностью» в своём совершенстве?","options":["постоянно не доверяет себе","уверен в своей праведности","равнодушен к своему совершенству","полагается на суд общества"],"explanation":"У русского, по Киреевскому, — глубокая тишина самосознания «при постоянной недоверчивости к себе и при неограниченной требовательности нравственного усовершения».","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"при постоянной недоверчивости к себе и при неограниченной требовательности нравственного усовершения"}]},{"id":"re15ec6cf80","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Каким словом Киреевский итожит характер западной образованности, перечисляя её черты?","options":["раздвоение","отчуждение","обмирщение","окаменение"],"explanation":"Итог сопоставления: «одним словом, там раздвоение духа, раздвоение мыслей, раздвоение наук, раздвоение государства…», а в древней России — стремление к цельности.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"одним словом, там раздвоение духа, раздвоение мыслей, раздвоение наук"}]},{"id":"re913d86a96","s":2,"topic":"Киреевский. «О характере просвещения Европы»","text":"Почему, по Киреевскому, арабская образованность развилась ещё быстрее западной?","options":["она была ещё одностороннее","она опиралась на греческие рукописи","её щедро поддерживали халифы","она не знала церковного надзора"],"explanation":"Киреевский пишет: «Ещё быстрее совершилось развитие образованности Арабской, ибо оно было ещё одностороннее», хотя имело то же отвлечённо-рассудочное направление.","sources":[{"title":"Киреевский. О характере просвещения Европы и о его отношении к просвещению России","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-haraktere-prosveshenija-evropy-i-o-ego-otnoshenii-k-prosvesheniyu-rossii/","quote":"Еще быстрее совершилось развитие образованности Арабской, ибо оно было еще одностороннее"}]},{"id":"r4d7fdf93a3","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, в Православной Церкви не смешивается между собой, в отличие от Римской Церкви и протестантских исповеданий?","options":["Божественное Откровение и человеческое мышление","церковная власть и власть государственная","вера народа и учёное богословие","Священное Писание и Священное Предание"],"explanation":"Отношение разума и веры в Православии, по Киреевскому, особое: «Божественное Откровение и человеческое мышление не смешиваются»; пределы между ними не переступаются ни наукой, ни учением Церкви.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"в Православной Церкви Божественное Откровение и человеческое мышление не смешиваются"}]},{"id":"r034c623e45","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Чего, по Киреевскому, верующее мышление никогда не примет за простой вывод разума?","options":["догмата Откровения","нравственного закона","бытия Божия","церковного обряда"],"explanation":"Как бы ни стремилось верующее мышление согласить разум с верой, оно «никогда не примет никакого догмата Откровения за простой вывод разума» и не придаст выводу разума авторитета догмата.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"никогда не примет никакого догмата Откровения за простой вывод разума"}]},{"id":"rf8b0b7ff91","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Кто, по Киреевскому, может сдвинуть в Православной Церкви границу между Откровением и мышлением?","options":["никто — ни патриарх, ни собор епископов","лишь Вселенский собор всех епископов","патриарх с согласия своего синода","общее мнение верующего народа"],"explanation":"Границы, по Киреевскому, стоят твёрдо: «никакой патриарх, никакое собрание епископов, никакое глубокомысленное соображение учёного, никакая власть» не может их сдвинуть.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Никакой патриарх, никакое собрание епископов, никакое глубокомысленное соображение ученого"}]},{"id":"r98380f7886","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"От чего, по Киреевскому, неприкосновенность пределов Откровения ограждает разум?","options":["от вмешательства церковного авторитета","от сомнения и соблазна неверия в Бога","от гордости и рассудочного самомнения","от влияния чуждых западных систем"],"explanation":"Неприкосновенность пределов Откровения, по Киреевскому, ограждает учение Церкви от перетолкований разума, а разум — «от неправильного вмешательства Церковного авторитета».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"ограждает разум от неправильного вмешательства Церковного авторитета"}]},{"id":"r25e4666c69","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Какой пример вмешательства церковного авторитета в дела разума приводит Киреевский?","options":["преследование Галилея","казнь Яна Гуса","сожжение Джордано Бруно","процесс над тамплиерами"],"explanation":"Православному христианину, по Киреевскому, равно непонятно и то, «как можно жечь Галилея» за несогласие с понятиями иерархии, и то, как можно отвергать апостольское послание за несогласие с понятиями своего времени.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"как можно жечь Галилея за несогласие его мнений с понятиями Церковной иерархии"}]},{"id":"r762e7290b9","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Почему, по Киреевскому, верующее мышление стремится согласить разум с учением веры?","options":["потому что истина одна","потому что так велит Церковь","потому что разум без веры бесплоден","потому что вера без разума слепа"],"explanation":"Чем твёрже стоят границы Откровения, тем сильнее потребность согласить разум с верой, «ибо истина одна, и стремление к сознанию этого единства есть постоянный закон» разумной деятельности.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Ибо истина одна, и стремление к сознанию этого единства есть постоянный закон"}]},{"id":"rc35e896b66","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"В чём, по Киреевскому, главное отличие православного мышления?","options":["оно возвышает сам разум до согласия с верой","оно подгоняет понятия под требования веры","оно отвергает выводы естественных наук","оно опирается лишь на авторитеты"],"explanation":"Православное мышление, по Киреевскому, ищет не отдельные понятия устроить по требованиям веры, а «самый разум поднять выше своего обыкновенного уровня», до сочувственного согласия с верой.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"самый разум поднять выше своего обыкновенного уровня"}]},{"id":"r136375888b","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, составляет первое условие такого возвышения разума?","options":["собрать все свои силы в неделимую цельность","отречься от логики ради одного чувства","подчиниться авторитету иерархии","очистить ум от всякого чувства"],"explanation":"Первое условие, по Киреевскому, — чтобы разум «стремился собрать в одну неделимую цельность все свои отдельные силы», в обычном состоянии разрозненные и противоречивые.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"собрать в одну неделимую цельность все свои отдельные силы"}]},{"id":"r89fb00f26c","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, разум не должен признавать единственным органом разумения истины?","options":["отвлечённую логическую способность","соборное сознание всей Церкви","святоотеческое церковное предание","Божественное Откровение в Писании"],"explanation":"Разум, по Киреевскому, не должен признавать «своей отвлечённой логической способности за единственный орган разумения истины»; так же не надёжны в отдельности восторженное чувство, эстетический смысл и даже любовь сердца.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"чтобы он не признавал своей отвлеченной логической способности за единственный орган разумения истины"}]},{"id":"r8fd8dc537f","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Как Киреевский называет мышление, в котором при каждом движении души «все её струны» звучат в полном аккорде?","options":["цельное","отвлечённое","рассудочное","созерцательное"],"explanation":"Киреевский пишет: «в цельном мышлении, при каждом движении души, все её струны должны быть слышны в полном аккорде, сливаясь в один гармонический звук».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"все ее струны должны быть слышны в полном аккорде, сливаясь в один гармонический звук"}]},{"id":"rb02a1dce17","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, сокрыто в глубине души от обыкновенного состояния духа, но достижимо для ищущего?","options":["живое общее средоточие всех сил разума","врождённые идеи, данные до опыта","память души о прежней жизни","голос совести, данный от рождения"],"explanation":"Киреевский говорит о внутреннем сознании, «что есть в глубине души живое общее средоточие для всех отдельных сил разума», одно достойное постигать высшую истину.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"в глубине души живое общее средоточие для всех отдельных сил разума"}]},{"id":"r5f4fcb2714","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Как, по Киреевскому, свободное развитие естественных законов разума сказывается на вере православного?","options":["не может быть для неё вредно","неизбежно ведёт к неверию","допустимо лишь под надзором Церкви","полезно лишь учёным богословам"],"explanation":"Киреевский пишет, что «свободное развитие естественных законов разума не может быть вредно для веры православно-мыслящего».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"свободное развитие естественных законов разума не может быть вредно для веры православно-мыслящего"}]},{"id":"r3a4df13c09","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Почему, по Киреевскому, православно-верующий может безвредно понять любые философские системы?","options":["он стоит на высшей степени разумения","он заранее знает их ложность","Церковь разрешает ему их изучение","его защищает послушание духовнику"],"explanation":"Находясь «на этой высшей степени мышления», православно-верующий, по Киреевскому, легко и безвредно понимает все системы, исходящие из низших степеней разума, и видит их ограниченность.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Находясь на этой высшей степени мышления, православно-верующий легко и безвредно может понять все системы мышления"}]},{"id":"r8cc2760ae6","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Чем, по Киреевскому, является философия?","options":["проводником мысли между науками и верой","одной из наук наряду со всеми другими","особым видом веры для образованных","служанкой церковного богословия"],"explanation":"«Философия не есть одна из наук, и не есть вера. Она общий итог и общее основание всех наук, и проводник мысли между ними и верою».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Она общий итог и общее основание всех наук, и проводник мысли между ними и верою"}]},{"id":"r870688909c","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Где, по Киреевскому, философии быть не может?","options":["где есть вера, но нет образованности","где вера исчезла, а науки развиты","где наука свободна от надзора Церкви","где народ подчинён воле одного государя"],"explanation":"«Где есть вера, и нет развития разумной образованности, там и философии быть не может». Там же, где вера исчезла, философские убеждения, напротив, заменяют убеждения веры.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Где есть вера, и нет развития разумной образованности, там и философии быть не может"}]},{"id":"rba63bf05c5","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, происходит там, где есть науки и образованность, но вера исчезла?","options":["философские убеждения заменяют убеждения веры","наступает полное безверие и отчаяние","народ возвращается к прежнему язычеству","наука сама становится новой Церковью"],"explanation":"Там, где вера исчезла, «убеждения философские заменяют убеждения веры» и, являясь в виде предрассудка, направляют мышление и жизнь народа; их выводы принимают на веру.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"там убеждения философские заменяют убеждения веры"}]},{"id":"r51c97e3758","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Какой исход, кроме вытеснения веры, Киреевский допускает, когда вера народа сталкивается с заимствованной образованностью?","options":["вера произведёт свою философию","народ отвергнет чужую образованность","вера и наука разойдутся навсегда","Церковь запретит чужую науку"],"explanation":"Возможны два исхода: или образованность вытеснит веру, или вера, преодолевая внешнюю образованность, «из самого соприкосновения с нею произведёт свою философию».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"или вера, преодолевая в мыслящем сознании народа эту внешнюю образованность, из самого соприкосновения с нею произведет свою философию"}]},{"id":"r4593394960","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Когда, по Киреевскому, угасла православно-христианская философия на Востоке?","options":["вместе со свободой и образованностью Греции","с разделением Восточной и Западной Церквей","с победой исихастов над Варлаамом","с крещением Руси при князе Владимире"],"explanation":"Православная философия процветала, пока на Востоке жило внешнее просвещение, и, по Киреевскому, «погасла только вместе с свободою Греции и с уничтожением её образованности».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Она погасла только вместе с свободою Греции и с уничтожением ее образованности"}]},{"id":"rdd8f1fff8a","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Как Киреевский называет следы православной философии, сохранившиеся в писаниях святых отцов?","options":["живые искры","светлые зёрна","тихие голоса","сокрытые клады"],"explanation":"Следы этой философии, по Киреевскому, сохраняются в писаниях святых отцов «как живые искры, готовые вспыхнуть при первом прикосновении верующей мысли».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"как живые искры, готовые вспыхнуть при первом прикосновении верующей мысли"}]},{"id":"r7a3c333625","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Почему, по Киреевскому, нельзя возобновить философию святых отцов в том виде, как она была?","options":["она отвечала вопросам своего времени","её тексты утрачены после падения Византии","её запретила Римская Церковь","она написана на мёртвом языке"],"explanation":"Философия отцов, по Киреевскому, возникла из отношения веры к образованности их эпохи и «должна была соответствовать и вопросам своего времени»; новая образованность требует нового развития философии.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Возникая из отношения веры к современной образованности, она должна была соответствовать и вопросам своего времени"}]},{"id":"r77c9520d2a","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, нужно для удовлетворительного решения задачи новой философии?","options":["совокупная деятельность единомысленных","гений одного великого мыслителя","покровительство государства и Церкви","перевод лучших западных систем"],"explanation":"Для решения этой задачи, по Киреевскому, «нужна совокупная деятельность людей единомысленных»: философия, которая не хочет оставаться в книге, должна стать общим делом.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"нужна совокупная деятельность людей единомысленных"}]},{"id":"r1f8a4def1d","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, «одно осталось серьёзное» для западного человека?","options":["промышленность","наука","политика","искусство"],"explanation":"Киреевский пишет: «Одно осталось серьёзное для человека: это промышленность», ибо уцелела одна действительность — его физическая личность; промышленность управляет миром без веры и поэзии.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Одно осталось серьезное для человека: это промышленность"}]},{"id":"r41c8da07cf","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, погибло на Западе вместе с верой?","options":["поэзия","ремёсла","право","торговля"],"explanation":"«Не только вера утратилась на Западе, но вместе с ней погибла и поэзия», которая без живых убеждений превратилась в пустую забаву.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"но вместе с ней погибла и поэзия"}]},{"id":"rc303bb9dcc","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"С кем Киреевский сравнивает человека, раздробившего цельность духа и оторвавшегося от действительности?","options":["со зрителем в театре","с узником в темнице","со странником без дома","с актёром на сцене"],"explanation":"Раздробив цельность духа, человек, по Киреевскому, «сам явился на земле существом отвлечённым, как зритель в театре», равно способный всему сочувствовать.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"сам явился на земле существом отвлеченным, как зритель в театре"}]},{"id":"r43487f97b8","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, «праздновалось по Европе» с возрождением наук?","options":["освобождение от авторитета Аристотеля","возвращение к философии Платона","ослабление власти римских пап","открытие древних рукописей"],"explanation":"С возрождением наук упал безграничный авторитет Аристотеля, и, по Киреевскому, «освобождение от него праздновалось по Европе», хотя сродство западного ума с ним сохранилось.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Освобождение от него праздновалось по Европе"}]},{"id":"rfdd9a5d6db","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, разорвала система Аристотеля?","options":["цельность умственного самосознания","союз философии с поэзией и мифом","единство греческих философских школ","связь умозрительной науки с ремеслом"],"explanation":"«Система Аристотеля разорвала цельность умственного самосознания» и перенесла корень убеждений в отвлечённое сознание рассуждающего разума.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Система Аристотеля разорвала цельность умственного самосознания"}]},{"id":"re369a75a8e","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Какими орудиями, по Киреевскому, система Аристотеля познавала истину?","options":["логикой ума и безучастным наблюдением мира","созерцанием идей и припоминанием души","верой отцов и преданием мудрецов","вдохновением и чувством прекрасного"],"explanation":"Орудия аристотелевской системы, по Киреевскому, «ограничивались логическою деятельностью ума и безучастною наблюдательностью внешнего мира». Припоминание идей — учение Платона.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"ограничивались логическою деятельностью ума и безучастною наблюдательностью внешнего мира"}]},{"id":"rb3bdf62102","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Когда, по Аристотелю в изложении Киреевского, человек начинает любомудрствовать?","options":["когда освободится от житейских нужд","когда мудрость освободит его от нужд","когда душа вспомнит виденные идеи","когда удивится устройству мира"],"explanation":"Аристотель, по Киреевскому, учил, что человек начинает любомудрствовать, лишь освободившись от нужд житейских; стоики же считали, что только мудрость освобождает от них.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Когда человек освободится от нужд житейских, говорил он, тогда только начинает он любомудрствовать"}]},{"id":"r75d9be074b","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"В чём, по Аристотелю в изложении Киреевского, состояла добродетель?","options":["в золотой середине между крайностями","в подражании совершенному божеству","в бесстрастии мудреца перед судьбой","в знании блага и следовании ему"],"explanation":"Добродетель у Аристотеля, по Киреевскому, «не требовала высшей сферы бытия», а состояла «в отыскании золотой середины между порочными крайностями». Бесстрастие — идеал стоиков.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"состояла в отыскании золотой середины между порочными крайностями"}]},{"id":"r1be999308a","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Какую роль, по Киреевскому, сыграла греческая философия, освободив ум от ложных учений язычества?","options":["приготовила поле для христианского посева","заменила собой прежнюю народную религию","стала основой будущего римского права","сохранила язычество от скорого упадка"],"explanation":"Греческая философия, по Киреевскому, была «полезной воспитательницей ума» и привела его в состояние, способное принять высшую истину: «Философия приготовила поле для Христианского посева».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Философия приготовила поле для Христианского посева"}]},{"id":"re9edef3c2b","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Почему, по Киреевскому, Римская Церковь оторвалась от Церкви Вселенской?","options":["из-за формально-логического вывода разума","из-за спора о власти над Болгарской Церковью","из-за различия в церковных обрядах","по воле германских императоров"],"explanation":"Киреевский пишет: «Римская Церковь оторвалась от Церкви Вселенской вследствие вывода разума формально-логического», искавшего наружного единства.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Римская Церковь оторвалась от Церкви Вселенской вследствие вывода разума формально-логического"}]},{"id":"r56f72b2cdb","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Где, по Киреевскому, рациональная философия развивалась почти исключительно?","options":["в протестантских землях","в католических странах","в православных землях","в мусульманском мире"],"explanation":"Реформация, по Киреевскому, освободила народы от умственного угнетения Рима, поэтому «философия рациональная развивалась почти исключительно в землях протестантских».","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"философия рациональная развивалась почти исключительно в землях протестантских"}]},{"id":"raf2bbdc948","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Кто, по Киреевскому, разрушил Пор-Рояль с его уединёнными мыслителями?","options":["иезуиты","янсенисты","галликане","кальвинисты"],"explanation":"Во Франции, по Киреевскому, могла бы возникнуть своя философия, но «происки иезуитов разрушили Пор-Рояль» и погубили рождавшееся там живое направление мысли.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Но происки иезуитов разрушили Пор-Рояль с его уединенными мыслителями"}]},{"id":"reb91be7f5c","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Чьё живое «уклонение от официального мышления Рима», по Киреевскому, не поняла «холодная, торжественная логика» Боссюэта?","options":["Фенелона","Паскаля","Мальбранша","Арно"],"explanation":"Боссюэт, по Киреевскому, не понял живого и тёплого в уклонении Фенелона и принудил его авторитетом папы отречься от заветных убеждений.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Холодная, торжественная логика Боссюэта не поняла того, что было живого и теплого в уклонении Фенелона"}]},{"id":"ra65b0d84ec","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, перенесённое из Греции, по Киреевскому, открыло многим европейцам различие между учением христианским и римским?","options":["писания святых отцов","рукописи Аристотеля","греческие служебники","диалоги Платона"],"explanation":"Писания святых отцов, перенесённые из Греции после её падения, по Киреевскому, «открыли глаза многим Европейцам»; тогда у Запада была ещё одна возможность вернуться к Церкви.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Писания Святых Отцов, перенесенные из Греции после падения, открыли глаза многим Европейцам"}]},{"id":"r13d43f1380","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Кому, по Киреевскому, Лютер писал, что изучает папские декреталии и находит в них противоречия и ложь?","options":["Меланхтону","Эразму","Цвингли","Кальвину"],"explanation":"Киреевский приводит письмо Лютера к Меланхтону: изучив декреталии, Лютер не может поверить, что их внушал Святой Дух, и собирается обратиться к Вселенским Соборам.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"писал тогда Лютер к Меланхтону"}]},{"id":"r04e8b579ea","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Сколько Вселенских Соборов, по Киреевскому, признаёт «целая половина» христианского человечества, в отличие от шестнадцати у Запада?","options":["семь","восемь","четыре","двенадцать"],"explanation":"Если бы Лютер вспомнил, что половина христиан «признаёт Вселенских Соборов только семь, а не шестнадцать» и чиста от злоупотреблений Запада, реформация, по Киреевскому, могла пойти иначе.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"признает Вселенских Соборов только семь, а не шестнадцать"}]},{"id":"r2fc59aefe2","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Что, по Киреевскому, решило судьбу реформации?","options":["недоразумение, вольное или невольное","воля германских князей и городов","изобретение книгопечатания","проповедь Кальвина в Женеве"],"explanation":"«Недоразумение, — вольное или невольное, один Бог знает, — решило её судьбу»: Лютер не обратился к Православной Церкви и сочинил новое исповедание.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Недоразумение, – вольное или невольное, один Бог знает, – решило ее судьбу"}]},{"id":"reeae5c9b84","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"Какую систему Киреевский называет выражением понятия о разуме, выработанного новейшей философией?","options":["Шеллинго-Гегельянскую","Канто-Фихтевскую","Картезианскую","Лейбнице-Вольфианскую"],"explanation":"Понятие о разуме новейшей философии, «которого выражением служит система Шеллинго-Гегельянская», по Киреевскому, не противоречило бы безусловно православному пониманию, если бы знало свою ограниченность.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"которого выражением служит система Шеллинго-Гегельянская"}]},{"id":"ra0907b21ed","s":2,"topic":"Киреевский. «О необходимости и возможности новых начал для философии»","text":"От чего, по Киреевскому, зависят все ложные выводы рационального мышления?","options":["от притязания на полное познание истины","от ошибок в самих законах логики","от недостатка опытных данных науки","от влияния страстей на рассудок"],"explanation":"«Все ложные выводы рационального мышления зависят только от его притязания на высшее и полное познание истины»; сознав свою ограниченность, оно было бы полезным.","sources":[{"title":"Киреевский. О необходимости и возможности новых начал для философии","url":"https://azbyka.ru/otechnik/Ivan_Kireevskij/o-neobhodimosti-i-vozmozhnosti-novyh-nachal-dlja-filosofii/","quote":"Все ложные выводы рационального мышления зависят только от его притязания на высшее и полное познание истины"}]},{"id":"r35b15d4346","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Какому государю Константин Аксаков представил записку «О внутреннем состоянии России»?","options":["Александру II","Николаю I","Александру III","Александру I"],"explanation":"Записка была представлена императору Александру II в 1855 году, в начале его царствования; позже Аксаков подал к ней «Дополнение».","sources":[{"title":"Аксаков. О внутреннем состоянии России, заглавие","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"представленная государю императору Александру II в 1855 г."}]},{"id":"rd9f2d73020","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Каким словом Аксаков характеризует русский народ в первой главе записки?","options":["негосударственный","державный","вечевой","самодержавный"],"explanation":"«Русский народ есть народ не государственный», то есть, по Аксакову, не стремящийся к государственной власти, не желающий политических прав и не имеющий «даже зародыша народного властолюбия».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. I","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Русский народ есть народ не государственный, т.е. не стремящийся к государственной власти"}]},{"id":"re36f7c5f12","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что Аксаков считает «самым первым доказательством» своей мысли о русском народе в начале записки?","options":["добровольное призвание варягов","крещение Руси при Владимире","терпение под ордынским игом","избрание царём Михаила Романова"],"explanation":"Первым доказательством Аксаков называет «начало нашей истории: добровольное призвание чужой государственной власти в лице варягов». Вторым, ещё более сильным, — события 1612 года.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. I","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Самым первым доказательством тому служит начало нашей истории: добровольное призвание чужой государственной власти в лице варягов"}]},{"id":"rea2fa15c86","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, сделал народ в 1612 году, победив врагов без государя и бояр?","options":["избрал царя и поручил ему свою судьбу","созвал вече и стал править сам","отдал всю власть князю Пожарскому","призвал на престол польского королевича"],"explanation":"Аксаков пишет, что народ, «победивший без царя и бояр», как в 862 году, «призвал государственную власть, избрал царя и поручил ему неограниченно судьбу свою», а сам разошёлся по домам.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. I","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"так в 1612 году народ призвал государственную власть, избрал царя"}]},{"id":"r77350908af","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"О чём, по свидетельству поляков 1612 года в изложении Аксакова, только и толкует русский народ?","options":["о вере","о земле","о царе","о свободе"],"explanation":"Поляки, современники 1612 года, с удивлением писали, что русский народ «только и толкует, что о вере, а не о политических условиях».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Русский народ только и толкует, что о вере, а не о политических условиях"}]},{"id":"r976a10f42d","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Как называли себя в просьбах государю служилые люди «от первого боярина до последнего стрельца»?","options":["холопами","богомольцами","рабами","подданными"],"explanation":"Служилые люди, по Аксакову, писались в челобитных холопами государя, а земские люди — его сиротами.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"назывались его холопами, от первого боярина до последнего стрельца"}]},{"id":"raad3f07f9c","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, значило слово «сирота» в обращении земских людей к государю?","options":["нуждающийся в защите","лишённый родителей","бедный и бесправный","верный и покорный"],"explanation":"Сирота на русском языке, по Аксакову, не значит orphelin: «сирота есть беспомощный, нуждающийся в опоре, в защите». Земля, называя себя сиротой, признаёт государство своим защитником.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"сирота есть беспомощный, нуждающийся в опоре, в защите"}]},{"id":"r053b468209","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"На какие две стороны, по Аксакову, разделялась Россия в понимании русского человека?","options":["на государство и землю","на царство и Церковь","на город и деревню","на знать и простонародье"],"explanation":"Аксаков указывает на древнее деление России «на государство и землю (правительство и народ)» и на выражения «государево» и «земское дело».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"на государство и землю (правительство и народ)"}]},{"id":"r3085aabf4d","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, разумелось под «земским делом»?","options":["весь народный быт, вся жизнь народа","сбор податей с пахотной земли","суд и расправа в уездах и волостях","межевание и раздача поместий"],"explanation":"Под государевым делом разумелось всё правительство, под земским — «весь быт народный, вся жизнь народа», его благосостояние: земледелие, промышленность, торговля.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Под земским делом разумелся весь быт народный, вся жизнь"}]},{"id":"reb3325dbf0","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, «доселе значит в народе» выражение «государева служба»?","options":["службу военную","службу при дворе","службу в приказах","уплату податей"],"explanation":"Аксаков пишет: «Государева служба доселе значит в народе: служба военная». Защита земли — главное дело государства.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Государева служба доселе значит в народе: служба военная"}]},{"id":"r556ff23e3b","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, русский народ хотел оставить для себя, отдав государственную власть правительству?","options":["свою внутреннюю общественную жизнь","право избирать местных начальников","самоуправление вольных городов","военную силу народного ополчения"],"explanation":"Народ, по Аксакову, «хотел оставить для себя свою не политическую, свою внутреннюю общественную жизнь, свои обычаи, свой быт — жизнь мирную духа».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Он хотел оставить для себя свою не политическую, свою внутреннюю общественную жизнь"}]},{"id":"r7d51c4e932","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, народ образовал в себе ещё до христианства, «готовый к его принятию»?","options":["жизнь общины","вечевое правление","княжескую власть","родовую знать"],"explanation":"Ещё до христианства народ, по Аксакову, «образовал в себе жизнь общины, освящённую потом принятием христианства».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"народ наш образовал в себе жизнь общины, освященную потом принятием христианства"}]},{"id":"r7024f0ce61","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Какие слова Христа, по Аксакову, помнит русский народ, отделяя от себя государство?","options":["«Воздайте кесарева кесаревы, а Божия Богови»","«Не мир пришёл Я принести, но меч»","«Блаженны миротворцы, ибо они сынами Божиими нарекутся»","«Кто хочет быть первым, будь всем слугою»"],"explanation":"По Аксакову, русский народ помнит слова Христа «воздайте кесарева кесаревы, а Божия Богови» и «Царство Моё несть от мира сего», поэтому ищет свободы духа, а не власти.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. II","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"он помнит слова Христа: воздайте кесарева кесаревы, а Божия Богови"}]},{"id":"r20e97bb328","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Почему, по Аксакову, верховная власть в России должна принадлежать монарху?","options":["лишь одно лицо может быть неограниченной властью","так завещали первые князья Рюриковичи","так устроена власть в православной Византии","монархия обходится народу дешевле других форм"],"explanation":"«Вне народа, вне общественной жизни, может быть только лицо… Одно только лицо может быть неограниченным правительством», поэтому, по Аксакову, необходим государь, монарх.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. V","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Одно только лицо может быть неограниченным правительством"}]},{"id":"rd5f54355d4","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, русский человек удерживает за собой, признавая неограниченную власть государства?","options":["независимость духа, совести, мысли","право восстать против тирана","право выбирать местных начальников","право суда над чиновниками"],"explanation":"Признавая неограниченную власть, русский человек, по Аксакову, «удерживает за собою совершенную независимость духа, совести, мысли» и потому не раб, а человек свободный.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. V","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"он удерживает за собою совершенную независимость духа, совести, мысли"}]},{"id":"r447d338414","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Как Аксаков оценивает тех, кто видит в покорности русского народа «дух рабства» или «дух законного порядка»?","options":["обе стороны ошибаются, судя по-западному","права первая сторона, видящая рабство","права вторая сторона, видящая порядок","обе стороны отчасти правы и дополняют друг друга"],"explanation":"Аксаков пишет: одни огорчаются и называют это духом рабства, другие радуются и называют духом законного порядка, «но и те и другие ошибаются, ибо судят так о России по западным взглядам».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. I","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"но и те и другие ошибаются, ибо судят так о России по западным взглядам"}]},{"id":"rf40fea81f0","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Чем, по Аксакову, увлеклись люди Запада, оставив внутренний путь веры и духа?","options":["властолюбием масс и конституциями","мирским богатством и торговлей","наукой и неверием философов","войнами и захватом колоний"],"explanation":"Народы Запада, по Аксакову, «увлеклись тщеславными побуждениями народного властолюбия», наделали республик и конституций, обеднели душой и утратили веру.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. VII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"увлеклись тщеславными побуждениями народного властолюбия"}]},{"id":"r9c42696d8f","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Как Аксаков формулирует разделение прав между царём и землёй по примеру Земских соборов?","options":["действие — право государево, мнение — право страны","закон — право государево, суд — право страны","война — право государево, мир — право страны","власть — право государево, подати — право страны"],"explanation":"Ответы выборных на соборах начинались словами «делай, как тебе угодно, а наша мысль такова». Отсюда вывод Аксакова: «действие — право государево, мнение — право страны».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. VIII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Итак, действие -- право государево, мнение -- право страны"}]},{"id":"rf86363fe6d","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Как, по Аксакову, обычно начинались ответы выборных на Земских соборах?","options":["«Делай, как тебе угодно, а наша мысль такова»","«Повелевай, и мы исполним без рассуждения»","«Земля решила, а ты, государь, утверди»","«Просим тебя, государь, уступить земле»"],"explanation":"Все ответы, по Аксакову, начинались так: «Как поступить в этом случае, это зависит от тебя, государь. Делай, как тебе угодно, а наша мысль такова». Соборы имели смысл только мнения.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. VIII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Делай, как тебе угодно, а наша мысль такова"}]},{"id":"re67630a66a","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"С кем, по Аксакову, царь Алексей Михайлович советовался на Красной площади, когда в Москве поднялся в цене хлеб?","options":["с купцами","с боярами","с патриархом","со стрельцами"],"explanation":"Как пример того, что цари вызывали мнение страны, Аксаков приводит случай: царь Алексей Михайлович созвал на Красную площадь купцов, чтобы посоветоваться о дороговизне хлеба.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. VIII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"царь Алексей Михайлович созывает на Красную площадь купцов посоветоваться с ними"}]},{"id":"r3ceeb13820","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, сделал Пётр, когда Москва «стала не угодна государю»?","options":["перенёс столицу на край России","упразднил Земские соборы навсегда","перенёс патриарший престол","переселил бояр в Новгород"],"explanation":"Аксаков пишет: «Москва стала не угодна государю, и он перенёс столицу на край России», в новый город, которому дал немецкое название.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Москва стала не угодна государю, и он перенес столицу на край России"}]},{"id":"rec4d29e1c7","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, образовалось вместо древнего союза земли и государства после разрыва царя с народом?","options":["иго государства над землёй","союз дворянства с престолом","власть Сената над государем","господство Церкви над царём"],"explanation":"Так, по Аксакову, «вместо прежнего союза образовалось иго государства над землёю», и Русская земля стала как бы завоёванной.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"так вместо прежнего союза образовалось иго государства над землею"}]},{"id":"rc3e838ac62","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Какое значение, по Аксакову, получил русский монарх после разрыва царя с народом?","options":["значение деспота","значение отца народа","значение помазанника","значение слуги закона"],"explanation":"«Так русский монарх получил значение деспота, а свободно-подданный народ — значение раба-невольника в своей земле!»","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Так русский монарх получил значение деспота"}]},{"id":"r00d03b4432","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, Пётр поразил растлением, придав России внешнее величие?","options":["её внутреннюю целость","её православную Церковь","её войско и флот","её древний язык"],"explanation":"«Он много придал ей внешнего величия, но внутреннюю её целость он поразил растлением», внеся в жизнь семена разрушения и вражды.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"но внутреннюю ее целость он поразил растлением"}]},{"id":"r190b2b8f87","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Чьими силами, по Аксакову, «Петровское государство побеждает»?","options":["силами ещё допетровской России","силами иноземных наёмников","силами нового служилого дворянства","силами созданного Петром флота"],"explanation":"Аксаков пишет, что славные дела Петра и преемников совершены силами России, выросшей на древней почве: «Петровское государство побеждает с силами ещё до-Петровской России».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Петровское государство побеждает с силами еще до-Петровской России"}]},{"id":"rf30e9f39fe","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Кто, по Аксакову, восставал против государя в послепетровской России?","options":["«бритая борода и немецкий костюм»","«русская борода и крестьянский зипун»","купечество и посадские люди","монастыри и белое духовенство"],"explanation":"Аксаков подчёркивает: восставали дворяне, «восставала бритая борода и немецкий костюм», но никогда не восставала русская борода и зипун.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Восставала бритая борода и немецкий костюм"}]},{"id":"rb67b02d263","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, «куётся из цепей рабства»?","options":["беспощадные ножи бунта","покорность и молчание","новые строгие законы","верность престолу"],"explanation":"Угнетённый народ, по Аксакову, ненадёжен: «рабы сегодня — бунтовщики завтра; из цепей рабства куются беспощадные ножи бунта».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. IX","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"из цепей рабства куются беспощадные ножи бунта"}]},{"id":"r320941e24c","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Что, по Аксакову, представляет собой современное состояние России?","options":["разлад, прикрытый бессовестной ложью","единство, скреплённое верой и царём","застой, вызванный войной и бедностью","смуту, поднятую тайными обществами"],"explanation":"«Современное состояние России представляет внутренний разлад, прикрываемый бессовестною ложью»: правительство и верхние классы отдалились от народа.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. X","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Современное состояние России представляет внутренний разлад, прикрываемый бессовестною ложью"}]},{"id":"r18f914de20","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"От чего, по Аксакову, «главнейшим образом» происходит всё зло в России?","options":["от угнетения правительством свободы мнения","от недостатка просвещения в простом народе","от бедности и частых неурожаев","от вражды сословий между собой"],"explanation":"«Всё зло происходит главнейшим образом от угнетательной системы нашего правительства, угнетательной относительно свободы мнения, свободы нравственной».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XI","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Все зло происходит главнейшим образом от угнетательной системы нашего правительства"}]},{"id":"r37acd50880","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Чего, по Аксакову, иные представители власти не позволяют даже подчинённым?","options":["хвалить распоряжения начальства","жаловаться на взяточников","читать иностранные газеты","собираться в частных домах"],"explanation":"Гнёт мнения, по Аксакову, дошёл до того, что запрещают всякое мнение, даже благоприятное: «Они не позволяют даже хвалить распоряжения начальства».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XI","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Они не позволяют даже хвалить распоряжения начальства"}]},{"id":"r95052216e7","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Почему, по Аксакову, созывать Земский собор в настоящее время бесполезно?","options":["сословия слишком отдалились друг от друга","нет закона о порядке выборов от сословий","его не допустит поместное дворянство","казна не вынесет расходов на выборы"],"explanation":"Собор состоял бы из дворян, купцов, мещан и крестьян, но, по Аксакову, видно, «как далеки они в настоящее время друг от друга, как мало единства между ними».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"как далеки они в настоящее время друг от друга, как мало единства между ними"}]},{"id":"ra405f47ea4","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Чем, по Аксакову, «в настоящую минуту» может быть заменён для правительства Земский собор?","options":["открыто возвещаемым общественным мнением","советом министров при самом государе","губернскими собраниями дворянства","тайными докладами губернских чиновников"],"explanation":"«Открыто возвещаемое общественное мнение — вот чем в настоящую минуту может быть заменён для правительства Земский Собор»; для этого необходима свобода слова.","sources":[{"title":"Аксаков. Дополнение к записке «О внутреннем состоянии России»","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Открыто возвещаемое общественное мнение, -- вот чем в настоящую минуту может быть заменен для правительства Земский Собор"}]},{"id":"r454072a009","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Как Аксаков называет слово, находящееся под тяжким гнётом?","options":["единственный орган земли","оружие правительства","достояние учёных","голос государя"],"explanation":"«В настоящее время слово, этот единственный орган земли, находится под тяжким гнётом», особенно слово письменное и печатное.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"слово, этот единственный орган земли, находится под тяжким гнетом"}]},{"id":"r79fe1d7212","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Зачем, по Аксакову, цензура должна пока остаться?","options":["чтобы охранять личность человека","чтобы оберегать веру от ересей","чтобы защищать власть от критики","чтобы не пускать западные книги"],"explanation":"Аксаков не требует уничтожить цензуру: «Цензура должна остаться, чтоб охранять личность человека», но быть как можно свободнее относительно мысли и мнения.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Цензура должна остаться, чтоб охранять личность человека"}]},{"id":"rc931b1bd86","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Как, по Аксакову, свобода слова связана с неограниченной монархией?","options":["она её верная опора","она её неизбежно подрывает","она с ней несовместима","она возможна лишь при республике"],"explanation":"Аксаков пишет, что «свобода слова неразрывно соединена с неограниченной монархией, есть её верная опора, ручательство за порядок и тишину».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"свобода слова неразрывно соединена с неограниченной монархией, есть ее верная опора"}]},{"id":"rb9b999031f","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Чем, по Аксакову, является страх перед свободой слова?","options":["неверием в истину, своего рода безбожием","разумной осторожностью мудрой власти","заботой о спокойствии простого народа","наследием ордынского ига"],"explanation":"«Этот страх есть неверие в истину, в её победоносную силу, есть безбожие своего рода, ибо Бог есть истина», — пишет Аксаков в «Дополнении».","sources":[{"title":"Аксаков. Дополнение к записке «О внутреннем состоянии России»","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Этот страх есть неверие в истину, в ее победоносную силу, есть безбожие своего рода"}]},{"id":"r7fcd131c17","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Какие «отдельные внутренние язвы» России Аксаков называет, но не разбирает в записке?","options":["раскол, крепостное состояние, взяточничество","пьянство, нищета и невежество крестьян","разбой на дорогах, голод и эпидемии","безверие, роскошь и праздность дворян"],"explanation":"Аксаков упоминает раскол, крепостное состояние и взяточничество, но оговаривается, что предлагать о них свои мысли не было его целью: он говорит об основах внутреннего состояния России.","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. XII","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Таковы раскол, крепостное состояние, взяточничество"}]},{"id":"r2d76f0a70d","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"С кем Аксаков сравнивает Россию, отступившую от основных русских начал?","options":["с ренегатом","с блудным сыном","с больным человеком","с заблудившимся путником"],"explanation":"«Россия в таком точно положении как ренегат: она отступила от основных истинных русских начал», и совет ей один — обратиться к ним вновь.","sources":[{"title":"Аксаков. Дополнение к записке «О внутреннем состоянии России»","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Россия в таком точно положении как ренегат"}]},{"id":"r9119a972ff","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Чьи строки о Петре («он Бог, он Бог твой был, Россия») Аксаков приводит как пример непомерной лести?","options":["Ломоносова","Державина","Сумарокова","Тредиаковского"],"explanation":"Лесть, пришедшая с Запада, по Аксакову, употребляет священные титулы для возвеличения власти: так, Ломоносов в оде говорит о Петре «он Бог, он Бог твой был Россия».","sources":[{"title":"Аксаков. О внутреннем состоянии России, гл. VI","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Ломоносов в одной своей оде говорит о Петре: он Бог, он Бог твой был Россия"}]},{"id":"r5fb44745d7","s":2,"topic":"К. С. Аксаков. «О внутреннем состоянии России»","text":"Каков практический вывод «Дополнения» к записке Аксакова?","options":["свобода слова и Земский собор при нужде","конституция и выборный парламент по-английски","отмена всякой цензуры и созыв Думы","возвращение столицы из Петербурга в Москву"],"explanation":"Итог «Дополнения»: «Полная свобода слова устного, письменного и печатного — всегда и постоянно; и Земский Собор — в тех случаях, когда правительство захочет спросить мнения страны».","sources":[{"title":"Аксаков. Дополнение к записке «О внутреннем состоянии России»","url":"http://az.lib.ru/a/aksakow_k_s/text_1855_zapiska.shtml","quote":"Полная свобода слова устного, письменного и печатного -- всегда и постоянно; и Земский Собор"}]},{"id":"rc98a5c58be","s":2,"topic":"Чаадаев. «Философические письма»","text":"Каким греческим словом («город мёртвых») Чаадаев обозначает Москву в подписи первого «Философического письма»?","options":["Некрополис","Космополис","Метрополис","Акрополис"],"explanation":"Первое письмо подписано «Некрополис, 1829, 1 декабря». Греческое слово значит «город мёртвых»: так Чаадаев называет Москву.","sources":[{"title":"Чаадаев. Философические письма, письмо первое, примечания","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Некрополис – город мертвых (греч.). Так Чаадаев называет здесь Москву"}]},{"id":"r3e29fff1a5","s":2,"topic":"Чаадаев. «Философические письма»","text":"На кого, по Чаадаеву, мы похожи в своих городах?","options":["на кочевников","на пленников","на гостей","на изгнанников"],"explanation":"Чаадаев пишет: «В домах наших мы как будто определены на постой; в семьях мы имеем вид чужестранцев; в городах мы похожи на кочевников, мы хуже кочевников».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"в городах мы похожи на кочевников, мы хуже кочевников"}]},{"id":"r1dc3cff4a5","s":2,"topic":"Чаадаев. «Философические письма»","text":"Как, по Чаадаеву в первом письме, живут русские?","options":["в узком настоящем без прошлого и будущего","одним прошлым, вовсе забыв о будущем","одним будущим, решительно отвергнув прошлое","в вечном ожидании перемен и чудес"],"explanation":"«Мы живём лишь в самом ограниченном настоящем без прошедшего и без будущего, среди плоского застоя». У нас нет ни одного памятника, который живо говорил бы о прошедшем.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Мы живем лишь в самом ограниченном настоящем без прошедшего"}]},{"id":"r3ff321d809","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чем, по Чаадаеву, была наполнена пора, соответствующая «юности» русского народа?","options":["диким варварством и грубым суеверием","великими подвигами и песнями","поэзией, чудесами и святыми","торговлей и строительством городов"],"explanation":"У других народов юность — пора великих побуждений и ярких воспоминаний; у нас, по Чаадаеву, «сначала дикое варварство, затем грубое суеверие, далее иноземное владычество».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Сначала дикое варварство, затем грубое суеверие"}]},{"id":"r7e200a23d8","s":2,"topic":"Чаадаев. «Философические письма»","text":"Кем, по Чаадаеву, мы явились на свет, «без наследства, без связи с людьми»?","options":["незаконнорожденными детьми","блудными сыновьями Европы","круглыми сиротами мира","пасынками всемирной истории"],"explanation":"«Мы же, явившись на свет как незаконнорождённые дети, без наследства, без связи с людьми, предшественниками нашими на земле, не храним в сердцах ничего из поучений».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Мы же, явившись на свет как незаконнорожденные дети, без наследства"}]},{"id":"rd969635ec9","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чьи слова о том, что жизнь человека теряет смысл без памяти о прошлом, приводит Чаадаев в первом письме?","options":["Цицерона","Сенеки","Тацита","Плутарха"],"explanation":"Чаадаев пишет: «В чём заключается жизнь человека, говорит Цицерон, если память о протекших временах не связывает настоящего с прошлым?»","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"В чем заключается жизнь человека, говорит Цицерон"}]},{"id":"r342dfd64b3","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, необходимо каждому из нас сделать с «порванной нитью родства»?","options":["самому пытаться её связать","забыть о ней навсегда","искать её в летописях","ждать, пока её свяжет власть"],"explanation":"Мы не храним в сердцах поучений предшественников, поэтому, по Чаадаеву, «необходимо, чтобы каждый из нас сам пытался связать порванную нить родства».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Необходимо, чтобы каждый из нас сам пытался связать порванную нить родства"}]},{"id":"r334123df50","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, необходимо, чтобы иметь своё лицо, как другие цивилизованные народы?","options":["повторить воспитание рода людского","вернуться к допетровской старине","отказаться от всякого подражания","создать собственную науку и веру"],"explanation":"«Если мы хотим подобно другим цивилизованным народам иметь своё лицо, необходимо как-то вновь повторить у себя всё воспитание человеческого рода».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"необходимо как-то вновь повторить у себя все воспитание человеческого рода"}]},{"id":"r941c5b9df3","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чем, по Чаадаеву, живут народы?","options":["впечатлениями прошлого и общением","верой отцов и подвигами героев","торговлей и военной добычей","законами и мудростью правителей"],"explanation":"«Народы живут только сильными впечатлениями, сохранившимися в их умах от прошедших времён, и общением с другими народами»; так личность ощущает связь с человечеством.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Народы живут только сильными впечатлениями, сохранившимися в их умах от прошедших времен"}]},{"id":"r9b34b6bd35","s":2,"topic":"Чаадаев. «Философические письма»","text":"С кем Чаадаев сравнивает народы, говоря, что их «воспитывают века»?","options":["с отдельными личностями","с растущими деревьями","с текущими реками","с часовыми механизмами"],"explanation":"«Народы — существа нравственные, точно так, как и отдельные личности. Их воспитывают века, как отдельных людей воспитывают годы».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Народы – существа нравственные, точно так, как и отдельные личности"}]},{"id":"re02ffe4594","s":2,"topic":"Чаадаев. «Философические письма»","text":"Для чего, по Чаадаеву, существуют народы, которые «как бы не входят составной частью в род человеческий»?","options":["чтобы преподать миру великий урок","чтобы спасти мир в конце времён","чтобы хранить древнюю веру","чтобы служить мостом между народами"],"explanation":"Мы, по Чаадаеву, принадлежим к тем народам, которые существуют лишь для того, «чтобы преподать великий урок миру».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"а существуют лишь для того, чтобы преподать великий урок миру"}]},{"id":"r0f65781e00","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какое название, по Чаадаеву, ещё сравнительно недавно носила вся Европа?","options":["Христианский мир","Священная империя","Латинский мир","Вселенская республика"],"explanation":"Народы Европы, по Чаадаеву, имеют «общее лицо, семейное сходство»: недавно вся Европа носила название Христианского мира, и это слово значилось в публичном праве.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"вся Европа носила название Христианского мира"}]},{"id":"r2bd672fa2b","s":2,"topic":"Чаадаев. «Философические письма»","text":"На какие ветви, по Чаадаеву, разделяются народы Европы при всём их «семейном сходстве»?","options":["латинскую и тевтонскую","романскую и славянскую","католическую и протестантскую","кельтскую и германскую"],"explanation":"«Несмотря на их разделение на ветви латинскую и тевтонскую, на южан и северян», народы Европы, по Чаадаеву, связаны в одно целое.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Несмотря на их разделение на ветви латинскую и тевтонскую"}]},{"id":"rb1914d0eb9","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, «нам незнакомо», отчего нам не хватает устойчивости и последовательности в уме?","options":["силлогизм Запада","школьная схоластика","римское право","латинская грамматика"],"explanation":"Чаадаев пишет: нам не хватает какой-то логики. «Силлогизм Запада нам незнаком», и в лучших головах есть нечто большее, чем легкомыслие.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"какой-то логики. Силлогизм Запада нам незнаком"}]},{"id":"r70773aaf1a","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, иностранцы ставили русским в заслугу?","options":["своего рода беспечную отвагу","щедрое гостеприимство","набожность и смирение","долготерпение в бедствиях"],"explanation":"Иностранцы, по Чаадаеву, хвалили беспечную отвагу, особенно в низших классах, но не заметили, что то же начало лишает нас глубины и настойчивости.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Иностранцы ставили нам в заслугу своего рода беспечную отвагу"}]},{"id":"r88b3a4b6eb","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, порождает в нас то свойство, которое делает нас безразличными к превратностям жизни?","options":["равнодушие к добру и злу, к истине и лжи","твёрдость и спокойствие духа в испытаниях","смирение и покорность Провидению","жажду подвига и самопожертвования"],"explanation":"Иностранцы не заметили, по Чаадаеву, что это свойство «вызывает в нас также равнодушие к добру и злу, ко всякой истине, ко всякой лжи».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"вызывает в нас также равнодушие к добру и злу, ко всякой истине, ко всякой лжи"}]},{"id":"r61b7b78c5b","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какие два начала духовной природы, по Чаадаеву, Россия должна была бы сочетать, раскинувшись между Востоком и Западом?","options":["воображение и разум","веру и знание","власть и свободу","чувство и волю"],"explanation":"Раскинувшись между Востоком и Западом, мы, по Чаадаеву, «должны бы были сочетать в себе два великих начала духовной природы — воображение и разум». Но эту роль провидение нам не предоставило.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"мы должны бы были сочетать в себе два великих начала духовной природы – воображение и разум"}]},{"id":"r487bf66b05","s":2,"topic":"Чаадаев. «Философические письма»","text":"На какие страны, по образу Чаадаева, Россия опирается «локтями»?","options":["на Китай и Германию","на Индию и Францию","на Персию и Польшу","на Турцию и Швецию"],"explanation":"Россия раскинулась между Востоком и Западом, «опираясь одним локтем на Китай, другим на Германию».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"опираясь одним локтем на Китай, другим на Германию"}]},{"id":"raffbce13dd","s":2,"topic":"Чаадаев. «Философические письма»","text":"Как, по Чаадаеву, провидение отнеслось к судьбе России?","options":["как будто совсем ею не занималось","избрало её для особого служения","наказало её за грехи предков","вело её через испытания к славе"],"explanation":"Провидение, по Чаадаеву, «как будто совсем не занималось нашей судьбой» и предоставило нас всецело самим себе: «Опыт времён для нас не существует».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"оно как будто совсем не занималось нашей судьбой"}]},{"id":"r81c0cba322","s":2,"topic":"Чаадаев. «Философические письма»","text":"Как, по Чаадаеву, протекли для нас века и поколения?","options":["бесплодно","в страданиях","в борьбе","в молитве"],"explanation":"«Опыт времён для нас не существует. Века и поколения протекли для нас бесплодно».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Опыт времен для нас не существует. Века и поколения протекли для нас бесплодно"}]},{"id":"re3be2dc34a","s":2,"topic":"Чаадаев. «Философические письма»","text":"Как Чаадаев завершает мысль «Одинокие в мире, мы миру ничего не дали…»?","options":["«…ничего у мира не взяли»","«…но всё от мира приняли»","«…и мир нам ничего не дал»","«…но сохранили своё»"],"explanation":"Полностью: «Одинокие в мире, мы миру ничего не дали, ничего у мира не взяли, мы не внесли в массу человеческих идей ни одной мысли».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Одинокие в мире, мы миру ничего не дали, ничего у мира не взяли"}]},{"id":"rfca13111bb","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какой, по Чаадаеву, оказывается русская история даже в области всеохватывающей науки?","options":["ни с чем не связанной, ничего не объясняющей","ключом ко всей истории Востока и Азии","прямым продолжением истории Византии","образцом для всех молодых народов Европы"],"explanation":"«Удивительное дело! Даже в области той науки, которая всё охватывает, наша история ни с чем не связана, ничего не объясняет, ничего не доказывает».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"наша история ни с чем не связана, ничего не объясняет, ничего не доказывает"}]},{"id":"r0cb633690b","s":2,"topic":"Чаадаев. «Философические письма»","text":"Благодаря чему, по Чаадаеву, Россия вообще стала бы главой во всемирной истории?","options":["через неё прошли орды варваров на Запад","она приняла христианство от Византии","она остановила монголов у границ Европы","она дала миру великих святых"],"explanation":"Чаадаев пишет: «Если бы орды варваров, потрясших мир, не прошли прежде нашествия на Запад по нашей стране, мы едва были бы главой для всемирной истории».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Если бы орды варваров, потрясших мир, не прошли прежде нашествия на Запад по нашей стране"}]},{"id":"r4924330786","s":2,"topic":"Чаадаев. «Философические письма»","text":"От чего до чего, по Чаадаеву, России «пришлось растянуться», чтобы заставить себя заметить?","options":["от Берингова пролива до Одера","от Белого моря до Чёрного","от Камчатки до Вислы","от Амура до Дуная"],"explanation":"«Чтобы заставить себя заметить, нам пришлось растянуться от Берингова пролива до Одера», — пишет Чаадаев.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"нам пришлось растянуться от Берингова пролива до Одера"}]},{"id":"ra557f09919","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по образу Чаадаева, «кинул» России великий человек, желавший приохотить её к просвещению?","options":["плащ цивилизации","светильник науки","ключ просвещения","книгу законов"],"explanation":"Пётр, по Чаадаеву, «кинул нам плащ цивилизации; мы подняли плащ, но к просвещению не прикоснулись».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"кинул нам плащ цивилизации; мы подняли плащ"}]},{"id":"rcd472fc735","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, русские принесли из победоносного похода по самым просвещённым странам Европы?","options":["одни дурные идеи и гибельные заблуждения","любовь к свободе и жажду новых знаний","новые моды и множество иностранных книг","славу и уважение всей Европы"],"explanation":"Вернувшись из триумфального шествия, «мы принесли с собой одни только дурные идеи и гибельные заблуждения», последствием которых стало неизмеримое бедствие (намёк на восстание 14 декабря).","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"мы принесли с собой одни только дурные идеи и гибельные заблуждения"}]},{"id":"rf2e2420719","s":2,"topic":"Чаадаев. «Философические письма»","text":"На сколько, по Чаадаеву, «неизмеримое бедствие», последовавшее за заграничным походом, отбросило Россию назад?","options":["на полвека","на целый век","на десятилетие","на четверть века"],"explanation":"Дурные идеи, принесённые из Европы, по Чаадаеву, привели к «неизмеримому бедствию, отбросившему нас назад на полвека».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"отбросившее нас назад на полвека"}]},{"id":"r93ad6514f4","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, есть «в крови у нас»?","options":["нечто, отвергающее всякий настоящий прогресс","неутолимая жажда правды и справедливости","тяга к простору и вольной жизни","память о великом прошлом народа"],"explanation":"«В крови у нас есть нечто, отвергающее всякий настоящий прогресс», — пишет Чаадаев в первом письме.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"В крови у нас есть нечто, отвергающее всякий настоящий прогресс"}]},{"id":"r85332f7994","s":2,"topic":"Чаадаев. «Философические письма»","text":"К кому, по Чаадаеву, Россия «по воле роковой судьбы» обратилась за нравственным учением?","options":["к растленной Византии","к латинскому Риму","к болгарским книжникам","к варягам-христианам"],"explanation":"«Мы обратились за нравственным учением, которое должно было нас воспитать, к растленной Византии, к предмету глубокого презрения этих народов».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"мы обратились за нравственным учением, которое должно было нас воспитать, к растленной Византии"}]},{"id":"r261e385a6b","s":2,"topic":"Чаадаев. «Философические письма»","text":"Кто, по Чаадаеву, незадолго до Крещения Руси «похитил у вселенского братства» Византию?","options":["«один честолюбивый ум»","«один властолюбивый император»","«один гордый собор епископов»","«одна партия ересиархов»"],"explanation":"Чаадаев пишет, что «эту семью похитил у вселенского братства один честолюбивый ум» (имеется в виду патриарх Фотий), и мы восприняли идею в искажённом виде.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"эту семью похитил у вселенского братства один честолюбивый ум"}]},{"id":"r6acfa47f99","s":2,"topic":"Чаадаев. «Философические письма»","text":"Каким началом, по Чаадаеву, тогда было одушевлено всё в Европе?","options":["животворным началом единства","началом свободы личности","началом разума и науки","началом права и закона"],"explanation":"«В Европе всё тогда было одушевлено животворным началом единства»: всё умственное движение стремилось установить единство человеческой мысли. Мы же были чужды этому началу.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"В Европе все тогда было одушевлено животворным началом единства"}]},{"id":"r4598d00942","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чему, по Чаадаеву, подпала Россия после освобождения от чужеземного ига?","options":["рабству, ещё более тяжкому","власти польских королей","влиянию шведских купцов","смуте и безначалию"],"explanation":"Освободившись от чужеземного ига, мы, по Чаадаеву, оказались отторгнуты от общей семьи и «подпали рабству, ещё более тяжкому», освящённому самим фактом нашего освобождения.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"мы подпали рабству, еще более тяжкому, и притом освященному"}]},{"id":"re2c5b30be9","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, упускают из виду те, кто «ничего не понимает в христианстве»?","options":["его чисто историческую сторону","его мистическую, созерцательную сторону","его обрядовую, богослужебную сторону","его аскетическую сторону"],"explanation":"«Ничего не понимают в христианстве те, которые не замечают в его чисто исторической стороне» существенной части его учения.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Ничего не понимают в христианстве те, которые не замечают в его чисто исторической стороне"}]},{"id":"r849f564f29","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какие две функции, по Чаадаеву, различимы в христианстве?","options":["действие на индивидуальное и на общее сознание","просвещение разума и смирение своевольной воли","служение Богу и служение каждому ближнему","проповедь народам и спасение отдельных душ"],"explanation":"«Христианство обладает двумя легко различимыми функциями. Во-первых, действием на индивидуальное, во-вторых, действием на общее сознание».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Во-первых, действием на индивидуальное, во-вторых, действием на общее сознание"}]},{"id":"r58a8e5484d","s":2,"topic":"Чаадаев. «Философические письма»","text":"На какой почве, по Чаадаеву, происходит вся история нового общества?","options":["на почве убеждений","на почве интересов","на почве завоеваний","на почве торговли"],"explanation":"«Вся история нового общества происходит на почве убеждений. Значит, это настоящее воспитание».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Вся история нового общества происходит на почве убеждений"}]},{"id":"r476b09d4f8","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какого поэта Чаадаев советует прочесть, чтобы увидеть все народы Европы «у подножия стен Иерусалима»?","options":["Тассо","Данте","Ариосто","Петрарку"],"explanation":"Чтобы понять единство европейских народов, по Чаадаеву, «читайте только Тасса»: в «Освобождённом Иерусалиме» все народы распростёрты у стен святого города.","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"и вы увидите все народы распростертыми у подножия стен Иерусалима"}]},{"id":"r9861cc9208","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, «в известном смысле» действительно осуществлено в европейском обществе, несмотря на всё порочное в нём?","options":["царство Божие","вечный мир","общее благоденствие","свобода совести"],"explanation":"Невзирая на всё незаконченное и порочное в европейском обществе, по Чаадаеву, «всё же царство Божие в известном смысле в нём действительно осуществлено».","sources":[{"title":"Чаадаев. Философические письма, письмо первое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"все же царство Божие в известном смысле в нем действительно"}]},{"id":"r135693d276","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву во втором письме, составляет «атмосферу», окружающую его собеседницу?","options":["рабы, которые ей прислуживают","книги, которые она читает","гости, которые к ней приходят","молитвы, которые она творит"],"explanation":"Чаадаев пишет: «Эти рабы, которые вам прислуживают, разве не они составляют окружающую вас атмосферу?» — и называет крепостное право ужасной язвой.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Эти рабы, которые вам прислуживают, разве не они составляют окружающую вас атмосферу?"}]},{"id":"re600fb4dd3","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, «придётся себе всё создавать» человеку, живущему верой среди равнодушной толпы?","options":["всё, вплоть до воздуха для дыхания","лишь круг друзей-единомышленников","лишь домашнюю церковь и библиотеку","лишь распорядок дня и чтения"],"explanation":"«Вам придётся себе всё создавать, сударыня, вплоть до воздуха для дыхания, вплоть до почвы под ногами». И это, по Чаадаеву, буквально так.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Вам придется себе все создавать, сударыня, вплоть до воздуха для дыхания"}]},{"id":"r5a90c2ace0","s":2,"topic":"Чаадаев. «Философические письма»","text":"В чём, по Чаадаеву, может заставить усомниться то, что русский народ в лоне христианства отрёкся от свободы?","options":["в православии, которым мы кичимся","в самой христианской вере","в мудрости русских государей","в возможности всякого прогресса"],"explanation":"Откуда у нас это «обратное действие религии»? «Одно это могло бы заставить усомниться в православии, которым мы кичимся», — пишет Чаадаев.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"одно это могло бы заставить усомниться в православии, которым мы кичимся"}]},{"id":"rf123720e88","s":2,"topic":"Чаадаев. «Философические письма»","text":"В чём, по Чаадаеву, упрёк Русской Церкви, высказанный во втором письме?","options":["она не возвысила голос против насилия","она не просветила народ грамотой","она подчинилась власти патриарха","она приняла обряды от греков"],"explanation":"Чаадаев спрашивает, почему Церковь «не возвысила материнского голоса против этого отвратительного насилия одной части народа над другой», то есть против крепостного права.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"почему она не возвысила материнского голоса против этого отвратительного насилия"}]},{"id":"r3609a9de32","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чему, по Чаадаеву, Европа обязана уничтожением крепостничества?","options":["христианству","Просвещению","революции","римскому праву"],"explanation":"По признанию даже упорных скептиков, пишет Чаадаев, «уничтожением крепостничества в Европе мы обязаны христианству».","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"уничтожением крепостничества в Европе мы обязаны"}]},{"id":"r5ce698ab25","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какого мыслителя Чаадаев приводит как утверждавшего, что одни люди родятся свободными, а другие — для оков?","options":["Аристотеля","Платона","Цицерона","Сенеку"],"explanation":"Ни один философ древности не мыслил общества без рабов: Аристотель, «признанный представитель всей той мудрости, какая только была в мире до пришествия Христа», считал, что одни рождаются для свободы, другие для оков.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Аристотель, признанный представитель всей той мудрости, какая только была в мире до пришествия Христа"}]},{"id":"r880da42f51","s":2,"topic":"Чаадаев. «Философические письма»","text":"Кого Чаадаев называет «самым идеальным, самым выспренным из мудрецов древнего мира»?","options":["Платона","Пифагора","Сократа","Плотина"],"explanation":"Чаадаев напоминает собеседнице, что она читала Платона, и обращает внимание, как заботливо этот мудрец окружает своих героев обстановкой, располагающей к размышлению.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Вспомните, как заботливо самый идеальный, самый выспренный из мудрецов древнего мира"}]},{"id":"r7f150a59dd","s":2,"topic":"Чаадаев. «Философические письма»","text":"Кого из древних Чаадаев «в особенности» выделяет среди избранников, узревших «неизречённое сияние» правды?","options":["Платона","Пифагора","Зороастра","Сократа"],"explanation":"«Так Пифагор, Сократ, Зороастр и в особенности Платон узрели неизречённое сияние», — пишет Чаадаев о прозрениях древних до христианства.","sources":[{"title":"Чаадаев. Философические письма, письмо второе","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Так Пифагор, Сократ, Зороастр и в особенности Платон узрели неизреченное сияние"}]},{"id":"r400379061b","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какие латинские слова служат эпиграфом к третьему «Философическому письму»?","options":["«Absorpta est mors ad victoriam»","«Credo quia absurdum est»","«Ex oriente lux et veritas»","«Memento mori, memento vivere»"],"explanation":"Эпиграф третьего письма — слова апостола Павла «Поглощена смерть победою» в латинском переводе.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Absorpta est mors ad victoriam"}]},{"id":"raea6f88f8a","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чьё изречение о том, что повиноваться — «прямая обязанность разумной души», Чаадаев приводит, называя его автора скептиком?","options":["Монтеня","Паскаля","Декарта","Вольтера"],"explanation":"Чаадаев цитирует по-французски Монтеня и замечает, что тот «не считается умом, склонным к вере», — тем полезнее завербовать союзника «из вражьего стана».","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Монтень сказал: L'obéir est le propre office"}]},{"id":"r3bd77a1291","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какой разум, по Чаадаеву, только и существует?","options":["подчинённый","свободный","самозаконный","творческий"],"explanation":"«Прежде всего, нет иного разума, кроме разума подчинённого»: человек всю жизнь только и ищет, чему бы подчиниться.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Прежде всего, нет иного разума, кроме разума подчиненного"}]},{"id":"r51148461cf","s":2,"topic":"Чаадаев. «Философические письма»","text":"Почему, по Чаадаеву, разум достигает наибольшей мощи в математических исчислениях?","options":["ум здесь в полном подчинении правилу","математика опирается на опыт и наблюдение","в ней нет места чувству и воображению","она самая древняя из всех наук"],"explanation":"Исчисление, по Чаадаеву, — «механическая работа ума»: чудодейственная мощь анализа объясняется тем, что «ум здесь действует в полном подчинении данному правилу».","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Дело в том, что ум здесь действует в полном подчинении данному правилу"}]},{"id":"r28d18d2e71","s":2,"topic":"Чаадаев. «Философические письма»","text":"Чьи слова о «едином пути», открытом человеку для владычества над природой, приводит Чаадаев?","options":["Бэкона","Декарта","Ньютона","Локка"],"explanation":"Чаадаев цитирует Бэкона: единый путь к владычеству над природой — повиновение её законам. Это подтверждает его мысль о подчинённости разума.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Единый путь, говорит Бэкон, отверстый человеку для владычества"}]},{"id":"r2db7532c2f","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, есть логический анализ?","options":["насилие разума над самим собой","естественный и лёгкий путь разума","высшая ступень всякого познания","плод чистого созерцания"],"explanation":"«Что такое логический анализ, как не насилие разума над самим собою?» Аналитическим путём мы идём лишь с чрезвычайным усилием над собой.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Что такое логический анализ, как не насилие разума над самим собою?"}]},{"id":"re8baae2e76","s":2,"topic":"Чаадаев. «Философические письма»","text":"Каким путём, по Чаадаеву, разум действовал бы, если «дать ему волю»?","options":["одним синтезом","одним анализом","одним опытом","одной интуицией"],"explanation":"«Дайте разуму волю, и он будет действовать одним синтезом»: с синтеза человеческий разум и начал.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Дайте разуму волю, и он будет действовать одним синтезом"}]},{"id":"r770313ab48","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, является пределами человеческой жизни, какова она ныне?","options":["время и пространство","рождение и смерть","тело и душа","природа и общество"],"explanation":"«Время и пространство — вот пределы человеческой жизни, какова она ныне». Но мысль, по Чаадаеву, способна вырваться из их объятий.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Время и пространство – вот пределы человеческой жизни"}]},{"id":"r7f1e9c4170","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что такое воспоминание, по Чаадаеву?","options":["действие воли","след впечатления","игра воображения","голос совести"],"explanation":"Идею времени мы черпаем из памяти, а воспоминание, по Чаадаеву, «не что иное, как действие воли»: мы помним лишь то, что хотели запомнить.","sources":[{"title":"Чаадаев. Философические письма, письмо третье","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Не что иное, как действие воли"}]},{"id":"r9877f1eaea","s":2,"topic":"Чаадаев. «Философические письма»","text":"Как в эпиграфе к четвёртому письму определяется воля?","options":["как род мышления","как слепое влечение","как свободное начало","как сила тела"],"explanation":"Эпиграф гласит: «Воля есть не что иное, как род мышления» и потому должна рассматриваться «не как начало свободное, а как начало обусловленное».","sources":[{"title":"Чаадаев. Философические письма, письмо четвёртое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Воля есть не что иное, как род мышления"}]},{"id":"r2b10261cdb","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какой пример Чаадаев приводит в подтверждение того, что он свободен?","options":["он властен не писать строк, которые пишет","он может мысленно изменить своё прошлое","он способен долго жить без пищи и сна","он может не верить в провидение"],"explanation":"«Да, я свободен… Пока я пишу эти строки, разве я не знаю, что я властен их не писать?» Но со свободой связана и страшная идея — злоупотребление ею.","sources":[{"title":"Чаадаев. Философические письма, письмо четвёртое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Пока я пишу эти строки, разве я не знаю, что я властен их не писать?"}]},{"id":"ra3fbf5c3c4","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какое из трёх открытий, давших толчок положительным наукам, Чаадаев связывает с Ньютоном?","options":["небесную геометрию","анализ","наблюдение","опыт"],"explanation":"По Чаадаеву, три открытия вознесли науки: «анализ — создание Декарта, наблюдение — создание Бэкона и небесная геометрия — создание Ньютона».","sources":[{"title":"Чаадаев. Философические письма, письмо четвёртое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"и небесная геометрия – создание Ньютона"}]},{"id":"r0e740e9ce3","s":2,"topic":"Чаадаев. «Философические письма»","text":"В чём, по Чаадаеву, неизбежно заключена всякая философия?","options":["в роковом круге без исхода","в границах чувственного опыта","в оковах человеческого языка","в рамках своей эпохи"],"explanation":"«Всякая философия… неизбежно заключена в некий роковой круг без исхода»: в нравственности она сама даёт себе закон, в метафизике сама устанавливает начало.","sources":[{"title":"Чаадаев. Философические письма, письмо пятое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Всякая философия, приходится сказать это, неизбежно заключена в некий роковой круг без исхода"}]},{"id":"r93bef5a63c","s":2,"topic":"Чаадаев. «Философические письма»","text":"Как, по Чаадаеву, философия поступает в области нравственности?","options":["сама даёт себе закон и затем ему подчиняется","принимает закон из Откровения и толкует его","выводит закон из опыта всех народов","отвергает всякий закон как предрассудок"],"explanation":"В области нравственности философия, по Чаадаеву, «сначала предписывает сама себе закон, а затем начинает ему подчиняться, неизвестно, ни как, ни почему».","sources":[{"title":"Чаадаев. Философические письма, письмо пятое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"она сначала предписывает сама себе закон, а затем начинает ему подчиняться"}]},{"id":"rec8b9783be","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, является главным средством формирования душ?","options":["слово","пример","страдание","молитва"],"explanation":"«Главным средством формирования душ без сомнения является слово»: без него нельзя представить ни происхождения сознания в личности, ни его развития в человеческом роде.","sources":[{"title":"Чаадаев. Философические письма, письмо пятое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Главным средством формирования душ без сомнения является слово"}]},{"id":"r3fc81bb89d","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, мы найдём в сокровенных глубинах своего сердца?","options":["мысль, унаследованную от предков","врождённые идеи чистого разума","образ Бога, не тронутый грехом","своё неповторимое личное Я"],"explanation":"«Как бы ни замыкаться в себе… мы никогда там ничего не найдём, кроме мысли, унаследованной от наших предшественников на земле».","sources":[{"title":"Чаадаев. Философические письма, письмо пятое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"мы никогда там ничего не найдем, кроме мысли унаследованной от наших предшественников"}]},{"id":"r4d6b253c02","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какая истина, по Чаадаеву, есть в человеческом духе?","options":["лишь вложенная в него Богом","добытая опытом поколений","рождённая собственным разумом","унаследованная от природы"],"explanation":"Основная идея писем, по Чаадаеву: «в человеческом духе нет истины помимо собственноручно вложенной в неё Богом, когда он извлёк человека из небытия».","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"что в человеческом духе нет истины помимо собственноручно вложенной в нее Богом"}]},{"id":"ra063027697","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какую форму, по Чаадаеву, современный разум стремится придать всякому знанию?","options":["историческую","математическую","поэтическую","опытную"],"explanation":"«Современное направление человеческого разума явно стремится облечь всякое знание в историческую форму», и историческая мысль призвана подняться на новую высоту.","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"явно стремится облечь всякое знание в историческую форму"}]},{"id":"r3599cdab88","s":2,"topic":"Чаадаев. «Философические письма»","text":"Что, по Чаадаеву, Сократ «завещал людям» в отличие от Моисея, открывшего им истинного Бога?","options":["малодушное и беспокойное сомнение","стремление к познанию самого себя","твёрдую веру в бессмертие души","искусство спора и диалога"],"explanation":"При верном понимании истории, по Чаадаеву, станет ясно, что Моисей «открыл людям истинного Бога, а последний завещал им малодушное и беспокойное сомнение».","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"а последний завещал им малодушное и беспокойное сомнение"}]},{"id":"r0653595286","s":2,"topic":"Чаадаев. «Философические письма»","text":"Кого Чаадаев противопоставляет Давиду как «любопытный пример искусственного величия, пышной и хвастливой добродетели»?","options":["Марка Аврелия","Катона","Сенеку","Цицерона"],"explanation":"«На примере Давида и Марка Аврелия станет очевидным», что первый был образцом святого героизма, а второй — лишь искусственного величия.","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"На примере Давида и Марка Аврелия станет очевидным"}]},{"id":"rd51cb7b532","s":2,"topic":"Чаадаев. «Философические письма»","text":"О ком из римлян Чаадаев пишет, что тот «в ярости растерзал свои внутренности»?","options":["о Катоне","о Бруте","о Сенеке","о Лукреции"],"explanation":"Чаадаев пишет, что про Катона, «в ярости растерзавшего свои внутренности», будут вспоминать, чтобы оценить философию, внушавшую столь неистовую добродетель.","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Точно так же про Катона, в ярости растерзавшего свои внутренности"}]},{"id":"rc919da8931","s":2,"topic":"Чаадаев. «Философические письма»","text":"Кого из языческих мудрецов Чаадаев считает освобождённым от «порочащего его предвзятого мнения»?","options":["Эпикура","Диогена","Сократа","Пиррона"],"explanation":"«Я думаю, что среди славных языческих имён Эпикур освобождён от порочащего его предвзятого мнения», — пишет Чаадаев, переоценивая героев древности.","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Я думаю, что среди славных языческих имен Эпикур освобожден от порочащего его предвзятого мнения"}]},{"id":"r29eca9ff16","s":2,"topic":"Чаадаев. «Философические письма»","text":"С чьим великим именем, по Чаадаеву, будет связано «своего рода бесчестие»?","options":["Гомера","Платона","Вергилия","Аристотеля"],"explanation":"«И, наконец, — сказать ли это? Своего рода бесчестие будет связано с великим именем Гомера»: по Чаадаеву, Гомер воспевал земные страсти.","sources":[{"title":"Чаадаев. Философические письма, письмо шестое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"Своего рода бесчестие будет связано с великим именем Гомера"}]},{"id":"r85eed8b99d","s":2,"topic":"Чаадаев. «Философические письма»","text":"Какую заслугу Чаадаев признаёт за религией Магомета?","options":["распространение идеи единого Бога","сохранение античной науки и философии","создание великого искусства","соединение Востока и Запада"],"explanation":"Религия Магомета, по Чаадаеву, содействовала уничтожению многобожия и распространила на огромных пространствах «идею единого Бога и всемирного верования».","sources":[{"title":"Чаадаев. Философические письма, письмо седьмое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"идею единого Бога и всемирного верования"}]},{"id":"r78e373c43f","s":2,"topic":"Чаадаев. «Философические письма»","text":"К чему, по Чаадаеву в восьмом письме, «пришло время» обратиться?","options":["к простому языку разума","к слепой вере сердца","к молчанию и молитве","к опыту простого народа"],"explanation":"«Да, сударыня, пришло время говорить простым языком разума. Нельзя уже более ограничиваться слепой верой, упованием сердца».","sources":[{"title":"Чаадаев. Философические письма, письмо восьмое","url":"http://www.vehi.net/chaadaev/filpisma.html","quote":"пришло время говорить простым языком разума"}]},{"id":"rb1ec3d096e","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"О чём Гоголь просит в первом пункте своего завещания, открывающего «Выбранные места»?","options":["не погребать тело до явных признаков разложения","похоронить его в Святой Земле у Гроба Господня","отпевать его без всякого торжества и речей","раздать всё его имущество бедным студентам"],"explanation":"Первый пункт: «Завещаю тела моего не погребать до тех пор, пока не покажутся явные признаки разложения», ибо во время болезни на Гоголя находили минуты оцепенения.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Завещание»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Завещаю тела моего не погребать до тех пор, пока не покажутся явные признаки разложения"}]},{"id":"re4bc767464","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь в завещании называет мысль о памятнике над своей могилой?","options":["пустяком, христианина недостойным","данью славе русской словесности","делом, угодным друзьям и читателям","гордостью, простительной писателю"],"explanation":"Гоголь завещает не ставить над ним никакого памятника и «не помышлять о таком пустяке, христианина недостойном»; друг воздвигнет ему памятник в самом себе.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Завещание»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Завещаю не ставить надо мною никакого памятника и не помышлять о таком пустяке, христианина недостойном"}]},{"id":"r151a65bb91","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что, по Гоголю, сказал Пушкин о словах и делах поэта, возражая Державину?","options":["«слова поэта суть уже его дела»","«дело поэта — его стихи, а не поступки»","«поэта судят по делам, а не по словам»","«у поэта нет дел, кроме слова»"],"explanation":"Пушкин, прочитав строки Державина «За слова меня пусть гложет, за дела сатирик чтит», сказал: «Державин не совсем прав: слова поэта суть уже его дела». Гоголь соглашается с Пушкиным.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О том, что такое слово»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Державин не совсем прав: слова поэта суть уже его дела"}]},{"id":"r4ef0c2671f","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Чем, по Гоголю, является слово?","options":["высшим подарком Бога человеку","орудием власти над людьми","украшением образованной жизни","изобретением человеческого ума"],"explanation":"«Обращаться с словом нужно честно. Оно есть высший подарок Бога человеку», — пишет Гоголь в главе «О том, что такое слово».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О том, что такое слово»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Обращаться с словом нужно честно. Оно есть высший подарок Бога человеку"}]},{"id":"rd4e2570fcb","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Кто, по Гоголю, произвёл больше зла, чем сами безбожники?","options":["лицемерные и неприготовленные проповедники","равнодушные к вере образованные люди","переводчики западных философских книг","светские писатели и журналисты"],"explanation":"«Не столько зла произвели сами безбожники, сколько произвели зла лицемерные или даже просто неприготовленные проповедатели Бога, дерзавшие произносить имя Его неосвящёнными устами».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О том, что такое слово»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Не столько зла произвели сами безбожники, сколько произвели зла лицемерные"}]},{"id":"r722b047034","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь оценивает «Одиссею» в главе о переводе Жуковского?","options":["совершеннейшее произведение всех веков","лучшее создание греческой трагедии","образец языческой мудрости древних","детская сказка древнего мира"],"explanation":"«Появление „Одиссеи“ произведёт эпоху. „Одиссея“ есть решительно совершеннейшее произведение всех веков», — пишет Гоголь о переводе Жуковского.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Об Одиссее, переводимой Жуковским»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Одиссея есть решительно совершеннейшее произведение всех веков"}]},{"id":"r1faaca9e80","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Чем, по Гоголю, является «Илиада» перед «Одиссеей»?","options":["эпизодом","вступлением","подражанием","образцом"],"explanation":"Гоголь пишет об «Одиссее»: «Объём её велик; „Илиада“ пред нею эпизод», ведь «Одиссея» захватывает весь древний мир.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Об Одиссее, переводимой Жуковским»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Объем ее велик; Илиада пред нею эпизод"}]},{"id":"r4ed9401e38","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"На что, по Гоголю, может значительно подействовать «Одиссея» в русской одежде Жуковского?","options":["на очищение русского языка","на развитие русского театра","на смягчение нравов дворянства","на изучение древних языков"],"explanation":"«„Одиссея“ своей русской одеждой, в которую облёк её Жуковский, может подействовать значительно на очищение языка», — пишет Гоголь.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Об Одиссее, переводимой Жуковским»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"может подействовать значительно на очищение языка"}]},{"id":"r36ee6802b8","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"К чему, по Гоголю, «Одиссея» возвратит современного человека, уставшего от беспорядка жизни?","options":["к простоте","к вере отцов","к природе","к героизму"],"explanation":"Гоголь предрекает Жуковскому: его «Одиссея» «возвратит к свежести современного человека» и «возвратит его к простоте».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Просвещение»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"она возвратит его к простоте"}]},{"id":"ra7447d04fa","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Кем, по предсказанию Гоголя, Жуковский будет в Москве?","options":["патриархом","наставником","отшельником","изгнанником"],"explanation":"В письме к Жуковскому Гоголь пишет: Москва станет для него желанной пристанью, «как патриарх ты будешь в Москве», и юноши будут ловить его слова.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Просвещение»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Как патриарх ты будешь в Москве"}]},{"id":"r70fddd26ea","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что Гоголь говорит о слове «просвещение»?","options":["его нет ни в одном языке, кроме нашего","оно пришло к нам из французского языка","оно означает лишь обучение наукам","оно устарело и должно быть забыто"],"explanation":"«Слова этого нет ни на каком языке, оно только у нас. Просветить не значит научить, или наставить, или образовать», а осветить человека насквозь.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Просвещение»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Слова этого нет ни на каком языке, оно только у нас"}]},{"id":"r95606544a3","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"С кем, по Гоголю, Церковь сравнима в том, что она одна от апостольских времён сохранилась в непорочной чистоте?","options":["с целомудренной девой","с неприступной крепостью","с неугасимым светильником","с нетленными мощами"],"explanation":"Гоголь пишет о Церкви, «которая, как целомудренная дева, сохранилась одна только от времён апостольских в непорочной первоначальной чистоте».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Несколько слов о нашей Церкви и духовенстве»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Эта Церковь, которая, как целомудренная дева, сохранилась одна"}]},{"id":"r97a22629f3","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Каким сравнением Гоголь показывает, что нам неведома наша Церковь?","options":["хозяин не знает, где лежит лучшая вещь в доме","сын не помнит лица родной матери","путник не видит света, стоя под ним","наследник не читал отцовского завещания"],"explanation":"«У хозяина спрашивают показать лучшую вещь в его доме, и сам хозяин не знает, где лежит она»: так, по Гоголю, мы знаем нашу Церковь.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Несколько слов о нашей Церкви и духовенстве»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"У хозяина спрашивают показать лучшую вещь в его доме, и сам хозяин не знает"}]},{"id":"red7dd1147f","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Где, по Гоголю, должна святиться наша Церковь?","options":["в нас, а не в словах наших","в храмах, а не в книгах","в обряде, а не в проповеди","в монастырях, а не в мире"],"explanation":"Защиты духовенства, по Гоголю, не убедят западных католиков: «Церковь наша должна святиться в нас, а не в словах наших».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Несколько слов о нашей Церкви и духовенстве»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Церковь наша должна святиться в нас, а не в словах наших"}]},{"id":"re6c97b9502","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Где, по Гоголю, готовятся «неопровержимые» защиты Церкви?","options":["в глубине монастырей и в тишине келий","в духовных академиях и семинариях","в журналах и печатных брошюрах","на соборах епископов в столице"],"explanation":"Духовенство, по Гоголю, не бездействует: «в глубине монастырей и в тишине келий готовятся неопровержимые» сочинения в защиту Церкви — в спокойствии и молитве.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Несколько слов о нашей Церкви и духовенстве»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"в глубине монастырей и в тишине келий готовятся неопровержимые"}]},{"id":"r299cec6bab","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"В чьи ряды, по Гоголю, не следует становиться нашему духовенству, «отличавшемуся величавым спокойствием»?","options":["в ряды европейских крикунов","в ряды светских проповедников","в ряды учёных богословов","в ряды придворных сановников"],"explanation":"Гоголь спрашивает: зачем хотите, чтобы духовенство «стало в ряды европейских крикунов и начало, подобно им, печатать опрометчивые брошюры?»","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Несколько слов о нашей Церкви и духовенстве»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"стало в ряды европейских крикунов и начало, подобно им, печатать опрометчивые брошюры"}]},{"id":"r7382975c49","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь оценивает мнение, будто власть Церкви у нас слаба из-за недостатка светскости у духовенства?","options":["как нелепость","как горькую правду","как полезный упрёк","как мнение раскольников"],"explanation":"Замечание, будто власть Церкви слаба оттого, что духовенство мало имеет «светскости и ловкости обращенья», Гоголь называет «такою нелепостью».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О том же»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"мало имеет светскости и ловкости обращенья в обществе, есть такая нелепость"}]},{"id":"ra07ef9e963","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"С каким верховным источником лиризма, по Гоголю, соприкасались русские поэты, видя всякий высокий предмет?","options":["с Богом","с природой","с народом","с любовью"],"explanation":"Наши поэты, по Гоголю, видели всякий высокий предмет «в его законном соприкосновенье с верховным источником лиризма — Богом», одни сознательно, другие бессознательно.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О лиризме наших поэтов»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"в его законном соприкосновенье с верховным источником лиризма -- Богом"}]},{"id":"r08781e8ce4","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Какой первый из двух предметов, по Гоголю, вызывал у русских поэтов лиризм, «близкий к библейскому»?","options":["Россия","природа","смерть","любовь"],"explanation":"Гоголь пишет: «Первый из них — Россия. При одном этом имени как-то вдруг просветляется взгляд у нашего поэта», и это больше, чем обыкновенная любовь к отечеству.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О лиризме наших поэтов»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"лиризм, близкий к библейскому. Первый из них -- Россия"}]},{"id":"r42bf650716","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Каким Гоголь считает христианина, сколько бы лет ему ни было?","options":["вечным учеником до самого гроба","зрелым наставником других людей","воином, уже выигравшим битву","странником, нашедшим свой дом"],"explanation":"«Для христианина нет оконченного курса; он вечно ученик и до самого гроба ученик», — пишет Гоголь в главе «Христианин идёт вперёд».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Христианин идёт вперёд»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Для христианина нет оконченного курса; он вечно ученик и до самого гроба ученик"}]},{"id":"r089e17d140","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Чьё похвальное слово Карамзину Гоголь называет лучшим из сочинений его автора?","options":["Погодина","Шевырёва","Жуковского","Вяземского"],"explanation":"Гоголь пишет, что с удовольствием прочёл «похвальное слово Карамзину, написанное Погодиным»: это лучшее из сочинений Погодина по благопристойности.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Карамзин»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"похвальное слово Карамзину, написанное Погодиным"}]},{"id":"r89e94c92a7","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что, по Гоголю, Карамзин первым показал русским литераторам?","options":["что писатель может быть у нас независим","что история может быть увлекательной","что русский язык годится для прозы","что литература может кормить автора"],"explanation":"«Карамзин первый показал, что писатель может быть у нас независим и почтён всеми равно, как именитейший гражданин в государстве».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Карамзин»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Карамзин первый показал, что писатель может быть у нас независим"}]},{"id":"rba7fb27940","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь говорит о том, что Карамзин «весь исполнил долг»?","options":["на пять талантов принёс другие пять","посадил дерево и вырастил целый сад","построил свой дом на камне","не зарыл в землю ни одной монеты"],"explanation":"О Карамзине Гоголь пишет: он «ничего не зарыл в землю и на данные ему пять талантов истинно принёс другие пять» — образ из евангельской притчи о талантах.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Карамзин»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"на данные ему пять талантов истинно принес другие пять"}]},{"id":"r2b3d1ee877","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Каким человеком, по Гоголю, был Пушкин в отношении всего великого в человеке?","options":["знатоком и верным оценщиком","суровым судьёй и обличителем","равнодушным наблюдателем","восторженным подражателем"],"explanation":"Гоголь пишет: «Пушкин был знаток и оценщик верный всего великого в человеке», и приводит его стихи о прощении.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О театре, об одностороннем взгляде на театр»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Пушкин был знаток и оценщик верный всего великого в человеке"}]},{"id":"rc7f95c8855","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что, по Гоголю, «некоторые стали печатно объявлять» о Пушкине?","options":["что он был деист, а не христианин","что он был атеист и вольтерьянец","что он втайне принял католичество","что он был масоном и мистиком"],"explanation":"Гоголь возмущается теми, кто стал «печатно объявлять, что Пушкин был деист, а не христианин; точно как будто бы они побывали в душе Пушкина».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О театре, об одностороннем взгляде на театр»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Некоторые стали печатно объявлять, что Пушкин был деист, а не христианин"}]},{"id":"r62507f487c","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Каким, по Гоголю, был Пушкин в обращении со словами?","options":["скупым, как никто из наших поэтов","щедрым до полной расточительности","небрежным, но вдохновенным","витиеватым и пышным, как Державин"],"explanation":"«Никто из наших поэтов не был ещё так скуп на слова и выраженья, как Пушкин», боявшийся сказать неумеренное и лишнее.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «В чём же наконец существо русской поэзии»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Никто из наших поэтов не был еще так скуп на слова и выраженья, как Пушкин"}]},{"id":"rb122bb5647","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Какой пословицей Гоголь описывает охотников действовать сгоряча, уничтожая полезное?","options":["«Рассердясь на вши, да шубу в печь»","«Лес рубят — щепки летят»","«Заставь дурака Богу молиться»","«Не в свои сани не садись»"],"explanation":"Много предметов страдает от извращения их смысла, а охотники действовать сгоряча поступают, «по пословице: „Рассердясь на вши, да шубу в печь“».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О театре, об одностороннем взгляде на театр»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"по пословице: Рассердясь на вши, да шубу в печь"}]},{"id":"r48176e5077","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь отзывается о первом томе «Мёртвых душ» в «Четырёх письмах…»?","options":["выкроен недурно, но сшит белыми нитками","задуман слабо, но написан блестяще","верен жизни, но лишён всякой мысли","совершенен и не требует поправок"],"explanation":"Гоголь признаёт: не следовало выдавать сочинение, которое «хотя выкроено было недурно, но сшито кое-как белыми нитками», как платье для примерки.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Четыре письма к разным лицам по поводу „Мёртвых душ“»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"хотя выкроено было недурно, но сшито кое-как белыми нитками"}]},{"id":"r42267e8bd6","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Зачем, по Гоголю, писателю иногда «нужно иметь противу себя озлобленных»?","options":["они выкопают и покажут все недостатки","они сделают книге громкую славу","они закалят характер писателя","они привлекут к книге власть"],"explanation":"Кто увлечён красотами, прощает всё, а озлобленный «постарается выкопать в нас всю дрянь» и выставит её так ярко, что её увидишь.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Четыре письма к разным лицам по поводу „Мёртвых душ“»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Иногда нужно иметь противу себя озлобленных"}]},{"id":"r5453dc1d91","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Без чего, по Гоголю, «никому не спастись»?","options":["без любви к Богу","без знания Писания","без монастырской жизни","без таинства покаяния"],"explanation":"Глава «Нужно любить Россию» начинается так: «Без любви к Богу никому не спастись; а любви к Богу у вас нет».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Нужно любить Россию»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Без любви к Богу никому не спастись"}]},{"id":"ra35bf02464","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Кто, по Гоголю, идёт в монастырь?","options":["лишь те, кого позвал туда Сам Бог","все, кто разочаровался в мире","те, кто ищет любви к Богу","те, кто кается в тяжких грехах"],"explanation":"Любви к Богу, пишет Гоголь, в монастыре не найти: «в монастырь идут одни, которых уже позвал туда Сам Бог».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Нужно любить Россию»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"в монастырь идут одни, которых уже позвал туда Сам Бог"}]},{"id":"r03b4a2ba07","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Через что, по Гоголю, человек приходит к любви к Богу?","options":["через любовь к братьям","через строгий пост","через уединённую молитву","через чтение отцов Церкви"],"explanation":"Трудно полюбить невидимого Бога, но Христос открыл тайну, «что в любви к братьям получаем любовь к Богу». Поэтому Гоголь советует идти в мир.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Нужно любить Россию»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"что в любви к братьям получаем любовь к Богу"}]},{"id":"rbd0c367d5a","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Какое звание Гоголь называет высшим в главе «Нужно проездиться по России»?","options":["монашеское","царское","писательское","священническое"],"explanation":"«Нет выше званья, как монашеское», — пишет Гоголь, но без зова Божьего его не принять, а чтобы удалиться от мира, нужно уметь с ним распроститься.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Нужно проездиться по России»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Нет выше званья, как монашеское"}]},{"id":"r682a1b6d76","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что, по совету Гоголя, помещик должен сделать перед крестьянами, чтобы показать, что деньги ему не нужны?","options":["сжечь ассигнации","раздать им серебро","простить им долги","отдать им свою землю"],"explanation":"Гоголь советует «русскому помещику» доказать мужикам, что они трудятся не для его удовольствий: «в доказательство тут же сожги ты перед ними ассигнации».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Русской помещик»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"и в доказательство тут же сожги ты перед ними ассигнации"}]},{"id":"r5ace15d73b","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь называет суд в главе «Сельский суд и расправа»?","options":["Божьим делом","царской милостью","барской обязанностью","мирской заботой"],"explanation":"Гоголь советует помещице не поручать суд управителю: «Суд — Божье дело, и я не знаю, что может быть этого выше».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Сельский суд и расправа»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Суд -- Божье дело, и я не знаю, что может быть этого выше"}]},{"id":"r6be622c51f","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"О каком художнике Гоголь пишет отдельную главу «Выбранных мест»?","options":["об Александре Иванове","о Карле Брюллове","об Алексее Венецианове","об Оресте Кипренском"],"explanation":"Глава «Исторический живописец Иванов» начинается словами: «Пишу к вам об Иванове. Что за непостижимая судьба этого человека!»","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Исторический живописец Иванов»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Пишу к вам об Иванове. Что за непостижимая судьба этого человека"}]},{"id":"r5493d0047f","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Чем, по Гоголю, вызвано то, что петербургская молодёжь подносила золотые венки чужеземным певцам, когда в России голодали губернии?","options":["общей нам всем беспечностью","глупостью столичной молодёжи","ожесточением сердец богачей","светским легкомыслием"],"explanation":"Это происходит, по Гоголю, «не от глупости и не от ожесточения сердец, даже и не от легкомыслия», а от «от всем нам общей человеческой беспечности»: несчастья голода далеки от нас и не перед нашими глазами.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О помощи бедным»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Это происходит не от глупости и не от ожесточения сердец, даже и не от легкомыслия"}]},{"id":"r7de45b4a5c","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Каким, по Гоголю, может быть влияние женщины на общество «именно теперь»?","options":["очень великим","совсем ничтожным","только домашним","только вредным"],"explanation":"Собеседница думает, что не может влиять на общество, а Гоголь отвечает: «Влияние женщины может быть очень велико, именно теперь», при охлаждении душевном и утомлённой образованности.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Женщина в свете»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Влияние женщины может быть очень велико, именно теперь"}]},{"id":"r17a3392625","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Почему, по Гоголю, у нас необходимы публичные чтения?","options":["мы охотнее действуем сообща","у нас мало книжных лавок и журналов","простой народ у нас ещё неграмотен","так принято в просвещённой Европе"],"explanation":"Гоголь рад публичным чтениям: «Мы как-то охотней готовы действовать сообща, даже и читать; поодиночке из нас» каждый скорее ленится.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Чтения русских поэтов перед публикою»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Мы как-то охотней готовы действовать сообща, даже и читать"}]},{"id":"r5d35b46cfc","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь пишет о своём состоянии в главе «Значение болезней»?","options":["силы слабеют ежеминутно, но не дух","тело крепнет, но дух изнемогает","силы и дух слабеют вместе","болезнь отступила, и дух окреп"],"explanation":"Глава начинается словами: «Силы мои слабеют ежеминутно, но не дух. Никогда ещё телесные недуги не были так изнурительны».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Значение болезней»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Силы мои слабеют ежеминутно, но не дух"}]},{"id":"r5bbd7146e6","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Почему Гоголь, по его словам, «напал» на жену, а не на мужа, в главе «Чем может быть жена для мужа»?","options":["женщина скорей способна очнуться и двинуться","жена больше виновата в их общем положении","муж всё равно не станет его слушать","жена старше и разумнее своего мужа"],"explanation":"Гоголь решает «напасть» на жену, потому что «женщина скорей способна очнуться и двинуться».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Чем может быть жена для мужа в простом домашнем быту»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"женщина скорей способна очнуться и двинуться"}]},{"id":"r659cef692f","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь отвечает на письмо, которое корреспондент просил «сей же час истребить» и передать ответ лишь через верные руки?","options":["отвечает в печатной книге","отвечает устно при встрече","сжигает письмо без ответа","отвечает через духовника"],"explanation":"Гоголь пишет, что отвечает «не только не по секрету, но, как вы видите, в печатной книге, которую, может быть, прочтёт половина грамотной России».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Страхи и ужасы России»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"я отвечаю не только не по секрету, но, как вы видите, в печатной книге"}]},{"id":"r3404129fed","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что Гоголь говорит выводам «близорукого приятеля» о событиях?","options":["они гниль, ибо сделаны без Бога","они верны, но преждевременны","они остроумны, но неглубоки","они взяты из иностранных газет"],"explanation":"«Выводы твои — гниль; они сделаны без Бога», — отвечает Гоголь приятелю, вооружившемуся «взглядом современной близорукости».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Близорукому приятелю»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Выводы твои -- гниль; они сделаны без Бога"}]},{"id":"r81eb33970d","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь возражает приятелю, судящему о России по примеру других стран?","options":["«Россия не Франция»","«Россия не Англия»","«Россия не Германия»","«Россия не Польша»"],"explanation":"Гоголь пишет «близорукому приятелю»: «Россия не Франция; элементы французские не в силах разыграться в России».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Близорукому приятелю»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"ничтожные и мелкие. Россия не Франция"}]},{"id":"re8b3e05c27","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что Гоголь советует человеку, «занимающему важное место», когда ему предлагают должность?","options":["брать во имя Бога всякую должность","отказываться от должностей в столице","брать лишь ту, что по силам","ждать указа самого государя"],"explanation":"Глава начинается словами: «Во имя Бога берите всякую должность, какая б ни была вам предложена, и не смущайтесь ничем».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Занимающему важное место»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Во имя Бога берите всякую должность, какая б ни была вам предложена"}]},{"id":"r3b66e0c1da","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Как Гоголь отвечает на вопрос «чей удел на земле выше»?","options":["участь всех равно завидна","выше всех удел монаха","выше всех удел писателя","выше всех удел государя"],"explanation":"Прежде Гоголь предпочитал одно звание другому, «теперь же вижу, что участь всех равно завидна»: все получат равное воздаяние, как в притче о талантах.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Чей удел на земле выше»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"теперь же вижу, что участь всех равно завидна"}]},{"id":"re1b255e3c6","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"К чему, по Гоголю, больше привязаны русские песни, где «бил самородный ключ» нашей поэзии?","options":["к безграничному разгулу и стремлению","к домашнему быту и хозяйству","к любви и семейному счастью","к истории и подвигам древних князей"],"explanation":"В песнях, по Гоголю, «мало привязанности к жизни и её предметам, но много привязанности к какому-то безграничному разгулу, к стремлению как бы унестись куда-то».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «В чём же наконец существо русской поэзии»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"мало привязанности к жизни и ее предметам, но много привязанности к какому-то безграничному разгулу"}]},{"id":"r32ef7168f7","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"К какому празднику, по Гоголю, у русского человека «особенное участие»?","options":["к Светлому Воскресенью","к Рождеству Христову","к Троицину дню","к Крещению Господню"],"explanation":"Последняя глава книги начинается словами: «В русском человеке есть особенное участие к празднику Светлого Воскресенья», которое он особенно чувствует на чужбине.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Светлое Воскресенье»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"В русском человеке есть особенное участие к празднику Светлого Воскресенья"}]},{"id":"r716e5e02ca","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"В чём, по Гоголю, суть праздника Светлого Воскресенья, если не в видимых знаках?","options":["взглянуть на человека как на драгоценность","отстоять всенощную и пасхальный крестный ход","раздать милостыню всем нищим города","примириться с родными и соседями"],"explanation":"«Нет, не в видимых знаках дело… но в том, чтобы в самом деле взглянуть в этот день на человека, как на лучшую свою драгоценность».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Светлое Воскресенье»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"взглянуть в этот день на человека, как на лучшую свою драгоценность"}]},{"id":"r9d61bc9223","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Какой пословицей Гоголь объясняет появление «преглупой бумаги», вышедшей «из такого угла, откуда и подозревать никто не мог»?","options":["«Писал писачка, а имя ему собачка»","«Что написано пером, не вырубишь топором»","«Бумага всё стерпит»","«Без бумажки ты букашка»"],"explanation":"Гоголь объясняет, что умный начальник подписывает глупые бумаги, составленные мелкими писцами, «по пословице: „Писал писачка, а имя ему собачка“».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «О театре, об одностороннем взгляде на театр»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"по пословице: Писал писачка, а имя ему собачка"}]},{"id":"r96e7006d32","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что, по Гоголю, нужно уметь, чтобы приобрести право удалиться от мира?","options":["распроститься с миром","переспорить мир","возненавидеть мир","забыть о мире"],"explanation":"Без зова Божьего монашества не принять, пишет Гоголь: «Чтобы приобресть право удалиться от мира, нужно уметь распроститься с миром».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Нужно проездиться по России»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Чтобы приобресть право удалиться от мира, нужно уметь распроститься с миром"}]},{"id":"r166011c876","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что Гоголь советует губернаторше, возвращающейся в свой губернский город?","options":["с новыми силами возлюбить его как вверенный ей","уехать из него в столицу при первой возможности","держаться подальше от местного общества","заняться одними благотворительными балами"],"explanation":"«Вы должны с новыми силами возлюбить его, — он ваш, он вверен вам, он должен быть вашим родным», — пишет Гоголь губернаторше.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Что такое губернаторша»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Вы должны с новыми силами возлюбить его, -- он ваш, он вверен вам"}]},{"id":"rb23b282cf3","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Кто, по Гоголю, виноват в том, что исчезли прежние узы между барином и мужиками?","options":["сами помещики","сами крестьяне","столичные чиновники","городские торговцы"],"explanation":"Гоголь пишет «русскому помещику»: что прежние узы исчезли — правда, «что виноваты тому сами помещики, это также правда», но исчезли они не навсегда.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Русской помещик»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"что виноваты тому сами помещики, это также правда"}]},{"id":"rdf6ecf8135","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Что, по Гоголю, укрепит владелица деревни, если сама будет вершить сельский суд?","options":["разорванную связь барина с мужиками","своё хозяйство и доходы всего имения","уважение губернского начальства к себе","порядок в своём церковном приходе"],"explanation":"Гоголь советует не поручать суд управителю: «Этим одним вы укрепите разорванную связь помещика с крестьянами».","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Сельский суд и расправа»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"Этим одним вы укрепите разорванную связь помещика с крестьянами"}]},{"id":"r266ddd9988","s":2,"topic":"Гоголь. «Выбранные места из переписки с друзьями»","text":"Для кого, по Гоголю, повествование «Одиссеи» имеет «равную заманчивость»?","options":["для всякого, будь то дворянин или лакей","лишь для знатоков древних языков","прежде всего для детей и юношества","лишь для поэтов и художников"],"explanation":"«Одиссея» передаёт «простую правду человеческого похождения, имеющего равную заманчивость для всякого человека, кто бы он ни был»: дворянина, купца, солдата, лакея, ребёнка.","sources":[{"title":"Гоголь. Выбранные места из переписки с друзьями, гл. «Об Одиссее, переводимой Жуковским»","url":"http://az.lib.ru/g/gogolx_n_w/text_0160.shtml","quote":"имеющего равную заманчивость для всякого человека, кто бы он ни был"}]},{"id":"r8f8ce671d0","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Чем, по словам Белинского, ещё можно было бы пренебречь, в отличие от оскорблённого чувства истины?","options":["оскорблённым самолюбием","оскорблённой верой","оскорблённой дружбой","оскорблённым патриотизмом"],"explanation":"«Оскорблённое чувство самолюбия ещё можно перенести… Но нельзя перенести оскорблённого чувства истины, человеческого достоинства».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Оскорбленное чувство самолюбия еще можно перенести"}]},{"id":"re87429bd36","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Под покровом чего и под защитой чего, по Белинскому, в книге Гоголя проповедуют ложь как истину?","options":["религии и кнута","науки и закона","народности и старины","искусства и вкуса"],"explanation":"«Нельзя умолчать, когда под покровом религии и защитою кнута проповедуют ложь и безнравственность как истину и добродетель».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"под покровом религии и защитою кнута проповедуют ложь и безнравственность"}]},{"id":"r7198e36335","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"В чём, по Белинскому, Россия видит своё спасение?","options":["в успехах цивилизации и просвещения","в мистицизме, аскетизме и пиетизме","в возврате к допетровской старине","в укреплении власти и Церкви"],"explanation":"Россия видит спасение «не в мистицизме, не в аскетизме, не в пиетизме, а в успехах цивилизации, просвещения гуманности».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"а в успехах цивилизации, просвещения гуманности"}]},{"id":"rdf2b1ab06a","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Что, по Белинскому, прежде всего нужно России вместо проповедей и молитв?","options":["пробуждение в народе человеческого достоинства","новое и лучшее устройство приходов","строгая и внимательная духовная цензура","скорое возвращение к старым обычаям"],"explanation":"Ей нужны «не проповеди… не молитвы…, а пробуждение в народе чувства человеческого достоинства», права и законы по здравому смыслу.","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"а пробуждение в народе чувства человеческого достоинства"}]},{"id":"r1783c7b8ce","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"С чем должны быть сообразны права и законы в России, по Белинскому?","options":["со здравым смыслом и справедливостью","с учением Церкви и святым преданием","с обычаями предков и седой старины","с волей монарха и знатного дворянства"],"explanation":"Нужны «права и законы, сообразные не с учением церкви, а со здравым смыслом и справедливостью».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"а со здравым смыслом и справедливостью"}]},{"id":"r31f93f5352","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"В каком состоянии, по Белинскому, Россия тревожно занята вопросами о правах и законах?","options":["в «апатическом полусне»","в «тревожном бреду»","в «глубоком обмороке»","в «весеннем пробуждении»"],"explanation":"«Вот вопросы, которыми тревожно занята Россия в её апатическом полусне!»","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Вот вопросы, которыми тревожно занята Россия в ее апатическом полусне"}]},{"id":"r7f004f11df","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"С чем Белинский сравнивает художественные творения Гоголя, давшие России взглянуть на себя?","options":["с зеркалом","с картиной","с летописью","с проповедью"],"explanation":"Гоголь своими творениями содействовал самосознанию России, «давши ей возможность взглянуть на самое себя как будто в зеркале».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"давши ей возможность взглянуть на самое себя как будто в зеркале"}]},{"id":"ra4ecee26a4","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Как Белинский называет Гоголя после «Выбранных мест»?","options":["«Проповедник кнута, апостол невежества»","«Пророк России, учитель всего народа»","«Слуга Церкви, верный друг народа»","«Певец старины, лютый враг прогресса»"],"explanation":"«Проповедник кнута, апостол невежества, поборник обскурантизма и мракобесия, панегирист татарских нравов — что Вы делаете?!»","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Проповедник кнута, апостол невежества, поборник обскурантизма и мракобесия"}]},{"id":"r3fb5e4911e","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Кто, по Белинскому, первым возвестил людям учение свободы, равенства и братства?","options":["Христос","Руссо","Вольтер","Сен-Симон"],"explanation":"«Он первый возвестил людям учение свободы, равенства и братства и мученичество запечатлел… истину своего учения».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Он первый возвестил людям учение свободы, равенства и братства"}]},{"id":"r4775e7a8eb","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"До какого момента, по Белинскому, учение Христа было спасением людей?","options":["пока не организовалось в Церковь","пока не перешло от иудеев к язычникам","пока его не записали в священные книги","пока не пал великий Константинополь"],"explanation":"Учение Христа «только до тех пор и было спасением людей, пока не организовалось в церковь и не приняло за основание принцип ортодоксии».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"пока не организовалось в церковь и не приняло за основание принцип ортодоксии"}]},{"id":"rc9ccbb1943","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Чем, по Белинскому, никогда не было православное духовенство, в отличие от католического?","options":["ничем, кроме слуги светской власти","обличителем самих русских царей","хранителем народной учёности","защитником крестьян от помещиков"],"explanation":"Католическое духовенство «было чем-то», а православное «никогда, ничем и нигде не было, кроме как слугою и рабом светской власти».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"кроме как слугою и рабом светской власти"}]},{"id":"r5b82565740","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Кем, по Белинскому, делается европеец, особенно католик, когда им овладевает религиозный дух?","options":["обличителем неправой власти","смиренным послушником Церкви","верным слугой государя","отшельником, бегущим мира"],"explanation":"Такой человек «делается обличителем неправой власти, подобно еврейским пророкам», тогда как у нас он «земному Богу подкурит больше, чем небесному».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"он делается обличителем неправой власти, подобно еврейским пророкам"}]},{"id":"r82d492fd2e","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Какую мысль Гоголя Белинский называет «византийской»?","options":["что простым людям вредна грамота","что крестьян надо держать в строгом посте","что крестьяне должны чтить помещика","что мужик не способен к истинной вере"],"explanation":"Гоголь утверждал, «будто простому народу грамота не только не полезна, но положительно вредна»: «Да благословит Вас ваш византийский Бог за эту византийскую мысль».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"будто простому народу грамота не только не полезна, но положительно вредна"}]},{"id":"re5f9ac8212","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Где, по Белинскому, в России, несмотря на «татарскую цензуру», ещё есть жизнь и движение вперёд?","options":["только в литературе","только в армии","только в университетах","только в журналистике"],"explanation":"«Только в одной литературе, несмотря на татарскую цензуру, есть ещё жизнь и движение вперёд. Вот почему звание писателя у нас так почтенно».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Только в одной литературе, несмотря на татарскую цензуру"}]},{"id":"r7ca577d748","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Что, по Белинскому, давно затмило в России «мишуру эполет и разноцветных мундиров»?","options":["титло поэта, звание литератора","богатство купца и промышленника","учёная степень и профессорская кафедра","древний род и громкая фамилия"],"explanation":"«Титло поэта, звание литератора у нас давно уже затмило мишуру эполет и разноцветных мундиров».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"давно уже затмило мишуру эполет и разноцветных мундиров"}]},{"id":"r57922e84e1","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Какое влияние книги Гоголя, по признанию Белинского, испугало его?","options":["на правительство и цензуру","на всю русскую публику","на молодых писателей","на сельское духовенство"],"explanation":"«Ваша книга испугала меня возможностью дурного влияния на правительство, на цензуру, но не на публику».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Ваша книга испугала меня возможностью дурного влияния на правительство, на цензуру, но не на публику"}]},{"id":"r49d61f4bd3","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Какой инстинкт, по Белинскому, глубок, хотя ещё не развит, у русского человека?","options":["инстинкт истины","инстинкт свободы","инстинкт веры","инстинкт порядка"],"explanation":"Книгу Гоголя скоро забыли: «Да! У русского человека глубок, хотя и не развит ещё, инстинкт истины!»","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"У русского человека глубок, хотя и не развит еще, инстинкт истины"}]},{"id":"r6f45c9a4e3","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Кто, по Белинскому, «носит Христа в груди своей» и кому незачем ходить в Иерусалим?","options":["кто способен страдать при виде чужого страдания","кто соблюдает все посты и правила Церкви","кто раздал своё имение нищим и бедным","кто удалился от мира в пустынь"],"explanation":"«Кто способен страдать при виде чужого страдания, кому тяжко зрелище угнетения чуждых ему людей, — тот носит Христа в груди своей».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"Кто способен страдать при виде чужого страдания"}]},{"id":"racb4e0c0c6","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Чем, по Белинскому, отзывается проповедуемое Гоголем смирение?","options":["гордыней и унижением своего достоинства","истинной и деятельной любовью к ближнему","подлинным и живым духом древней Церкви","глубокой мудростью восточных отцов"],"explanation":"Смирение Гоголя «отзывается с одной стороны, страшною гордынею, а с другой — самым позорным унижением своего собственного человеческого достоинства».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"отзывается с одной стороны, страшною гордынею"}]},{"id":"rba978c8e3a","s":3,"topic":"Белинский. «Письмо Н. В. Гоголю»","text":"Каким годом датировано «Письмо Н. В. Гоголю» Белинского?","options":["1847","1836","1852","1861"],"explanation":"Письмо помечено: «15-го июля н. с. 1847-го года».","sources":[{"title":"Белинский. Письмо Н. В. Гоголю","url":"http://az.lib.ru/b/belinskij_w_g/text_0040.shtml","quote":"15-го июля н.с. 1847-го года"}]},{"id":"r429074fc26","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"С чем, по Герцену, естествоиспытатели постоянно выходят за пределы, сами того не сознавая?","options":["с пределами опытного знания","с пределами церковного учения","с пределами школьной логики","с пределами здравого смысла"],"explanation":"Естествоиспытатели «только говорят, что они не выходят из эмпирии, а в сущности они почти никогда не остаются в ней».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"естествоиспытатели только говорят, что они не выходят из эмпирии"}]},{"id":"r36cd9924c9","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, идеализм сделал собственно для естествоведения?","options":["ничего","создал опытный метод","открыл законы движения","дал классификацию видов"],"explanation":"«Идеализм собственно для естествоведения ничего не сделал»; он лишь приготовил «бесконечную форму» для будущей науки.","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Идеализм собственно для естествоведения ничего не сделал"}]},{"id":"r600c18027d","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чего, по Герцену, не хотят делать натуралисты, готовые трудиться и рисковать жизнью?","options":["подумать о своей науке","путешествовать в дальние страны","ставить опасные опыты","собирать новые факты"],"explanation":"Натуралисты готовы делать опыты и путешествовать, «но не хотят дать себе труда подумать, порассудить о своей науке».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"но не хотят дать себе труда подумать, порассудить о своей науке"}]},{"id":"r696adc41fb","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Как Герцен называет боязнь натуралистов перед философским размышлением?","options":["«мыслебоязнь»","«умобоязнь»","«логофобия»","«метафизикоборство»"],"explanation":"«Мы уже видели причину этой мыслебоязни»: отвлечённость философии оттолкнула естествоиспытателей.","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Мы уже видели причину этой мыслебоязни"}]},{"id":"r8ea3272a2f","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, начинают понимать мыслители и натуралисты?","options":["что им друг без друга нет выхода","что их пути навсегда разошлись","что спор решит один опыт","что истина лишь в Писании"],"explanation":"«Мыслители и натуралисты начинают понимать, что им друг без друга нет выхода».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Мыслители и натуралисты начинают понимать, что им друг без друга нет выхода"}]},{"id":"r8972d1d54b","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, есть «великая цепь», удерживающая человека в кругу окостенелых понятий?","options":["предрассудки","страсти","привычки","законы"],"explanation":"«Предрассудки — великая цепь, удерживающая человека в определённом, ограниченном кружку окостенелых понятий».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Предрассудки -- великая цепь, удерживающая человека"}]},{"id":"rbd062216f1","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"С кем Герцен сравнивает Шеллинга, только указавшего дорогу, как Вергилий — Данте?","options":["с проводником","с завоевателем","с законодателем","с отшельником"],"explanation":"«Шеллинг, как Виргилий Данту, только указал дорогу, но так указывает и таким перстом — один гений».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Шеллинг, как Виргилий Данту, только указал дорогу"}]},{"id":"r34db891d11","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Кем Герцен называет Шеллинга, овладевающего истиной вдохновенно?","options":["«vates науки»","«Колумбом науки»","«Мирабо науки»","«Аристотелем науки»"],"explanation":"Шеллинг непосредственно и вдохновенно овладевает истиной: «Шеллинг — vates науки», то есть её пророк.","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Шеллинг -- vates науки. Гёте сознавал себя таким, каким он был"}]},{"id":"r4c5b080ab7","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"С кем, по сравнению Эдгара Кине, которое приводит Герцен, сопоставлен Фихте?","options":["с Робеспьером","с Мирабо","с Наполеоном","с Дантоном"],"explanation":"Кине сравнил немецкую философию с французской революцией: «Кант — Мирабо, Фихте — Робеспьер, а Шеллинг — Наполеон».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Кант -- Мирабо, Фихте -- Робеспьер, а Шеллинг -- Наполеон"}]},{"id":"r1f7fe369cb","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, представляет собой первый пример наукообразного изложения естествоведения?","options":["«Энциклопедия» Гегеля","«Органон» Аристотеля","«Начала» Ньютона","«Космос» Гумбольдта"],"explanation":"«Первый пример наукообразного изложения естествоведения представляет Гегелева „Энциклопедия“».","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Первый пример наукообразного изложения естествоведения представляет Гегелева Энциклопедия"}]},{"id":"rf8cc64851a","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, показал Гегель о германской науке?","options":["предел, дальше которого она не пойдёт","путь к полному примирению с Церковью","её отставание от французской мысли","её зависимость от английской эмпирии"],"explanation":"«Гегель показал предел, далее которого германская наука не пойдёт»; в его учении содержится выход из дуализма и метафизики.","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Гегель показал предел, далее которого германская наука не пойдет"}]},{"id":"r6150ac600f","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"По каким законам, как раскрыл Гегель в изложении Герцена, развиваются природа и жизнь?","options":["по законам логики","по законам механики","по законам случая","по законам морали"],"explanation":"Гегель «раскрыл, что природа, что жизнь развивается по законам логики», и фаза в фазу проследил этот параллелизм.","sources":[{"title":"Герцен. Письма об изучении природы, письмо первое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Он раскрыл, что природа, что жизнь развивается по законам логики"}]},{"id":"re0adeeca4f","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"В чём, по Герцену, состоит дело науки?","options":["в возведении всего сущего в мысль","в собирании и описании фактов","в служении практической пользе","в опровержении старых мнений"],"explanation":"«Дело науки — возведение всего сущего в мысль». Понять предмет — значит раскрыть необходимость его содержания.","sources":[{"title":"Герцен. Письма об изучении природы, письмо второе","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Дело науки -- возведение всего сущего в мысль"}]},{"id":"r513eb1f24f","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Продолжением чего, по Герцену, является история мышления?","options":["развития природы","судеб Церкви","жизни государства","роста языка"],"explanation":"«История мышления — продолжение истории природы: ни человечества, ни природы нельзя понять мимо исторического развития».","sources":[{"title":"Герцен. Письма об изучении природы, письмо второе","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"История мышления -- продолжение истории природы"}]},{"id":"r03668494f1","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по формуле Герцена, «человечественнее», хотя и менее разумно?","options":["история","логика","поэзия","религия"],"explanation":"«Логика — разумнее, история — человечественнее». Поэтому Герцен избирает исторический рассказ о самопознании.","sources":[{"title":"Герцен. Письма об изучении природы, письмо второе","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Логика -- разумнее, история -- человечественнее. Ничего не может быть ошибочнее"}]},{"id":"reed8c51f88","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чьё изречение Герцен предлагает эпиграфом к греческому мышлению?","options":["Протагора","Сократа","Гераклита","Фалеса"],"explanation":"Эпиграфом к греческому мышлению служит изречение Протагора: «Человек — мерило всем вещам».","sources":[{"title":"Герцен. Письма об изучении природы, письмо второе","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Эпиграфом к греческому мышлению прекрасно служит известное изречение Протагора"}]},{"id":"r90b1f2afbf","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чью статью о природе, написанную в 1780 году, Герцен прилагает ко второму письму?","options":["Гёте","Шиллера","Гердера","Новалиса"],"explanation":"Герцен прилагает «небольшую статейку Гёте; она писана в 1780 году»; позже Гёте находил её мысли «слишком юными».","sources":[{"title":"Герцен. Письма об изучении природы, письмо второе","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Прилагаю к этому письму небольшую статейку Гёте"}]},{"id":"rc5ee5bd146","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по приложенной Герценом статье о природе, есть «венец» природы?","options":["любовь","смерть","разум","красота"],"explanation":"«Венец её — любовь. Любовью только приближаются к ней».","sources":[{"title":"Герцен. Письма об изучении природы, письмо второе, приложение","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Венец ее -- любовь. Любовью только приближаются к ней"}]},{"id":"rc258109fd1","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, Восток имел вместо науки?","options":["фантазию","богословие","математику","законы"],"explanation":"«Восток не имел науки; он жил фантазией и никогда не устанавливался» настолько, чтобы привести в ясность свою мысль.","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"он жил фантазией и никогда не устанавливался"}]},{"id":"ra1e715ac51","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, есть Иония?","options":["начало Греции и конец Азии","колыбель римского права","родина пифагорейцев","центр эллинистической науки"],"explanation":"Первый свободный шаг мышления совершился, когда человек выдвинулся из Азии: «Иония — начало Греции и конец Азии».","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Иония -- начало Греции и конец Азии"}]},{"id":"rc4ed772e12","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Кто, по Герцену, поставил началом мысль, разум — «нус»?","options":["Анаксагор","Гераклит","Парменид","Демокрит"],"explanation":"«Анаксагор поставил началом мысль. Разум, всеобщее делается сущностью, деятельным двигателем».","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Анаксагор поставил началом мысль. Разум, всеобщее делается сущностью"}]},{"id":"r8865dcd387","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, было у Сократа вместо системы?","options":["метода","миф","школа","догма"],"explanation":"«У Сократа нет системы, а есть метода»; она состоит «в развитии самомышления».","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"У Сократа нет системы, а есть метода"}]},{"id":"r2c587fe287","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"В чём, по Герцену, состоял переворот, сделанный Сократом в мышлении?","options":["мысль стала сама себе предметом","мысль обратилась к изучению природы","мысль подчинилась богам полиса","мысль отказалась от поиска истины"],"explanation":"«Переворот, сделанный Сократом в мышлении, состоял именно в том, что мысль стала сама себе предметом».","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"состоял именно в том, что мысль стала сама себе предметом"}]},{"id":"r81c0468c19","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Каким, по Герцену, было воззрение Платона на природу?","options":["больше поэтико-созерцательным","строго опытным и точным","чисто математическим","механическим и атомистическим"],"explanation":"«Воззрение Платона на природу было больше поэтико-созерцательное, нежели спекулятивно-наукообразное».","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Воззрение Платона на природу было больше поэтико-созерцательное"}]},{"id":"r720b1873e2","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Кого Герцен называет эмпириком «в высшем смысле слова»?","options":["Аристотеля","Демокрита","Эпикура","Платона"],"explanation":"«Аристотель — в высшем смысле слова эмпирик»: он всё берёт из окружающей среды, но взятое не теряет у него связи.","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Аристотель -- в высшем смысле слова эмпирик"}]},{"id":"r279c808aad","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"В чём, по Герцену, Аристотель ищет истину предмета?","options":["в его цели","в его веществе","в его числе","в его имени"],"explanation":"«Аристотель ищет истину предмета в его цели; по цели стремится он определить причину».","sources":[{"title":"Герцен. Письма об изучении природы, письмо третье","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Аристотель ищет истину предмета в его цели"}]},{"id":"r597a0e7745","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Каким, по Герцену, был Эпикур в своём отношении к природе?","options":["атомистом и эмпириком","мистиком и пифагорейцем","скептиком и ритором","идеалистом и платоником"],"explanation":"«Эпикур был атомист и эмпирик — почти так же, как естествоиспытатели прошлого века и отчасти нашего».","sources":[{"title":"Герцен. Письма об изучении природы, письмо четвёртое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Эпикур был атомист и эмпирик"}]},{"id":"r59bc40b6fb","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по словам Эпикура в изложении Герцена, «должно предпочитать» безумному счастью?","options":["разумное несчастье","спокойную бедность","суровую добродетель","тихую смерть"],"explanation":"Тот, кто находит наслаждение в добродетели, может сказать, как Эпикур: «Должно предпочитать разумное несчастие безумному счастию».","sources":[{"title":"Герцен. Письма об изучении природы, письмо четвёртое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Должно предпочитать разумное несчастие безумному счастию"}]},{"id":"rf5cbe1c67f","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Почему, по Герцену, древний мир не имел орудия против скептицизма?","options":["скептицизм был вернее себе, чем все системы","скептицизм опирался на римскую власть","скептицизм был учением народа","скептицизм владел всеми школами"],"explanation":"«Против скептицизма древний мир решительно не имел орудия, потому что скептицизм был вернее себе, нежели все философские системы».","sources":[{"title":"Герцен. Письма об изучении природы, письмо четвёртое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"потому что скептицизм был вернее себе, нежели все философские системы древнего мира"}]},{"id":"r2ae4786a85","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чего, по Герцену, хотелось древним вместо изучения природы?","options":["поэтически ею наслаждаться","подчинить её своей воле","описать её в числах","молиться её силам"],"explanation":"«Не изучать природу, а наслаждаться поэтическим пониманием её — вот чего хотелось древним».","sources":[{"title":"Герцен. Письма об изучении природы, письмо четвёртое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Не изучать природу, а наслаждаться поэтическим пониманием ее"}]},{"id":"rc727a4b67a","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Какое сочинение, по Герцену, показывает рубеж древнего знания о природе?","options":["«Естественная история» Плиния","«Тимей» Платона","«Альмагест» Птолемея","«О природе вещей» Лукреция"],"explanation":"«„Historie Naturalis“ Плиния — энциклопедия, задуманная и выполненная колоссально»; оно показывает рубеж, дальше которого знание не шло.","sources":[{"title":"Герцен. Письма об изучении природы, письмо четвёртое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Historie Naturalis Плиния -- энциклопедия, задуманная и выполненная колоссально"}]},{"id":"rdec9b0a37f","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Каким, по Герцену, является христианство по отношению к древнему порядку вещей?","options":["совершенно противоположным ему","его прямым продолжением","его поздней римской формой","его философским итогом"],"explanation":"«Христианство является совершенно противоположным древнему порядку вещей» — не половинное и бессильное отрицание.","sources":[{"title":"Герцен. Письма об изучении природы, письмо пятое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Христианство является совершенно противоположным древнему порядку вещей"}]},{"id":"rfe5289e452","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"В каком веке, по Герцену, после «тысячелетнего беспокойного сна» человечество собрало силы на новый подвиг мысли?","options":["в XV веке","в XII веке","в XVII веке","в XIII веке"],"explanation":"«Наконец, после тысячелетнего беспокойного сна… в XV веке пробуждаются иные требования, тянет утренним воздухом».","sources":[{"title":"Герцен. Письма об изучении природы, письмо пятое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"в XV веке пробуждаются иные требования, тянет утренним воздухом"}]},{"id":"rb10c48a4fc","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чьи мысли Герцен передаёт как живой пример юношеского мышления эпохи восстания против схоластики?","options":["Джордано Бруно","Николая Кузанского","Томмазо Кампанеллы","Пьетро Помпонацци"],"explanation":"Для примера «одушевлённого юношеского мышления этой эпохи» Герцен передаёт мысли Джордано Бруно, который «оставляет далеко за собою всех товарищей своих».","sources":[{"title":"Герцен. Письма об изучении природы, письмо пятое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"передам вам несколько главных мыслей Джордано Бруно"}]},{"id":"r6b3ba669ce","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"С чем Герцен сравнивает то, как Европа приняла древнюю образованность?","options":["с усвоением Россией при Петре чужой культуры","с усвоением Римом греческой учёности","с усвоением варварами римских законов","с усвоением арабами античной мудрости"],"explanation":"«Европа приняла древнюю образованность, так, как Россия во время Петра I приняла, в свою очередь, образованность европейскую».","sources":[{"title":"Герцен. Письма об изучении природы, письмо пятое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Европа приняла древнюю образованность, так, как Россия во время Петра I приняла"}]},{"id":"r8b6142ef8c","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"От чего, по философии природы Бёма в изложении Герцена, всё возникает?","options":["от «да» и «нет»","от света и тьмы","от огня и воды","от слова и числа"],"explanation":"Основная мысль философии природы Бёма: «Всё возникает от да и нет».","sources":[{"title":"Герцен. Письма об изучении природы, письмо пятое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Все возникает от да и нет"}]},{"id":"r6d87b58317","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Каким, по Герцену, был язык Бёма?","options":["тёмным, безграмотным, но поэтичным","ясным, учёным и строго логичным","сухим, школьным, на манер латыни","лёгким, светским и очень изящным"],"explanation":"«Язык Бёма тёмен, безграмотен, но его резкая и оригинальная речь полна сильной, огненной поэзии».","sources":[{"title":"Герцен. Письма об изучении природы, письмо пятое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Язык Бёма темен, безграмотен, но его резкая и оригинальная речь полна сильной, огненной поэзии"}]},{"id":"r129005c0ac","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Каким восклицанием мореплавателей, по Герцену, Гегель приветствует философию Декарта?","options":["«Земля!»","«Гавань!»","«Берег!»","«Свобода!»"],"explanation":"Гегель пишет: мы дома и, подобно мореплавателям, можем воскликнуть «Земля!». Герцен видит в новой философии берег, который надо покинуть.","sources":[{"title":"Герцен. Письма об изучении природы, письмо шестое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"können wie die Schiffer nach langer Umherfahrt auf der ungestümen See"}]},{"id":"r1e801bdee4","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"На чём, по Герцену, твёрдо стоит наука со времени Декарта?","options":["на самопознающем мышлении","на опыте и наблюдении","на предании и авторитете","на математике и механике"],"explanation":"«Со времени Декарта наука не теряет своей почвы; она твёрдо стоит на самопознающем мышлении, на самозаконности разума».","sources":[{"title":"Герцен. Письма об изучении природы, письмо шестое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"она твердо стоит на самопознающем мышлении, на самозаконности разума"}]},{"id":"rfbf3c463b3","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Каким, по Герцену, был ум Декарта?","options":["математическим и отвлечённым","поэтическим и вдохновенным","практическим и опытным","мистическим и созерцательным"],"explanation":"«Декарт, ум чисто математический и отвлечённый, исключительно механически рассматривал природу».","sources":[{"title":"Герцен. Письма об изучении природы, письмо шестое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Декарт, ум чисто математический и отвлеченный, исключительно механически рассматривал природу"}]},{"id":"r470fdf03f7","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Что, по Герцену, случилось, когда Декарт произнёс своё Cogito, ergo sum?","options":["плотины были прорваны","схоластика окрепла","Церковь его осудила","наука остановилась"],"explanation":"Декарт мог на минуту удержать напор схоластики, но «как только он произнёс своё Cogito, ergo sum — плотины были прорваны».","sources":[{"title":"Герцен. Письма об изучении природы, письмо шестое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"как только он произнес свое Cogito, ergo sum -- плотины были прорваны"}]},{"id":"r80ac396163","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Как, по Герцену, Бэкон перевернул школьное рассуждение о смертности Кая?","options":["человек смертен потому, что Кай смертен","Кай смертен потому, что человек смертен","Кай бессмертен, ибо его душа проста","смертность Кая нельзя доказать"],"explanation":"Схоластика думала, что Кай смертен потому, что человек смертен; Бэкон доказывал, «что мы вправе сказать: человек смертен потому, что Кай смертен».","sources":[{"title":"Герцен. Письма об изучении природы, письмо седьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"человек смертен потому, что Кай смертен"}]},{"id":"r3e2ec77078","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чем, по Герцену, был опыт до Бэкона?","options":["случайностью","основой знания","запретом","искусством"],"explanation":"«До Бэкона опыт был случайностью»; Бэкон возвёл его в необходимый начальный момент ведения.","sources":[{"title":"Герцен. Письма об изучении природы, письмо седьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"До Бэкона опыт был случайностью"}]},{"id":"rb04ea2770b","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"С кем Герцен сравнивает Бэкона, открывшего в науке «новый мир»?","options":["с Колумбом","с Магелланом","с Коперником","с Галилеем"],"explanation":"«Бэкон, как Коломб, открыл в науке новый мир, именно тот, на котором люди стояли спокон века».","sources":[{"title":"Герцен. Письма об изучении природы, письмо седьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Бэкон, как Коломб, открыл в науке новый мир"}]},{"id":"rfc6c845345","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Где, по Герцену, раздался первый сильный протест против исключительно механического воззрения?","options":["в химических лабораториях","в анатомических театрах","на университетских кафедрах","в обсерваториях"],"explanation":"Механическое воззрение не удержалось: «первый сильный протест… раздался в химических лабораториях».","sources":[{"title":"Герцен. Письма об изучении природы, письмо седьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"первый сильный протест против исключительно механического воззрения раздался в химических лабораториях"}]},{"id":"r43545dd739","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Кто, по Герцену, будучи и математиком, и мыслителем, поднялся против механико-материалистического воззрения?","options":["Лейбниц","Ньютон","Паскаль","Спиноза"],"explanation":"«Лейбниц, тоже великий математик, но и великий мыслитель с тем вместе, поднялся против исключительного механико-материалистического воззрения».","sources":[{"title":"Герцен. Письма об изучении природы, письмо седьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Лейбниц, тоже великий математик, но и великий мыслитель с тем вместе"}]},{"id":"re351d26809","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"С чего, по требованию Локка в изложении Герцена, человек должен начать обсуждение своего знания?","options":["с разбора орудий мышления","с изучения Писания","с наблюдения природы","с сомнения во всём"],"explanation":"«Человек должен (по Локку) начать обсуживание своего ведения с разбора орудий мышления». Герцен считает это требование несостоятельным.","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"начать обсуживание своего ведения с разбора орудий мышления"}]},{"id":"r5a5074712d","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чем, по Герцену, была теория чувственного мышления школы Локка?","options":["своего рода механической психологией","новой формой мистического богословия","прямым продолжением учения Декарта","первым опытом диалектического метода"],"explanation":"«Теория чувственного мышления была своего рода механическая психология, как воззрение Ньютона — механическая космология».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"теория чувственного мышления была своего рода механическая психология"}]},{"id":"rc866d6a43b","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Чем, по Юму в изложении Герцена, является достоверность знания?","options":["инстинктом, предрассудком","выводом строгого разума","даром Божьей благодати","плодом общего согласия"],"explanation":"Юм «достоверность считает инстинктом, не подлежащим собственно умозаключению, предрассудком».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"он достоверность считает инстинктом, не подлежащим собственно умозаключению"}]},{"id":"r6ea24ca6ce","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Откуда, по Герцену, реализм перешёл во Францию?","options":["из Англии","из Германии","из Голландии","из Италии"],"explanation":"«Реализм явным образом перешёл во Францию из Англии», вместе с ироническим тоном и теорией себялюбивой полезности.","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Реализм явным образом перешел во Францию из Англии"}]},{"id":"rcef98a4cbf","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Как, по Герцену, англичане и французы поступают с общими и частными вопросами?","options":["англичане общий делают местным, французы частный — общечеловеческим","англичане частный делают общим, французы общий — местным","и те и другие сводят всё к местным вопросам","и те и другие возводят всё в общечеловеческое"],"explanation":"«Всякий общий вопрос делают англичане местным, национальным; всякий местный, частный вопрос становится общечеловеческим у французов».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Всякий общий вопрос делают англичане местным, национальным"}]},{"id":"ra257cd7ac1","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"В чём, по Герцену, Вольтер упрекал Лейбница?","options":["в излишнем глубокомыслии","в безбожии","в легкомыслии","в невежестве"],"explanation":"Французы охотнее читали Рабле и Монтеня, чем Мальбранша: «Сам Вольтер упрекает Лейбница в том, что он слишком глубокомыслен».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Сам Вольтер упрекает Лейбница в том, что он слишком глубокомыслен"}]},{"id":"r65d491f02b","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"О ком, по Герцену, одна дама сказала: «Это человек, который высказал секрет, известный всем»?","options":["о Гельвеции","о Вольтере","о Дидро","о Руссо"],"explanation":"Когда Эльвеций издал книгу «De l'esprit», одна дама заметила: «C'est un homme qui a dit le secret de tout le monde».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Когда Эльвеций издал свою известную книгу De l'esprit, одна дама заметила"}]},{"id":"r8ff1a4b4f5","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Какая книга, по Герцену, при Людовике XIV считалась «страшной», а регент издал её на свой счёт?","options":["«Телемак» Фенелона","«Персидские письма» Монтескьё","«Мысли» Паскаля","«Кандид» Вольтера"],"explanation":"«При Лудовике XIV Фенелонов „Телемак“ считался страшной книгой; регент издал её на свой счёт».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"При Лудовике XIV Фенелонов Телемак считался страшной книгой"}]},{"id":"rf65305eaf0","s":3,"topic":"Герцен. «Письма об изучении природы»","text":"Какими, по Герцену, были энциклопедисты?","options":["односторонними, но не плоскими","глубокими и всесторонними","поверхностными и плоскими","робкими и осторожными"],"explanation":"«Энциклопедисты были односторонни до нелепости, но они не были так плоско поверхностны, как думали об них немцы».","sources":[{"title":"Герцен. Письма об изучении природы, письмо восьмое","url":"http://az.lib.ru/g/gercen_a_i/text_0400-1.shtml","quote":"Энциклопедисты были односторонни до нелепости, но они не были так плоско поверхностны"}]}]};
